var e=(e,t)=>{let n=[...new Set(e)],r=t%n.length;return[...n.slice(r),...n.slice(0,r)]};function t(t){let n=t.phrases.map(([e,n,r,i],a)=>({id:`${t.id}-${a+1}`,hanzi:e,jyutping:n,mandarin:r,note:i})),r=[...t.id].reduce((e,t)=>e+t.charCodeAt(0),0),i=[0,4,8].map((i,a)=>{let o=n[i];return{id:`${t.id}-meaning-${a}`,kind:`meaning`,prompt:`「${o.hanzi}」是什么意思？`,options:e([o.mandarin,n[(i+3)%n.length].mandarin,n[(i+7)%n.length].mandarin],r+a),answer:o.mandarin,explanation:`${o.hanzi}：${o.mandarin}${o.note?` ${o.note}`:``}`}}),a=[1,3,5].map((i,a)=>{let o=n[i],s=n[i-1];return{id:`${t.id}-response-${a}`,kind:`response`,prompt:`对方说「${s.hanzi}」。按本课对话，怎样接下一句？`,options:e([o.hanzi,n[(i+4)%n.length].hanzi,n[(i+8)%n.length].hanzi],r+a+1),answer:o.hanzi,explanation:`本段对话的回应是「${o.hanzi}」，意思是“${o.mandarin}”。`}});return{...t,minutes:t.minutes??12,dialogueLength:t.dialogueLength??8,phrases:n,words:t.words.map(([e,t,n])=>({hanzi:e,jyutping:t,mandarin:n})),patterns:t.patterns.map(([e,t,n])=>({form:e,explanation:t,example:n})),exercises:[i[0],a[0],i[1],a[1],i[2],a[2]]}}var n=[t({id:`first-words-hello`,topicId:`first-words`,level:1,title:`见面打个招呼`,description:`问早、近况、道别`,speakers:[`邻居`,`你`],phrases:[[`早晨！咁早出門口？`,`zou2 san4 gam3 zou2 ceot1 mun4 hau2`,`早上好！这么早出门？`],[`係呀，我返工呀。`,`hai6 aa3 ngo5 faan1 gung1 aa3`,`是啊，我去上班。`],[`你最近點呀？`,`nei5 zeoi3 gan6 dim2 aa3`,`你最近怎么样？`],[`幾好呀，你呢？`,`gei2 hou2 aa3 nei5 ne1`,`挺好的，你呢？`],[`我都幾好，今日有啲忙。`,`ngo5 dou1 gei2 hou2 gam1 jat6 jau5 di1 mong4`,`我也挺好，今天有点忙。`],[`咁你忙先啦。`,`gam2 nei5 mong4 sin1 laa1`,`那你先忙吧。`],[`好呀，遲啲再傾。`,`hou2 aa3 ci4 di1 zoi3 king1`,`好啊，晚点再聊。`],[`拜拜，聽日見！`,`baai1 baai3 ting1 jat6 gin3`,`再见，明天见！`],[`你好，好耐冇見！`,`nei5 hou2 hou2 noi6 mou5 gin3`,`你好，好久不见！`],[`食咗飯未呀？`,`sik6 zo2 faan6 mei6 aa3`,`吃饭了吗？`,`熟人之间的日常寒暄，未必是邀约。`],[`啱啱食完，多謝關心。`,`ngaam1 ngaam1 sik6 jyun4 do1 ze6 gwaan1 sam1`,`刚吃完，谢谢关心。`],[`夜喇，早啲瞓啦。`,`je6 laa3 zou2 di1 fan3 laa1`,`很晚了，早点睡吧。`]],words:[[`早晨`,`zou2 san4`,`早上好`],[`門口`,`mun4 hau2`,`门口`],[`返工`,`faan1 gung1`,`上班`],[`最近`,`zeoi3 gan6`,`最近`],[`幾好`,`gei2 hou2`,`挺好`],[`有啲`,`jau5 di1`,`有一点`],[`遲啲`,`ci4 di1`,`晚一点`],[`傾`,`king1`,`聊天`],[`聽日`,`ting1 jat6`,`明天`],[`好耐`,`hou2 noi6`,`很久`],[`啱啱`,`ngaam1 ngaam1`,`刚刚`],[`瞓`,`fan3`,`睡觉`]],patterns:[[`你最近點呀？`,`用“点”询问近况，句尾“呀”让语气自然。`,`你今日點呀？`],[`遲啲再＋动作`,`表示以后或晚一点再做某事。`,`遲啲再傾。`]],cultureNote:`“早晨”是常见的早间招呼。熟人问“食咗飯未”时，可以简单回答吃过没有，再接一句近况，不必把它理解为请客。`,practicePrompt:`想象你在电梯遇见熟悉的邻居：问好、问近况，再说自己要去上班并道别。`}),t({id:`first-words-introduction`,topicId:`first-words`,level:1,title:`认识新朋友`,description:`姓名、来处、兴趣与联系方式`,speakers:[`新朋友`,`你`],phrases:[[`你好，我叫阿欣，你點稱呼呀？`,`nei5 hou2 ngo5 giu3 aa3 jan1 nei5 dim2 cing1 fu1 aa3`,`你好，我叫阿欣，你怎么称呼？`],[`我叫小林，叫我阿林得喇。`,`ngo5 giu3 siu2 lam4 giu3 ngo5 aa3 lam4 dak1 laa3`,`我叫小林，叫我阿林就行了。`],[`好高興識到你，你邊度嚟㗎？`,`hou2 gou1 hing3 sik1 dou2 nei5 nei5 bin1 dou6 lai4 gaa3`,`很高兴认识你，你从哪里来？`],[`我廣州嚟嘅，啱啱搬嚟香港。`,`ngo5 gwong2 zau1 lai4 ge3 ngaam1 ngaam1 bun1 lai4 hoeng1 gong2`,`我从广州来，刚搬来香港。`],[`你平時鍾意做啲咩呀？`,`nei5 ping4 si4 zung1 ji3 zou6 di1 me1 aa3`,`你平时喜欢做些什么？`],[`我鍾意行山，同埋聽歌。`,`ngo5 zung1 ji3 haang4 saan1 tung4 maai4 teng1 go1`,`我喜欢徒步登山，还有听歌。`],[`咁啱嘅，我都鍾意行山！`,`gam3 ngaam1 ge2 ngo5 dou1 zung1 ji3 haang4 saan1`,`这么巧，我也喜欢徒步登山！`],[`得閒一齊去呀。`,`dak1 haan4 jat1 cai4 heoi3 aa3`,`有空一起去啊。`],[`我仲學緊廣東話。`,`ngo5 zung6 hok6 gan2 gwong2 dung1 waa2`,`我还在学粤语。`],[`我做設計嘅。`,`ngo5 zou6 cit3 gai3 ge3`,`我是做设计的。`],[`我住喺九龍。`,`ngo5 zyu6 hai2 gau2 lung4`,`我住在九龙。`],[`不如加個聯絡方法？`,`bat1 jyu4 gaa1 go3 lyun4 lok3 fong1 faat3`,`不如留个联系方式？`]],words:[[`稱呼`,`cing1 fu1`,`称呼`],[`識`,`sik1`,`认识`],[`邊度`,`bin1 dou6`,`哪里`],[`搬`,`bun1`,`搬家`],[`平時`,`ping4 si4`,`平时`],[`鍾意`,`zung1 ji3`,`喜欢`],[`行山`,`haang4 saan1`,`徒步登山`],[`同埋`,`tung4 maai4`,`还有`],[`得閒`,`dak1 haan4`,`有空`],[`一齊`,`jat1 cai4`,`一起`],[`學緊`,`hok6 gan2`,`正在学`],[`聯絡方法`,`lyun4 lok3 fong1 faat3`,`联系方式`]],patterns:[[`我叫……，叫我……得喇`,`先报姓名，再给出希望对方使用的称呼。`,`我叫陳嘉欣，叫我阿欣得喇。`],[`我鍾意＋活动`,`介绍兴趣后，可以用“你呢”继续话题。`,`我鍾意聽歌，你呢？`]],cultureNote:`“阿”加名字中的一个字是常见的熟人称呼。初次见面先问对方“點稱呼”，再按对方给出的称呼来叫，通常更稳妥。`,practicePrompt:`参加周末活动，向同组的新朋友介绍名字、居住地区和兴趣，再邀请对方一起参加活动。`}),t({id:`first-words-family`,topicId:`first-words`,level:1,title:`家里怎么称呼`,description:`亲属称谓、家庭合照`,speakers:[`朋友`,`你`],phrases:[[`呢張相入面邊個係你呀？`,`ni1 zoeng1 soeng2 jap6 min6 bin1 go3 hai6 nei5 aa3`,`这张照片里哪个是你？`],[`企中間嗰個就係我。`,`kei5 zung1 gaan1 go2 go3 zau6 hai6 ngo5`,`站在中间的那个就是我。`],[`你隔籬嗰兩位呢？`,`nei5 gaak3 lei4 go2 loeng5 wai2 ne1`,`你旁边那两位呢？`],[`佢哋係我阿爸同阿媽。`,`keoi5 dei6 hai6 ngo5 aa3 baa4 tung4 aa3 maa1`,`他们是我爸爸和妈妈。`],[`你有冇兄弟姊妹呀？`,`nei5 jau5 mou5 hing1 dai6 zi2 mui6 aa3`,`你有兄弟姐妹吗？`],[`有呀，我有個家姐同個細佬。`,`jau5 aa3 ngo5 jau5 go3 gaa1 ze1 tung4 go3 sai3 lou2`,`有啊，我有一个姐姐和一个弟弟。`],[`你哋住埋一齊㗎？`,`nei5 dei6 zyu6 maai4 jat1 cai4 gaa3`,`你们住在一起吗？`],[`唔係，家姐搬咗出去住。`,`m4 hai6 gaa1 ze1 bun1 zo2 ceot1 heoi3 zyu6`,`不是，姐姐搬出去住了。`],[`嗰個係我阿哥。`,`go2 go3 hai6 ngo5 aa3 go1`,`那个是我哥哥。`],[`我細妹仲讀緊書。`,`ngo5 sai3 mui2 zung6 duk6 gan2 syu1`,`我妹妹还在上学。`],[`我週末會去探嫲嫲。`,`ngo5 zau1 mut6 wui5 heoi3 taam3 maa4 maa4`,`我周末会去看望奶奶。`],[`我婆婆煮餸好叻。`,`ngo5 po4 po2 zyu2 sung3 hou2 lek1`,`我外婆很会做菜。`]],words:[[`相`,`soeng2`,`照片`],[`中間`,`zung1 gaan1`,`中间`],[`隔籬`,`gaak3 lei4`,`旁边`],[`阿爸`,`aa3 baa4`,`爸爸`],[`阿媽`,`aa3 maa1`,`妈妈`],[`家姐`,`gaa1 ze1`,`姐姐`],[`細佬`,`sai3 lou2`,`弟弟`],[`阿哥`,`aa3 go1`,`哥哥`],[`細妹`,`sai3 mui2`,`妹妹`],[`嫲嫲`,`maa4 maa4`,`奶奶`],[`婆婆`,`po4 po2`,`外婆`],[`探`,`taam3`,`探望`]],patterns:[[`嗰個係我＋称谓`,`指着照片或某个人介绍关系。`,`嗰個係我家姐。`],[`有冇＋人或事物？`,`用肯定与否定并列来问有没有。`,`你有冇兄弟姊妹呀？`]],cultureNote:`香港口语常用“家姐、細佬、細妹”；“嫲嫲”通常指父亲的母亲，“婆婆”通常指母亲的母亲。“婆婆”也可用作对年长女士的称呼，要结合语境理解。`,practicePrompt:`拿一张真实或想象的家庭合照，介绍三位家人，说说他们住哪里、平时做什么。`}),t({id:`first-words-needs`,topicId:`first-words`,level:1,title:`说出自己的需要`,description:`饥渴、疲倦、休息与充电`,speakers:[`你`,`朋友`],phrases:[[`我有啲攰，想坐低抖吓。`,`ngo5 jau5 di1 gui6 soeng2 co5 dai1 tau2 haa5`,`我有点累，想坐下休息一下。`],[`前面有張凳，我哋過去啦。`,`cin4 min6 jau5 zoeng1 dang3 ngo5 dei6 gwo3 heoi3 laa1`,`前面有张椅子，我们过去吧。`],[`好呀，我仲有啲口渴。`,`hou2 aa3 ngo5 zung6 jau5 di1 hau2 hot3`,`好啊，我还有点口渴。`],[`你想飲水定飲茶呀？`,`nei5 soeng2 jam2 seoi2 ding6 jam2 caa4 aa3`,`你想喝水还是喝茶？`],[`我想飲水，唔使冰。`,`ngo5 soeng2 jam2 seoi2 m4 sai2 bing1`,`我想喝水，不用冰。`],[`得，我去幫你買。`,`dak1 ngo5 heoi3 bong1 nei5 maai5`,`好，我去帮你买。`],[`唔該，我想去埋洗手間。`,`m4 goi1 ngo5 soeng2 heoi3 maai4 sai2 sau2 gaan1`,`谢谢，我还想顺便去一下洗手间。`],[`洗手間喺右手邊。`,`sai2 sau2 gaan1 hai2 jau6 sau2 bin1`,`洗手间在右边。`],[`我肚餓喇，想食啲嘢。`,`ngo5 tou5 ngo6 laa3 soeng2 sik6 di1 je5`,`我饿了，想吃点东西。`],[`呢度有啲凍，可唔可以閂冷氣？`,`ni1 dou6 jau5 di1 dung3 ho2 m4 ho2 ji5 saan1 laang5 hei3`,`这里有点冷，可以关空调吗？`],[`我想搵個地方叉電。`,`ngo5 soeng2 wan2 go3 dei6 fong1 caa1 din6`,`我想找个地方充电。`],[`而家唔使住，唔該。`,`ji4 gaa1 m4 sai2 zyu6 m4 goi1`,`现在暂时不用，谢谢。`]],words:[[`攰`,`gui6`,`累`],[`坐低`,`co5 dai1`,`坐下`],[`抖吓`,`tau2 haa5`,`休息一下`],[`前面`,`cin4 min6`,`前面`],[`凳`,`dang3`,`椅子`],[`口渴`,`hau2 hot3`,`口渴`],[`定`,`ding6`,`还是`],[`唔使`,`m4 sai2`,`不用`],[`洗手間`,`sai2 sau2 gaan1`,`洗手间`],[`肚餓`,`tou5 ngo6`,`饿`],[`冷氣`,`laang5 hei3`,`空调`],[`叉電`,`caa1 din6`,`充电`]],patterns:[[`我有啲＋感受`,`“有啲”表达程度较轻的感受。`,`我有啲攰。`],[`我想＋动作`,`直接而清楚地说出自己的需要。`,`我想坐低抖吓。`]],cultureNote:`“唔使住”中的“住”表示暂时，和居住无关。需要帮助时先说“唔該”，再说明具体需要，能让对方更容易回应。`,practicePrompt:`你和朋友逛了一下午，说出两种身体感受，再提出喝水、休息或找洗手间的需要。`}),t({id:`first-words-repeat`,topicId:`first-words`,level:1,title:`听不懂也能接着聊`,description:`语速、重复、字词解释`,speakers:[`你`,`街坊`],phrases:[[`唔好意思，我聽唔清楚。`,`m4 hou2 ji3 si1 ngo5 teng1 m4 cing1 co2`,`不好意思，我没听清楚。`],[`我講多次吖。`,`ngo5 gong2 do1 ci3 aa1`,`我再说一次吧。`],[`可唔可以講慢啲呀？`,`ho2 m4 ho2 ji5 gong2 maan6 di1 aa3`,`可以说慢一点吗？`],[`可以呀，你想問邊度呀？`,`ho2 ji5 aa3 nei5 soeng2 man6 bin1 dou6 aa3`,`可以啊，你想问哪里？`],[`我想問巴士站點去。`,`ngo5 soeng2 man6 baa1 si2 zaam6 dim2 heoi3`,`我想问公交车站怎么走。`],[`行到路口，然後轉左。`,`haang4 dou3 lou6 hau2 jin4 hau6 zyun3 zo2`,`走到路口，然后左转。`],[`即係去到路口轉左，啱唔啱？`,`zik1 hai6 heoi3 dou3 lou6 hau2 zyun3 zo2 ngaam1 m4 ngaam1`,`就是到了路口左转，对吗？`],[`啱喇，轉咗就見到。`,`ngaam1 laa3 zyun3 zo2 zau6 gin3 dou2`,`对了，转过去就看到了。`],[`呢個字點讀呀？`,`ni1 go3 zi6 dim2 duk6 aa3`,`这个字怎么读？`],[`呢句係咩意思呀？`,`ni1 geoi3 hai6 me1 ji3 si1 aa3`,`这句话是什么意思？`],[`可唔可以寫低俾我呀？`,`ho2 m4 ho2 ji5 se2 dai1 bei2 ngo5 aa3`,`可以写下来给我吗？`],[`明白喇，唔該晒！`,`ming4 baak6 laa3 m4 goi1 saai3`,`明白了，非常感谢！`]],words:[[`唔好意思`,`m4 hou2 ji3 si1`,`不好意思`],[`聽唔清楚`,`teng1 m4 cing1 co2`,`听不清楚`],[`講`,`gong2`,`说`],[`多次`,`do1 ci3`,`再一次`],[`慢啲`,`maan6 di1`,`慢一点`],[`問`,`man6`,`问`],[`路口`,`lou6 hau2`,`路口`],[`轉左`,`zyun3 zo2`,`左转`],[`即係`,`zik1 hai6`,`也就是说`],[`啱`,`ngaam1`,`对`],[`寫低`,`se2 dai1`,`写下来`],[`明白`,`ming4 baak6`,`明白`]],patterns:[[`可唔可以＋动作＋啲？`,`礼貌请求对方调整说话方式。`,`可唔可以講慢啲呀？`],[`即係……，啱唔啱？`,`用自己的话复述，确认理解。`,`即係聽日交，啱唔啱？`]],cultureNote:`“聽唔清楚”偏向声音没听清；“唔明”偏向听到了但不理解。说明自己具体卡在哪里，比反复说“唔識”更容易得到有效帮助。`,practicePrompt:`请朋友说一条路线。先请求放慢，再复述路线确认，最后请对方写下目的地名字。`}),t({id:`first-words-polite`,topicId:`first-words`,level:1,title:`把请求说得有礼貌`,description:`借物、求助、致谢与婉拒`,speakers:[`你`,`同学`],phrases:[[`唔該，可唔可以借支筆俾我？`,`m4 goi1 ho2 m4 ho2 ji5 ze3 zi1 bat1 bei2 ngo5`,`请问，可以借我一支笔吗？`],[`可以呀，你用呢支啦。`,`ho2 ji5 aa3 nei5 jung6 ni1 zi1 laa1`,`可以啊，你用这支吧。`],[`唔該晒，我用完即刻還。`,`m4 goi1 saai3 ngo5 jung6 jyun4 zik1 hak1 waan4`,`非常感谢，我用完马上还。`],[`唔使急，我仲有支。`,`m4 sai2 gap1 ngo5 zung6 jau5 zi1`,`不用急，我还有一支。`],[`另外，想請你幫個忙。`,`ling6 ngoi6 soeng2 cing2 nei5 bong1 go3 mong4`,`另外，想请你帮个忙。`],[`咩事呀？`,`me1 si6 aa3`,`什么事？`],[`幫我睇一睇個袋，得唔得？`,`bong1 ngo5 tai2 jat1 tai2 go3 doi2 dak1 m4 dak1`,`帮我看一下包，可以吗？`],[`冇問題，你去啦。`,`mou5 man6 tai4 nei5 heoi3 laa1`,`没问题，你去吧。`],[`唔該，借借。`,`m4 goi1 ze3 ze3`,`劳驾，让一下。`],[`對唔住，我撞到你。`,`deoi3 m4 zyu6 ngo5 zong6 dou2 nei5`,`对不起，我撞到你了。`],[`唔緊要，冇事。`,`m4 gan2 jiu3 mou5 si6`,`没关系，没事。`],[`唔好意思，今次幫唔到你。`,`m4 hou2 ji3 si1 gam1 ci3 bong1 m4 dou2 nei5`,`不好意思，这次没法帮你。`]],words:[[`唔該`,`m4 goi1`,`劳驾；谢谢`],[`借`,`ze3`,`借`],[`支`,`zi1`,`支；笔等的量词`],[`用完`,`jung6 jyun4`,`用完`],[`即刻`,`zik1 hak1`,`马上`],[`還`,`waan4`,`归还`],[`幫個忙`,`bong1 go3 mong4`,`帮个忙`],[`睇`,`tai2`,`看`],[`袋`,`doi2`,`包`],[`冇問題`,`mou5 man6 tai4`,`没问题`],[`對唔住`,`deoi3 m4 zyu6`,`对不起`],[`唔緊要`,`m4 gan2 jiu3`,`没关系`]],patterns:[[`唔該，可唔可以……？`,`先以礼貌语引起注意，再提出请求。`,`唔該，可唔可以幫我開門？`],[`幫我＋动作，得唔得？`,`请求熟人帮忙时，句尾询问对方是否方便。`,`幫我睇一睇，得唔得？`]],cultureNote:`接受日常服务或小帮助，常说“唔該”；收到礼物、祝福或赞美，常说“多謝”。做错事道歉可以说“對唔住”，轻微打扰则常用“唔好意思”。`,practicePrompt:`向同学借一件东西，说明何时归还，再练习接受帮助和礼貌拒绝各一次。`})],r=[t({id:`time-plans-calendar`,topicId:`time-plans`,level:1,title:`今天几号、星期几`,description:`日期、星期与日程`,speakers:[`你`,`朋友`],phrases:[[`今日幾多號呀？`,`gam1 jat6 gei2 do1 hou6 aa3`,`今天几号？`],[`今日十月十二號。`,`gam1 jat6 sap6 jyut6 sap6 ji6 hou6`,`今天十月十二号。`],[`咁今日星期幾呀？`,`gam2 gam1 jat6 sing1 kei4 gei2 aa3`,`那今天星期几？`],[`星期一，聽日就星期二。`,`sing1 kei4 jat1 ting1 jat6 zau6 sing1 kei4 ji6`,`星期一，明天就是星期二。`],[`我哋個活動係咪後日呀？`,`ngo5 dei6 go3 wut6 dung6 hai6 mai6 hau6 jat6 aa3`,`我们的活动是不是后天？`],[`唔係呀，係今個星期五。`,`m4 hai6 aa3 hai6 gam1 go3 sing1 kei4 ng5`,`不是啊，是这星期五。`],[`即係十六號，我記低先。`,`zik1 hai6 sap6 luk6 hou6 ngo5 gei3 dai1 sin1`,`就是十六号，我先记下来。`],[`啱喇，唔好記錯日子。`,`ngaam1 laa3 m4 hou2 gei3 co3 jat6 zi2`,`对了，别记错日期。`],[`尋日我全日都唔得閒。`,`cam4 jat6 ngo5 cyun4 jat6 dou1 m4 dak1 haan4`,`昨天我一整天都没空。`],[`下個月我會放假。`,`haa6 go3 jyut6 ngo5 wui5 fong3 gaa3`,`下个月我会放假。`],[`呢個星期六你得唔得閒？`,`ni1 go3 sing1 kei4 luk6 nei5 dak1 m4 dak1 haan4`,`这个星期六你有空吗？`],[`星期日間舖休息。`,`sing1 kei4 jat6 gaan1 pou3 jau1 sik1`,`星期日这家店休息。`]],words:[[`今日`,`gam1 jat6`,`今天`],[`聽日`,`ting1 jat6`,`明天`],[`後日`,`hau6 jat6`,`后天`],[`尋日`,`cam4 jat6`,`昨天`],[`幾多號`,`gei2 do1 hou6`,`几号`],[`星期幾`,`sing1 kei4 gei2`,`星期几`],[`今個`,`gam1 go3`,`这个`],[`下個月`,`haa6 go3 jyut6`,`下个月`],[`活動`,`wut6 dung6`,`活动`],[`記低`,`gei3 dai1`,`记下来`],[`日子`,`jat6 zi2`,`日期；日子`],[`放假`,`fong3 gaa3`,`放假`]],patterns:[[`今日幾多號／星期幾？`,`“几多号”问日期，“星期几”问一周中的哪一天。`,`聽日星期幾呀？`],[`今個／下個＋时间单位`,`用“今个”与“下个”区分本次和下次。`,`下個星期我放假。`]],cultureNote:`“聽日”是明天，“尋日”是昨天。口头约时间时，补充星期和日期两项，能减少把“今个星期”和“下个星期”听混的机会。本课日期为对话示例。`,practicePrompt:`打开日历，选一个活动日期。用粤语说出月份、几号和星期几，再说明它是今天、明天还是下星期。`}),t({id:`time-plans-clock`,topicId:`time-plans`,level:1,title:`几点钟见面`,description:`整点、半点、一刻与“字”报时`,speakers:[`你`,`朋友`],phrases:[[`而家幾點呀？`,`ji4 gaa1 gei2 dim2 aa3`,`现在几点？`],[`而家兩點半。`,`ji4 gaa1 loeng5 dim2 bun3`,`现在两点半。`],[`套戲幾點開場呀？`,`tou3 hei3 gei2 dim2 hoi1 coeng4 aa3`,`电影几点开场？`],[`三點三個字開場。`,`saam1 dim2 saam1 go3 zi6 hoi1 coeng4`,`三点十五分开场。`,`报时时，一个“字”是五分钟。`],[`即係三點十五分？`,`zik1 hai6 saam1 dim2 sap6 ng5 fan1`,`就是三点十五分？`],[`係呀，我哋三點正入場啦。`,`hai6 aa3 ngo5 dei6 saam1 dim2 zing3 jap6 coeng4 laa1`,`是啊，我们三点整入场吧。`],[`好，仲有半個鐘。`,`hou2 zung6 jau5 bun3 go3 zung1`,`好，还有半个小时。`],[`我哋行過去啱啱好。`,`ngo5 dei6 haang4 gwo3 heoi3 ngaam1 ngaam1 hou2`,`我们走过去刚刚好。`],[`朝早八點我返工。`,`ziu1 zou2 baat3 dim2 ngo5 faan1 gung1`,`我早上八点上班。`],[`下晝五點我收工。`,`haa6 zau3 ng5 dim2 ngo5 sau1 gung1`,`我下午五点下班。`],[`夜晚十點之前返到屋企。`,`je6 maan5 sap6 dim2 zi1 cin4 faan1 dou3 uk1 kei2`,`晚上十点之前回到家。`],[`差五分鐘就六點。`,`caa1 ng5 fan1 zung1 zau6 luk6 dim2`,`差五分钟就六点。`]],words:[[`而家`,`ji4 gaa1`,`现在`],[`幾點`,`gei2 dim2`,`几点`],[`半`,`bun3`,`半`],[`開場`,`hoi1 coeng4`,`开场`],[`字`,`zi6`,`报时中的五分钟`],[`正`,`zing3`,`整点的“整”`],[`入場`,`jap6 coeng4`,`入场`],[`半個鐘`,`bun3 go3 zung1`,`半小时`],[`朝早`,`ziu1 zou2`,`早上`],[`下晝`,`haa6 zau3`,`下午`],[`夜晚`,`je6 maan5`,`晚上`],[`之前`,`zi1 cin4`,`之前`]],patterns:[[`几点＋几个字`,`一个“字”是五分钟；三个字是十五分钟，九个字是四十五分钟。`,`四點九個字。`],[`时间＋之前／之後`,`给出动作发生的时间界限。`,`六點之前返到屋企。`]],cultureNote:`“兩點”里的“两”用“兩”，一般不说“二點”。报时时“字”的说法很常见；还不熟悉时，可以复述成“十五分、四十五分”来确认。`,practicePrompt:`选三件明天要做的事，分别用整点、半点和“几个字”说出时间，并补上早上、下午或晚上。`}),t({id:`time-plans-duration`,topicId:`time-plans`,level:1,title:`要多久、多久一次`,description:`时长、频率与日常习惯`,speakers:[`朋友`,`你`],phrases:[[`你返工要幾耐呀？`,`nei5 faan1 gung1 jiu3 gei2 noi6 aa3`,`你上班路上要多久？`],[`搭車大概要四十分鐘。`,`daap3 ce1 daai6 koi3 jiu3 sei3 sap6 fan1 zung1`,`坐车大概要四十分钟。`],[`咁你平時幾耐做一次運動？`,`gam2 nei5 ping4 si4 gei2 noi6 zou6 jat1 ci3 wan6 dung6`,`那你平时多久运动一次？`],[`我一個星期做三次。`,`ngo5 jat1 go3 sing1 kei4 zou6 saam1 ci3`,`我一周运动三次。`],[`每次做幾耐呀？`,`mui5 ci3 zou6 gei2 noi6 aa3`,`每次做多久？`],[`通常一個鐘左右。`,`tung1 soeng4 jat1 go3 zung1 zo2 jau6`,`通常一小时左右。`],[`你做咗幾耐喇？`,`nei5 zou6 zo2 gei2 noi6 laa3`,`你坚持多久了？`],[`差唔多半年喇。`,`caa1 m4 do1 bun3 nin4 laa3`,`差不多半年了。`],[`我每日都會行半個鐘。`,`ngo5 mui5 jat6 dou1 wui5 haang4 bun3 go3 zung1`,`我每天都会走半小时。`],[`我間中先去一次。`,`ngo5 gaan3 zung1 sin1 heoi3 jat1 ci3`,`我偶尔才去一次。`],[`等多陣，十分鐘就得。`,`dang2 do1 zan6 sap6 fan1 zung1 zau6 dak1`,`再等一会儿，十分钟就行。`],[`唔使咁耐，好快就到。`,`m4 sai2 gam3 noi6 hou2 faai3 zau6 dou3`,`不用那么久，很快就到。`]],words:[[`幾耐`,`gei2 noi6`,`多久`],[`大概`,`daai6 koi3`,`大概`],[`分鐘`,`fan1 zung1`,`分钟`],[`運動`,`wan6 dung6`,`运动`],[`每次`,`mui5 ci3`,`每次`],[`通常`,`tung1 soeng4`,`通常`],[`一個鐘`,`jat1 go3 zung1`,`一小时`],[`左右`,`zo2 jau6`,`左右；上下`],[`差唔多`,`caa1 m4 do1`,`差不多`],[`半年`,`bun3 nin4`,`半年`],[`間中`,`gaan3 zung1`,`偶尔`],[`陣`,`zan6`,`一会儿`]],patterns:[[`要＋时长`,`表示完成某件事需要的时间。`,`搭車要半個鐘。`],[`一個星期＋动作＋次数`,`交代一段时间内的频率。`,`我一個星期游兩次水。`]],cultureNote:`“幾點”问时间点，“幾耐”问时长。“一個鐘”是一小时；“一陣”长度不固定，如果赶时间，可以再问“大概幾耐呀”。`,practicePrompt:`介绍你的通勤或做饭时间，再说一种爱好每周做几次、每次多久。`}),t({id:`time-plans-meet`,topicId:`time-plans`,level:1,title:`约定时间地点`,description:`碰面时间、地点与联系方式`,speakers:[`你`,`朋友`],phrases:[[`你星期六得唔得閒呀？`,`nei5 sing1 kei4 luk6 dak1 m4 dak1 haan4 aa3`,`你星期六有空吗？`],[`下晝得閒，咩事呀？`,`haa6 zau3 dak1 haan4 me1 si6 aa3`,`下午有空，什么事？`],[`不如一齊去睇展覽？`,`bat1 jyu4 jat1 cai4 heoi3 tai2 zin2 laam5`,`不如一起去看展览？`],[`好呀，幾點喺邊度等？`,`hou2 aa3 gei2 dim2 hai2 bin1 dou6 dang2`,`好啊，几点在哪里碰面？`],[`兩點喺尖沙咀站等，得唔得？`,`loeng5 dim2 hai2 zim1 saa1 zeoi2 zaam6 dang2 dak1 m4 dak1`,`两点在尖沙咀站碰面，行吗？`],[`得呀，邊個出口呀？`,`dak1 aa3 bin1 go3 ceot1 hau2 aa3`,`行啊，哪个出口？`],[`A 出口，出咗閘先等。`,`ei1 ceot1 hau2 ceot1 zo2 zaap6 sin1 dang2`,`A出口，出闸以后再等。`],[`好，到咗就打俾你。`,`hou2 dou3 zo2 zau6 daa2 bei2 nei5`,`好，到了就给你打电话。`],[`你幾點方便呀？`,`nei5 gei2 dim2 fong1 bin6 aa3`,`你几点方便？`],[`我晏晝之前都得。`,`ngo5 aan3 zau3 zi1 cin4 dou1 dak1`,`我中午之前都可以。`],[`咁就講好喇。`,`gam2 zau6 gong2 hou2 laa3`,`那就说定了。`],[`到時見，唔好蕩失路呀！`,`dou3 si4 gin3 m4 hou2 dong6 sat1 lou6 aa3`,`到时见，别迷路啊！`,`后半句是熟人之间的轻松打趣。`]],words:[[`得閒`,`dak1 haan4`,`有空`],[`不如`,`bat1 jyu4`,`不如`],[`展覽`,`zin2 laam5`,`展览`],[`等`,`dang2`,`等候；碰面`],[`出口`,`ceot1 hau2`,`出口`],[`出閘`,`ceot1 zaap6`,`出闸`],[`打俾你`,`daa2 bei2 nei5`,`给你打电话`],[`方便`,`fong1 bin6`,`方便`],[`晏晝`,`aan3 zau3`,`中午`],[`講好`,`gong2 hou2`,`说定`],[`到時`,`dou3 si4`,`到时候`],[`蕩失路`,`dong6 sat1 lou6`,`迷路`]],patterns:[[`不如＋一齊＋活动？`,`提出一个供双方考虑的建议。`,`不如一齊食晏？`],[`时间＋喺＋地点＋等`,`把碰面时间和地点一起说清楚。`,`六點喺門口等。`]],cultureNote:`港铁站较大，约见面时通常会再确认出口、闸内还是闸外。“喺某站等”仍不够具体，补一句“出咗閘先等”更容易找到对方。`,practicePrompt:`约朋友周末去看电影：提出活动，商量时间，说明一个真实车站的出口，并约定到达后的联系方法。`}),t({id:`time-plans-reschedule`,topicId:`time-plans`,level:2,title:`迟到与改期`,description:`迟到原因、预计到达时间、改期`,speakers:[`你`,`朋友`],phrases:[[`唔好意思，我可能遲少少。`,`m4 hou2 ji3 si1 ngo5 ho2 nang4 ci4 siu2 siu2`,`不好意思，我可能晚一点。`],[`唔緊要，大概幾點到呀？`,`m4 gan2 jiu3 daai6 koi3 gei2 dim2 dou3 aa3`,`没关系，大概几点到？`],[`塞緊車，應該遲十五分鐘。`,`sak1 gan2 ce1 jing1 goi1 ci4 sap6 ng5 fan1 zung1`,`正在堵车，应该晚十五分钟。`],[`得，我入去搵位先。`,`dak1 ngo5 jap6 heoi3 wan2 wai2 sin1`,`好，我先进去找座位。`],[`好呀，你唔使等我先落單。`,`hou2 aa3 nei5 m4 sai2 dang2 ngo5 sin1 lok6 daan1`,`好啊，你不用等我才点单。`],[`知道，你慢慢嚟。`,`zi1 dou3 nei5 maan6 maan6 lai4`,`知道，你慢慢来。`],[`我到門口喇，你坐邊呀？`,`ngo5 dou3 mun4 hau2 laa3 nei5 co5 bin1 aa3`,`我到门口了，你坐哪儿？`],[`我坐近窗口嗰張枱。`,`ngo5 co5 kan5 coeng1 hau2 go2 zoeng1 toi2`,`我坐靠窗的那张桌子。`],[`今日臨時有事，可唔可以改期？`,`gam1 jat6 lam4 si4 jau5 si6 ho2 m4 ho2 ji5 goi2 kei4`,`今天临时有事，可以改期吗？`],[`改做聽日同一時間，得唔得？`,`goi2 zou6 ting1 jat6 tung4 jat1 si4 gaan3 dak1 m4 dak1`,`改成明天同一时间，可以吗？`],[`我聽日唔得，不如下星期？`,`ngo5 ting1 jat6 m4 dak1 bat1 jyu4 haa6 sing1 kei4`,`我明天不行，不如下星期？`],[`真係唔好意思，要你等咁耐。`,`zan1 hai6 m4 hou2 ji3 si1 jiu3 nei5 dang2 gam3 noi6`,`真不好意思，让你等这么久。`]],words:[[`可能`,`ho2 nang4`,`可能`],[`遲`,`ci4`,`迟`],[`少少`,`siu2 siu2`,`一点点`],[`塞車`,`sak1 ce1`,`堵车`],[`應該`,`jing1 goi1`,`应该`],[`搵位`,`wan2 wai2`,`找座位`],[`落單`,`lok6 daan1`,`点单；下单`],[`窗口`,`coeng1 hau2`,`窗户`],[`枱`,`toi2`,`桌子`],[`臨時`,`lam4 si4`,`临时`],[`改期`,`goi2 kei4`,`改期`],[`同一時間`,`tung4 jat1 si4 gaan3`,`同一时间`]],patterns:[[`應該遲＋时长`,`给出预计迟到多久，让对方能调整安排。`,`應該遲十分鐘。`],[`改做＋新时间，得唔得？`,`提出具体替代时间，方便对方答复。`,`改做星期日朝早，得唔得？`]],cultureNote:`“遲少少”本身不说明晚多久。已经知道大致情况时，补充预计到达时间，并主动说对方可先入座或先点餐，会更体贴。`,practicePrompt:`你原定六点赴约，却遇上堵车。发一段粤语语音说明原因和预计到达时间，再练习把另一次约会改到周末。`}),t({id:`time-plans-weather`,topicId:`time-plans`,level:2,title:`看天气改计划`,description:`晴雨冷热、天气预报与出游安排`,speakers:[`朋友`,`你`],phrases:[[`聽日天氣點呀？`,`ting1 jat6 tin1 hei3 dim2 aa3`,`明天天气怎么样？`],[`天氣預報話會落雨。`,`tin1 hei3 jyu6 bou3 waa6 wui5 lok6 jyu5`,`天气预报说会下雨。`],[`咁仲去唔去海邊呀？`,`gam2 zung6 heoi3 m4 heoi3 hoi2 bin1 aa3`,`那还去不去海边？`],[`如果落雨，不如去博物館。`,`jyu4 gwo2 lok6 jyu5 bat1 jyu4 heoi3 bok3 mat6 gun2`,`如果下雨，不如去博物馆。`],[`好呀，落幾大雨都唔怕。`,`hou2 aa3 lok6 gei2 daai6 jyu5 dou1 m4 paa3`,`好啊，雨再大也不怕。`],[`不過都記得帶遮。`,`bat1 gwo3 dou1 gei3 dak1 daai3 ze1`,`不过还是记得带伞。`],[`館入面會唔會好凍呀？`,`gun2 jap6 min6 wui5 m4 wui5 hou2 dung3 aa3`,`馆里面会不会很冷？`],[`可能會，帶件薄外套穩陣啲。`,`ho2 nang4 wui5 daai3 gin6 bok6 ngoi6 tou3 wan2 zan6 di1`,`可能会，带件薄外套更稳妥。`],[`今日好焗，想搵個地方涼吓。`,`gam1 jat6 hou2 guk6 soeng2 wan2 go3 dei6 fong1 loeng4 haa5`,`今天很闷热，想找个地方凉快一下。`],[`出面起風喇。`,`ceot1 min6 hei2 fung1 laa3`,`外面起风了。`],[`等雨停咗先出門口。`,`dang2 jyu5 ting4 zo2 sin1 ceot1 mun4 hau2`,`等雨停了再出门。`],[`好彩今日出太陽。`,`hou2 coi2 gam1 jat6 ceot1 taai3 joeng4`,`幸好今天出太阳。`]],words:[[`天氣預報`,`tin1 hei3 jyu6 bou3`,`天气预报`],[`落雨`,`lok6 jyu5`,`下雨`],[`海邊`,`hoi2 bin1`,`海边`],[`如果`,`jyu4 gwo2`,`如果`],[`博物館`,`bok3 mat6 gun2`,`博物馆`],[`帶遮`,`daai3 ze1`,`带伞`],[`外套`,`ngoi6 tou3`,`外套`],[`穩陣`,`wan2 zan6`,`稳妥`],[`焗`,`guk6`,`闷热`],[`起風`,`hei2 fung1`,`起风`],[`好彩`,`hou2 coi2`,`幸好`],[`太陽`,`taai3 joeng4`,`太阳`]],patterns:[[`如果……，不如……`,`先说条件，再提出备选计划。`,`如果落雨，不如留喺屋企。`],[`等……咗先＋动作`,`等某个条件满足以后再行动。`,`等雨停咗先出去。`]],cultureNote:`“遮”在这里指雨伞，“焗”形容空气闷热、不通风。香港室内冷气和室外温度可能相差较大，日常聊出游时也常提到带薄外套。`,practicePrompt:`计划一次周末外出：先说天气情况，再分别给出晴天和雨天方案，并提醒朋友带一样物品。`})],i=[t({id:`cafe-order`,topicId:`food-drink`,level:1,minutes:18,dialogueLength:12,title:`茶餐厅第一次落单`,description:`早餐套餐、配蛋与饮品`,speakers:[`店员`,`你`],phrases:[[`早晨，幾位呀？`,`zou2 san4 gei2 wai2 aa3`,`早上好，几位？`],[`一位呀，有冇位？`,`jat1 wai2 aa3 jau5 mou5 wai2`,`一位，有座位吗？`],[`有呀，入面坐。`,`jau5 aa3 jap6 min6 co5`,`有啊，到里面坐。`],[`唔該，可唔可以睇吓餐牌？`,`m4 goi1 ho2 m4 ho2 ji5 tai2 haa5 caan1 paai4`,`请问，可以看一下菜单吗？`],[`呢度有，想食啲咩呀？`,`ni1 dou6 jau5 soeng2 sik6 di1 me1 aa3`,`这里有，想吃点什么？`],[`我要個火腿通粉餐。`,`ngo5 jiu3 go3 fo2 teoi2 tung1 fan2 caan1`,`我要一份火腿通心粉套餐。`],[`配咩蛋呀，炒蛋定煎蛋？`,`pui3 me1 daan2 aa3 caau2 daan2 ding6 zin1 daan2`,`配什么蛋，炒蛋还是煎蛋？`],[`炒蛋，唔該。`,`caau2 daan2 m4 goi1`,`炒蛋，谢谢。`],[`飲咩呀？`,`jam2 me1 aa3`,`喝什么？`],[`熱奶茶，少甜。`,`jit6 naai5 caa4 siu2 tim4`,`热奶茶，少糖。`],[`好，仲有冇其他嘢？`,`hou2 zung6 jau5 mou5 kei4 taa1 je5`,`好，还有别的吗？`],[`暫時唔使，唔該晒。`,`zaam6 si4 m4 sai2 m4 goi1 saai3`,`暂时不用了，非常感谢。`],[`唔該，我想落單。`,`m4 goi1 ngo5 soeng2 lok6 daan1`,`劳驾，我想点单。`],[`呢個餐包唔包飲品？`,`ni1 go3 caan1 baau1 m4 baau1 jam2 ban2`,`这个套餐包不包括饮品？`],[`凍飲要加幾多錢呀？`,`dung3 jam2 jiu3 gaa1 gei2 do1 cin2 aa3`,`冷饮要加多少钱？`],[`可唔可以轉多士？`,`ho2 m4 ho2 ji5 zyun2 do1 si2`,`可以换成吐司吗？`],[`我仲未揀好，等一陣先。`,`ngo5 zung6 mei6 gaan2 hou2 dang2 jat1 zan6 sin1`,`我还没选好，请再等一下。`],[`想問吓，早餐供應到幾點？`,`soeng2 man6 haa5 zou2 caan1 gung1 jing3 dou3 gei2 dim2`,`请问，早餐供应到几点？`]],words:[[`幾位`,`gei2 wai2`,`几位客人`],[`入面`,`jap6 min6`,`里面`],[`餐牌`,`caan1 paai4`,`菜单`],[`落單`,`lok6 daan1`,`点单`],[`火腿`,`fo2 teoi2`,`火腿`],[`通粉`,`tung1 fan2`,`通心粉`],[`炒蛋`,`caau2 daan2`,`炒蛋`],[`煎蛋`,`zin1 daan2`,`煎蛋`],[`熱奶茶`,`jit6 naai5 caa4`,`热奶茶`],[`少甜`,`siu2 tim4`,`少糖；降低甜度`],[`暫時`,`zaam6 si4`,`暂时`],[`飲品`,`jam2 ban2`,`饮品`],[`凍飲`,`dung3 jam2`,`冷饮`],[`多士`,`do1 si2`,`吐司`]],patterns:[[`我要個＋餐名`,`“个”可作一份套餐的口语量词；点饮品常用“杯”。`,`我要個火腿通粉餐。`],[`甲定乙？`,`“定”连接两个供选择的选项。`,`炒蛋定煎蛋？`],[`包唔包＋项目？`,`问某项东西是否已包括在套餐内。`,`呢個餐包唔包飲品？`]],cultureNote:`茶餐厅点套餐时，店员常接着问配蛋和饮品；先看清餐牌再说会更顺畅。冷饮、换配料是否加钱，各店规定不同，可以直接问“要加幾多錢”。“少甜”是减少甜度，不保证完全无糖。`,practicePrompt:`把自己放进一家没去过的茶餐厅：一人入座，点一份套餐，回答配蛋和饮品，再问清一次换配或加价。请换用自己真正想吃的食物。`}),t({id:`food-drink-changes`,topicId:`food-drink`,level:2,title:`少油、走葱与换配菜`,description:`口味要求、配菜更换、过敏提醒`,speakers:[`你`,`店员`],phrases:[[`唔該，我想要個雞扒飯。`,`m4 goi1 ngo5 soeng2 jiu3 go3 gai1 paa2 faan6`,`劳驾，我想要一份鸡排饭。`],[`要咩汁呀？`,`jiu3 me1 zap1 aa3`,`要什么酱汁？`],[`黑椒汁，可唔可以另外上？`,`hak1 ziu1 zap1 ho2 m4 ho2 ji5 ling6 ngoi6 soeng5`,`黑椒汁，可以另外装吗？`],[`可以，仲有咩要求？`,`ho2 ji5 zung6 jau5 me1 jiu1 kau4`,`可以，还有什么要求？`],[`少油，走葱，飯少啲。`,`siu2 jau4 zau2 cung1 faan6 siu2 di1`,`少油，不要葱，米饭少一点。`],[`好，配菜要唔要？`,`hou2 pui3 coi3 jiu3 m4 jiu3`,`好，配菜要不要？`],[`要呀，如果有菜心就最好。`,`jiu3 aa3 jyu4 gwo2 jau5 coi3 sam1 zau6 zeoi3 hou2`,`要啊，如果有菜心就最好了。`],[`今日有，我幫你問吓廚房。`,`gam1 jat6 jau5 ngo5 bong1 nei5 man6 haa5 cyu4 fong2`,`今天有，我帮你问一下厨房。`],[`唔好落辣椒，唔該。`,`m4 hou2 lok6 laat6 ziu1 m4 goi1`,`不要放辣椒，谢谢。`],[`我唔食牛肉，有冇其他選擇？`,`ngo5 m4 sik6 ngau4 juk6 jau5 mou5 kei4 taa1 syun2 zaak6`,`我不吃牛肉，有其他选择吗？`],[`我對花生敏感，呢個餸有冇花生？`,`ngo5 deoi3 faa1 sang1 man5 gam2 ni1 go3 sung3 jau5 mou5 faa1 sang1`,`我对花生过敏，这道菜有没有花生？`],[`唔肯定就唔要喇，唔該。`,`m4 hang2 ding6 zau6 m4 jiu3 laa3 m4 goi1`,`不确定的话就不要了，谢谢。`]],words:[[`雞扒`,`gai1 paa2`,`鸡排`],[`汁`,`zap1`,`酱汁`],[`黑椒`,`hak1 ziu1`,`黑胡椒`],[`另外上`,`ling6 ngoi6 soeng5`,`另装上桌`],[`要求`,`jiu1 kau4`,`要求`],[`少油`,`siu2 jau4`,`少油`],[`走葱`,`zau2 cung1`,`不要葱`],[`配菜`,`pui3 coi3`,`配菜`],[`菜心`,`coi3 sam1`,`菜心`],[`廚房`,`cyu4 fong2`,`厨房`],[`花生`,`faa1 sang1`,`花生`],[`敏感`,`man5 gam2`,`过敏；敏感`]],patterns:[[`可唔可以＋项目＋另外上？`,`要求酱汁或配料分开盛放。`,`可唔可以個汁另外上？`],[`我對＋食材＋敏感`,`明确说明某种食物过敏，再询问菜中是否含有。`,`我對花生敏感。`]],cultureNote:`点餐时“走”常表示不要某种配料，例如“走葱”。“少辣”仍可能有辣椒；过敏应明确说“對某食材敏感”，并请店员核实，不能只说少放。`,practicePrompt:`给一份饭提出两项口味要求，再询问一种食材能否去掉。另练一次清楚说明过敏并询问菜品成分。`}),t({id:`food-drink-dim-sum`,topicId:`food-drink`,level:2,title:`饮茶点几笼点心`,description:`选茶、点心、加单与添水`,speakers:[`店员`,`你`],phrases:[[`兩位飲咩茶呀？`,`loeng5 wai2 jam2 me1 caa4 aa3`,`两位喝什么茶？`],[`香片，唔該。`,`hoeng1 pin2 m4 goi1`,`茉莉花茶，谢谢。`],[`點心紙喺枱面，揀好叫我。`,`dim2 sam1 zi2 hai2 toi2 min6 gaan2 hou2 giu3 ngo5`,`点心单在桌面上，选好了叫我。`],[`我哋要一籠蝦餃同一籠燒賣。`,`ngo5 dei6 jiu3 jat1 lung4 haa1 gaau2 tung4 jat1 lung4 siu1 maai2`,`我们要一笼虾饺和一笼烧卖。`],[`仲要唔要其他點心？`,`zung6 jiu3 m4 jiu3 kei4 taa1 dim2 sam1`,`还要不要其他点心？`],[`加一碟腸粉，同埋一籠叉燒包。`,`gaa1 jat1 dip6 coeng4 fan2 tung4 maai4 jat1 lung4 caa1 siu1 baau1`,`加一碟肠粉，还有一笼叉烧包。`],[`好，夠唔夠食呀？`,`hou2 gau3 m4 gau3 sik6 aa3`,`好，够吃吗？`],[`夠喇，食完先再叫。`,`gau3 laa3 sik6 jyun4 sin1 zoi3 giu3`,`够了，吃完再点。`],[`唔該，加啲熱水。`,`m4 goi1 gaa1 di1 jit6 seoi2`,`劳驾，添点热水。`],[`呢籠入面有幾多件？`,`ni1 lung4 jap6 min6 jau5 gei2 do1 gin6`,`这一笼里面有几件？`],[`有冇素點心呀？`,`jau5 mou5 sou3 dim2 sam1 aa3`,`有素点心吗？`],[`呢個要等幾耐呀？`,`ni1 go3 jiu3 dang2 gei2 noi6 aa3`,`这个要等多久？`]],words:[[`飲茶`,`jam2 caa4`,`喝茶吃点心`],[`香片`,`hoeng1 pin2`,`茉莉花茶`],[`點心紙`,`dim2 sam1 zi2`,`点心单`],[`枱面`,`toi2 min6`,`桌面`],[`籠`,`lung4`,`笼`],[`蝦餃`,`haa1 gaau2`,`虾饺`],[`燒賣`,`siu1 maai2`,`烧卖`],[`碟`,`dip6`,`碟；盘`],[`腸粉`,`coeng4 fan2`,`肠粉`],[`叉燒包`,`caa1 siu1 baau1`,`叉烧包`],[`夠`,`gau3`,`够`],[`件`,`gin6`,`件；点心的量词`]],patterns:[[`一籠／一碟＋食物`,`蒸笼装的点心常按“笼”，盘装的常按“碟”来点。`,`一籠叉燒包同一碟腸粉。`],[`动作＋完先再＋动作`,`表示完成前一件事后再做下一件。`,`食完先再叫。`]],cultureNote:`“飲茶”常指到酒楼喝茶吃点心，不只是喝一杯茶。点心可按笼或碟计，茶位也可能另计；点餐方式和收费以店内餐牌为准。`,practicePrompt:`和一位朋友去饮茶：选一种茶，点三样不同点心，询问一笼有几件，最后请店员添水。`}),t({id:`food-drink-takeaway`,topicId:`food-drink`,level:1,title:`快餐与外卖自取`,description:`堂食外带、取餐号码、餐具`,speakers:[`店员`,`你`],phrases:[[`堂食定外賣呀？`,`tong4 sik6 ding6 ngoi6 maai6 aa3`,`在店里吃还是带走？`],[`外賣，一個叉燒飯。`,`ngoi6 maai6 jat1 go3 caa1 siu1 faan6`,`带走，一份叉烧饭。`],[`要唔要加飲品？`,`jiu3 m4 jiu3 gaa1 jam2 ban2`,`要不要加饮品？`],[`唔使，淨要個飯。`,`m4 sai2 zing6 jiu3 go3 faan6`,`不用，只要饭。`],[`餐具要唔要呀？`,`caan1 geoi6 jiu3 m4 jiu3 aa3`,`要餐具吗？`],[`唔使餐具，我返屋企食。`,`m4 sai2 caan1 geoi6 ngo5 faan1 uk1 kei2 sik6`,`不用餐具，我回家吃。`],[`好，拎住張飛，叫號碼攞餐。`,`hou2 ling1 zyu6 zoeng1 fei1 giu3 hou6 maa5 lo2 caan1`,`好，拿好取餐单，叫到号码来取餐。`],[`唔該，大概要等幾耐？`,`m4 goi1 daai6 koi3 jiu3 dang2 gei2 noi6`,`请问，大概要等多久？`],[`我喺網上落咗單，嚟自取。`,`ngo5 hai2 mong5 soeng6 lok6 zo2 daan1 lai4 zi6 ceoi2`,`我在网上下了单，来店里自取。`],[`訂單號碼係三八六。`,`deng6 daan1 hou6 maa5 hai6 saam1 baat3 luk6`,`订单号码是三八六。`],[`可唔可以個湯分開裝？`,`ho2 m4 ho2 ji5 go3 tong1 fan1 hoi1 zong1`,`汤可以分开装吗？`],[`唔該，幫我封好個蓋。`,`m4 goi1 bong1 ngo5 fung1 hou2 go3 goi3`,`劳驾，帮我盖牢盖子。`]],words:[[`堂食`,`tong4 sik6`,`店内用餐`],[`外賣`,`ngoi6 maai6`,`外带；外卖`],[`叉燒飯`,`caa1 siu1 faan6`,`叉烧饭`],[`淨`,`zing6`,`只；仅`],[`餐具`,`caan1 geoi6`,`餐具`],[`飛`,`fei1`,`票；单据`],[`號碼`,`hou6 maa5`,`号码`],[`攞餐`,`lo2 caan1`,`取餐`],[`網上`,`mong5 soeng6`,`网上`],[`自取`,`zi6 ceoi2`,`自行取货`],[`分開裝`,`fan1 hoi1 zong1`,`分开盛装`],[`蓋`,`goi3`,`盖子`]],patterns:[[`堂食定外賣？`,`询问就餐方式；“外卖”在这里也包括到店购买后带走。`,`外賣，唔該。`],[`淨要＋项目`,`强调只需要某一项。`,`淨要個飯，唔使飲品。`]],cultureNote:`香港点餐中的“外賣”既可指配送，也可指自己带走；“自取”明确表示到店取餐。“飛”可指取餐单，拿到后留意上面的号码。`,practicePrompt:`点一份外带午餐，说明不需要餐具并询问等候时间；再模拟取一份网上订单，报出号码。`}),t({id:`food-drink-drinks`,topicId:`food-drink`,level:1,title:`点一杯合口味的饮品`,description:`冷热、甜度、冰量与咖啡因`,speakers:[`你`,`店员`],phrases:[[`唔該，一杯凍檸茶。`,`m4 goi1 jat1 bui1 dung3 ning2 caa4`,`劳驾，一杯冰柠檬茶。`],[`正常甜度得唔得呀？`,`zing3 soeng4 tim4 dou6 dak1 m4 dak1 aa3`,`正常甜度可以吗？`],[`少甜，少冰，唔該。`,`siu2 tim4 siu2 bing1 m4 goi1`,`少糖，少冰，谢谢。`],[`仲要唔要其他飲品？`,`zung6 jiu3 m4 jiu3 kei4 taa1 jam2 ban2`,`还要不要其他饮品？`],[`再要一杯熱咖啡，唔落糖。`,`zoi3 jiu3 jat1 bui1 jit6 gaa3 fe1 m4 lok6 tong4`,`再要一杯热咖啡，不加糖。`],[`奶要唔要分開呀？`,`naai5 jiu3 m4 jiu3 fan1 hoi1 aa3`,`奶要分开放吗？`],[`要呀，唔該分開俾我。`,`jiu3 aa3 m4 goi1 fan1 hoi1 bei2 ngo5`,`要啊，请分开给我。`],[`好，一杯凍檸茶，一杯熱咖啡。`,`hou2 jat1 bui1 dung3 ning2 caa4 jat1 bui1 jit6 gaa3 fe1`,`好，一杯冰柠檬茶，一杯热咖啡。`],[`呢杯走冰，唔該。`,`ni1 bui1 zau2 bing1 m4 goi1`,`这杯不要冰，谢谢。`],[`有冇唔含咖啡因嘅飲品？`,`jau5 mou5 m4 ham4 gaa3 fe1 jan1 ge3 jam2 ban2`,`有没有不含咖啡因的饮品？`],[`我想要一杯暖水。`,`ngo5 soeng2 jiu3 jat1 bui1 nyun5 seoi2`,`我想要一杯温水。`],[`可唔可以唔要飲管？`,`ho2 m4 ho2 ji5 m4 jiu3 jam2 gun2`,`可以不要吸管吗？`]],words:[[`杯`,`bui1`,`杯`],[`凍檸茶`,`dung3 ning2 caa4`,`冰柠檬茶`],[`甜度`,`tim4 dou6`,`甜度`],[`少甜`,`siu2 tim4`,`少糖`],[`少冰`,`siu2 bing1`,`少冰`],[`熱咖啡`,`jit6 gaa3 fe1`,`热咖啡`],[`落糖`,`lok6 tong4`,`加糖`],[`奶`,`naai5`,`奶`],[`走冰`,`zau2 bing1`,`不加冰`],[`咖啡因`,`gaa3 fe1 jan1`,`咖啡因`],[`暖水`,`nyun5 seoi2`,`温水`],[`飲管`,`jam2 gun2`,`吸管`]],patterns:[[`一杯＋冷热＋饮品`,`先说数量，再说温度和饮品。`,`一杯熱奶茶。`],[`唔落＋配料`,`“落”在制作饮食时可指放入某种材料。`,`唔落糖，唔該。`]],cultureNote:`“少冰”仍有冰，“走冰”则是不放冰。“少甜”和“半糖”不一定是同一标准；如果必须完全不加糖，可直接说“唔落糖”，并确认饮品是否已经预先调甜。`,practicePrompt:`给自己和朋友各点一杯饮品，分别说明冷热、糖量与冰量，再提出一个有关奶或吸管的要求。`}),t({id:`food-drink-bill`,topicId:`food-drink`,level:2,title:`漏单、核单与埋单`,description:`催单、核单与付款`,speakers:[`你`,`店员`],phrases:[[`唔該，我個飯仲未到。`,`m4 goi1 ngo5 go3 faan6 zung6 mei6 dou3`,`劳驾，我的饭还没上。`],[`你叫咗邊款飯呀？`,`nei5 giu3 zo2 bin1 fun2 faan6 aa3`,`你点了哪款饭？`],[`雞扒飯，等咗差唔多半個鐘。`,`gai1 paa2 faan6 dang2 zo2 caa1 m4 do1 bun3 go3 zung1`,`鸡排饭，等了差不多半小时。`],[`唔好意思，我即刻幫你跟。`,`m4 hou2 ji3 si1 ngo5 zik1 hak1 bong1 nei5 gan1`,`不好意思，我马上帮你跟进。`],[`唔該。另外，我想睇吓張單。`,`m4 goi1 ling6 ngoi6 ngo5 soeng2 tai2 haa5 zoeng1 daan1`,`谢谢。另外，我想看一下账单。`],[`好，呢張係你張單。`,`hou2 ni1 zoeng1 hai6 nei5 zoeng1 daan1`,`好，这张是你的账单。`],[`呢杯凍奶茶我冇叫過喎。`,`ni1 bui1 dung3 naai5 caa4 ngo5 mou5 giu3 gwo3 wo3`,`这杯冰奶茶我没点过啊。`],[`對唔住，入錯咗，我幫你改返。`,`deoi3 m4 zyu6 jap6 co3 zo2 ngo5 bong1 nei5 goi2 faan1`,`对不起，录错了，我帮你改过来。`],[`唔該，埋單。`,`m4 goi1 maai4 daan1`,`劳驾，结账。`],[`一共幾多錢呀？`,`jat1 gung6 gei2 do1 cin2 aa3`,`一共多少钱？`],[`可唔可以用八達通？`,`ho2 m4 ho2 ji5 jung6 baat3 daat6 tung1`,`可以用八达通吗？`],[`唔該，俾張收據我。`,`m4 goi1 bei2 zoeng1 sau1 geoi3 ngo5`,`劳驾，给我一张收据。`]],words:[[`仲未`,`zung6 mei6`,`还没`],[`邊款`,`bin1 fun2`,`哪款`],[`跟`,`gan1`,`跟进`],[`單`,`daan1`,`单据；账单`],[`叫過`,`giu3 gwo3`,`点过`],[`入錯`,`jap6 co3`,`录入错误`],[`改返`,`goi2 faan1`,`改回正确状态`],[`埋單`,`maai4 daan1`,`结账`],[`一共`,`jat1 gung6`,`一共`],[`幾多錢`,`gei2 do1 cin2`,`多少钱`],[`八達通`,`baat3 daat6 tung1`,`八达通`],[`收據`,`sau1 geoi3`,`收据`]],patterns:[[`项目＋仲未＋动作`,`指出原本预期发生的事到现在仍未发生。`,`我杯嘢飲仲未到。`],[`我冇＋动作＋過`,`否认曾经做过某件事；核单时可明确指出未点项目。`,`呢個餸我冇叫過。`]],cultureNote:`“埋單”是结账的常用说法，部分店铺需要自己拿单到收银处付款。发现漏单或错单时，说清菜名和账单项目，再请店员核实，比单说“错了”更有效。`,practicePrompt:`假设饭菜迟迟没来，礼貌询问一次；随后发现账单多算了饮品，指出问题，核对后询问付款方式并索取收据。`})],a=[t({id:`shopping-supermarket`,topicId:`shopping`,level:1,title:`超市慢慢揀`,description:`货架位置、优惠与结账`,speakers:[`客人`,`店員`],phrases:[[`唔好意思，牛奶擺喺邊？`,`m4 hou2 ji3 si1, ngau4 naai5 baai2 hai2 bin1?`,`不好意思，牛奶放在哪里？`],[`行到尾轉左就見到。`,`haang4 dou3 mei5 zyun3 zo2 zau6 gin3 dou2.`,`走到尽头左转就能看见。`],[`呢盒牛奶今日有冇特價？`,`ni1 hap6 ngau4 naai5 gam1 jat6 jau5 mou5 dak6 gaa3?`,`这盒牛奶今天有特价吗？`],[`有，買兩盒平五蚊。`,`jau5, maai5 loeng5 hap6 peng4 ng5 man1.`,`有，买两盒便宜五元。`],[`我想要細盒，有冇呢？`,`ngo5 soeng2 jiu3 sai3 hap6, jau5 mou5 ne1?`,`我想要小盒的，有吗？`],[`細盒喺下面嗰層。`,`sai3 hap6 hai2 haa6 min6 go2 cang4.`,`小盒装在下面那层。`],[`多謝。買完嘢去邊度畀錢？`,`do1 ze6. maai5 jyun4 je5 heoi3 bin1 dou6 bei2 cin2?`,`谢谢。买完东西到哪里付款？`],[`出口旁邊有收銀處。`,`ceot1 hau2 pong4 bin1 jau5 sau1 ngan4 cyu3.`,`出口旁边有收银处。`],[`呢款有冇大包裝？`,`ni1 fun2 jau5 mou5 daai6 baau1 zong1?`,`这一款有大包装吗？`],[`唔該畀個購物袋我。`,`m4 goi1 bei2 go3 kau3 mat6 doi2 ngo5.`,`请给我一个购物袋。`],[`我帶咗袋，唔使膠袋。`,`ngo5 daai3 zo2 doi2, m4 sai2 gaau1 doi2.`,`我带了袋子，不需要塑料袋。`],[`呢包嘢幾時到期？`,`ni1 baau1 je5 gei2 si4 dou3 kei4?`,`这包东西什么时候到期？`]],words:[[`牛奶`,`ngau4 naai5`,`牛奶`],[`特價`,`dak6 gaa3`,`特价`],[`一盒`,`jat1 hap6`,`一盒`],[`下面`,`haa6 min6`,`下面`],[`嗰層`,`go2 cang4`,`那一层`],[`收銀處`,`sau1 ngan4 cyu3`,`收银处`],[`包裝`,`baau1 zong1`,`包装`],[`購物袋`,`kau3 mat6 doi2`,`购物袋`],[`膠袋`,`gaau1 doi2`,`塑料袋`],[`到期`,`dou3 kei4`,`到期`]],patterns:[[`……擺喺邊？`,`问商品摆放的位置。`,`洗頭水擺喺邊？`],[`買……平……`,`说明购买数量和减免金额；平在这里读 peng4。`,`買三包平十蚊。`]],cultureNote:`找商品或请店员帮忙先说「唔该」。得到帮助后也可说「唔该晒」；「多谢」常用于接受礼物或好意。超市收银时可以主动说明自己带了袋。`,practicePrompt:`把牛奶换成洗发水或鸡蛋，向店员问位置、包装大小和优惠，最后说明自己带了购物袋。`}),t({id:`shopping-wet-market`,topicId:`shopping`,level:2,title:`街市買今晚餸`,description:`蔬果、斤两与成熟度`,speakers:[`街坊`,`檔主`],phrases:[[`呢啲菜幾多錢一斤？`,`ni1 di1 coi3 gei2 do1 cin2 jat1 gan1?`,`这些菜多少钱一斤？`],[`十蚊一斤，今日好新鮮。`,`sap6 man1 jat1 gan1, gam1 jat6 hou2 san1 sin1.`,`十元一斤，今天很新鲜。`],[`幫我揀兩個番茄，唔該。`,`bong1 ngo5 gaan2 loeng5 go3 faan1 ke2, m4 goi1.`,`请帮我挑两个番茄。`],[`要熟啲定硬啲？`,`jiu3 suk6 di1 ding6 ngaang6 di1?`,`要熟一点的还是硬一点的？`],[`熟啲，今晚煮餸用。`,`suk6 di1, gam1 maan5 zyu2 sung3 jung6.`,`熟一点的，今晚做菜用。`],[`呢兩個啱晒，仲要啲乜？`,`ni1 loeng5 go3 ngaam1 saai3, zung6 jiu3 di1 mat1?`,`这两个正合适，还要什么？`],[`再要半斤菜心，幫我磅埋。`,`zoi3 jiu3 bun3 gan1 coi3 sam1, bong1 ngo5 bong6 maai4.`,`再要半斤菜心，请一起称一下。`],[`好呀，全部二十五蚊。`,`hou2 aa3, cyun4 bou6 ji6 sap6 ng5 man1.`,`好的，一共二十五元。`],[`呢條魚可唔可以幫我切件？`,`ni1 tiu4 jyu2 ho2 m4 ho2 ji5 bong1 ngo5 cit3 gin6?`,`这条鱼可以帮我切块吗？`],[`唔好揀太大個。`,`m4 hou2 gaan2 taai3 daai6 go3.`,`不要挑太大的。`],[`分開兩袋裝，得唔得？`,`fan1 hoi1 loeng5 doi2 zong1, dak1 m4 dak1?`,`分成两袋装，可以吗？`],[`我買少少試吓先。`,`ngo5 maai5 siu2 siu2 si3 haa5 sin1.`,`我先买一点试试。`]],words:[[`街市`,`gaai1 si5`,`菜市场`],[`一斤`,`jat1 gan1`,`一斤`],[`新鮮`,`san1 sin1`,`新鲜`],[`番茄`,`faan1 ke2`,`番茄`],[`熟`,`suk6`,`成熟；熟透`],[`煮餸`,`zyu2 sung3`,`做菜`],[`菜心`,`coi3 sam1`,`菜心`],[`磅`,`bong6`,`称重量`],[`切件`,`cit3 gin6`,`切块`],[`分開`,`fan1 hoi1`,`分开`]],patterns:[[`……幾多錢一斤？`,`把价格和计量单位一起问清楚，也可换成一磅、一个。`,`橙幾多錢一磅？`],[`要……啲定……啲？`,`用定提出两种选择；啲表示程度稍微多一点。`,`要大啲定細啲？`]],cultureNote:`街市计价可能按斤、磅、个或份，先确认单位再说数量。「餸」指配饭的菜，「买餸」就是买做饭用的食材。对话中的价格只是练习情境。`,practicePrompt:`你要买明天煮汤的食材。问价钱和单位，再提出不要太熟、分袋装等两项要求。`}),t({id:`shopping-clothes-sizes`,topicId:`shopping`,level:2,title:`試衫同揀鞋碼`,description:`试衣、松紧与鞋码`,speakers:[`客人`,`店員`],phrases:[[`呢件衫可唔可以試？`,`ni1 gin6 saam1 ho2 m4 ho2 ji5 si3?`,`这件衣服可以试穿吗？`],[`可以，試身室喺入面。`,`ho2 ji5, si3 san1 sat1 hai2 jap6 min6.`,`可以，试衣间在里面。`],[`着上身有啲緊，有冇大一個碼？`,`zoek3 soeng5 san1 jau5 di1 gan2, jau5 mou5 daai6 jat1 go3 maa5?`,`穿上有点紧，有大一号的吗？`],[`有，你想要邊隻色？`,`jau5, nei5 soeng2 jiu3 bin1 zek3 sik1?`,`有，你想要哪种颜色？`],[`深藍色。手袖會唔會太長？`,`sam1 laam4 sik1. sau2 zau6 wui5 m4 wui5 taai3 coeng4?`,`深蓝色。袖子会不会太长？`],[`你試埋呢件，手袖短啲。`,`nei5 si3 maai4 ni1 gin6, sau2 zau6 dyun2 di1.`,`你再试这件，袖子短一点。`],[`呢件啱身，我要呢件。`,`ni1 gin6 ngaam1 san1, ngo5 jiu3 ni1 gin6.`,`这件合身，我要这件。`],[`好呀，我幫你攞件新嘅。`,`hou2 aa3, ngo5 bong1 nei5 lo2 gin6 san1 ge3.`,`好的，我帮你拿一件新的。`],[`呢對鞋有冇三十八碼？`,`ni1 deoi3 haai4 jau5 mou5 saam1 sap6 baat3 maa5?`,`这双鞋有三十八码吗？`],[`鞋頭有啲窄，可唔可以試另一對？`,`haai4 tau4 jau5 di1 zaak3, ho2 m4 ho2 ji5 si3 ling6 jat1 deoi3?`,`鞋头有点窄，可以试另一双吗？`],[`我行幾步試吓先。`,`ngo5 haang4 gei2 bou6 si3 haa5 sin1.`,`我先走几步试试。`],[`有冇同款嘅黑色？`,`jau5 mou5 tung4 fun2 ge3 hak1 sik1?`,`有同款黑色的吗？`]],words:[[`試身室`,`si3 san1 sat1`,`试衣间`],[`着`,`zoek3`,`穿`],[`緊`,`gan2`,`紧`],[`尺碼`,`cek3 maa5`,`尺码`],[`深藍色`,`sam1 laam4 sik1`,`深蓝色`],[`手袖`,`sau2 zau6`,`袖子`],[`啱身`,`ngaam1 san1`,`合身`],[`一對鞋`,`jat1 deoi3 haai4`,`一双鞋`],[`窄`,`zaak3`,`窄`],[`同款`,`tung4 fun2`,`同款`]],patterns:[[`有冇大／細一個碼？`,`在已经试过的尺码基础上请求换码。`,`有冇細一個碼？`],[`……有啲……`,`委婉描述穿着上的小问题。`,`條褲有啲長。`]],cultureNote:`「件」配上衣，「条」配裤子，「对」配鞋。试穿前先问店员；「啱身」说衣服合身，「啱着」也可表达大小适合穿。`,practicePrompt:`你试了一件外套和一双鞋。分别说出袖子太长、鞋头太窄，并向店员请求合适的颜色和尺码。`}),t({id:`shopping-compare-prices`,topicId:`shopping`,level:2,title:`問價錢再比較`,description:`价格、功能、配件与预算`,speakers:[`客人`,`店員`],phrases:[[`唔該，呢兩款有咩分別？`,`m4 goi1, ni1 loeng5 fun2 jau5 me1 fan1 bit6?`,`请问，这两款有什么区别？`],[`呢款輕啲，嗰款個袋大啲。`,`ni1 fun2 heng1 di1, go2 fun2 go3 doi2 daai6 di1.`,`这款轻一点，那款的袋子大一点。`],[`輕嗰款賣幾多錢？`,`heng1 go2 fun2 maai6 gei2 do1 cin2?`,`轻的那款卖多少钱？`],[`三百八十蚊，包一條帶。`,`saam1 baak3 baat3 sap6 man1, baau1 jat1 tiu4 daai3.`,`三百八十元，包括一条带子。`],[`我想買個返工用嘅袋。`,`ngo5 soeng2 maai5 go3 faan1 gung1 jung6 ge3 doi2.`,`我想买一个上班用的包。`],[`咁呢款啱啲，可以放手提電腦。`,`gam2 ni1 fun2 ngaam1 di1, ho2 ji5 fong3 sau2 tai4 din6 nou5.`,`那这款更适合，可以放笔记本电脑。`],[`有啲超出預算，有冇平啲嘅？`,`jau5 di1 ciu1 ceot1 jyu6 syun3, jau5 mou5 peng4 di1 ge3?`,`有点超出预算，有便宜一些的吗？`],[`有，旁邊呢款二百幾蚊。`,`jau5, pong4 bin1 ni1 fun2 ji6 baak3 gei2 man1.`,`有，旁边这款两百多元。`],[`呢個價錢包埋配件未？`,`ni1 go3 gaa3 cin2 baau1 maai4 pui3 gin6 mei6?`,`这个价格已经包括配件了吗？`],[`我想睇清楚尺寸先。`,`ngo5 soeng2 tai2 cing1 co2 cek3 cyun3 sin1.`,`我想先看清楚尺寸。`],[`可唔可以攞兩個畀我比較吓？`,`ho2 m4 ho2 ji5 lo2 loeng5 go3 bei2 ngo5 bei2 gaau3 haa5?`,`可以拿两个给我比较一下吗？`],[`我諗吓先，多謝你介紹。`,`ngo5 nam2 haa5 sin1, do1 ze6 nei5 gaai3 siu6.`,`我先考虑一下，谢谢你介绍。`]],words:[[`分別`,`fan1 bit6`,`区别`],[`輕`,`heng1`,`轻`],[`一條帶`,`jat1 tiu4 daai3`,`一条带子`],[`返工`,`faan1 gung1`,`上班`],[`手提電腦`,`sau2 tai4 din6 nou5`,`笔记本电脑`],[`預算`,`jyu6 syun3`,`预算`],[`配件`,`pui3 gin6`,`配件`],[`尺寸`,`cek3 cyun3`,`尺寸`],[`比較`,`bei2 gaau3`,`比较`],[`諗吓`,`nam2 haa5`,`考虑一下`]],patterns:[[`呢款……啲，嗰款……啲。`,`比较两款商品的不同特点。`,`呢款細啲，嗰款輕啲。`],[`我想買個……用嘅……`,`先说明用途，让店员更容易推荐。`,`我想買個去旅行用嘅袋。`]],cultureNote:`「平」表示便宜时读 peng4。「我谂吓先」是自然、礼貌的暂不购买说法。比较价格时，也要问清楚是否包括配件。`,practicePrompt:`为短途旅行挑一个背包，比较重量、容量与配件。说出你的预算，并在决定前礼貌地表示想考虑一下。`}),t({id:`shopping-paying-receipts`,topicId:`shopping`,level:1,title:`畀錢同留單`,description:`付款方式、金额与收据`,speakers:[`客人`,`收銀員`],phrases:[[`唔該，幫我計數。`,`m4 goi1, bong1 ngo5 gai3 sou3.`,`请帮我结账。`],[`一共一百二十八蚊。`,`jat1 gung6 jat1 baak3 ji6 sap6 baat3 man1.`,`一共一百二十八元。`],[`可唔可以用八達通？`,`ho2 m4 ho2 ji5 jung6 baat3 daat6 tung1?`,`可以用八达通吗？`],[`可以，拍呢度就得。`,`ho2 ji5, paak3 ni1 dou6 zau6 dak1.`,`可以，在这里拍卡就行。`],[`唔好意思，我想睇吓張單先。`,`m4 hou2 ji3 si1, ngo5 soeng2 tai2 haa5 zoeng1 daan1 sin1.`,`不好意思，我想先看一下账单。`],[`冇問題，你慢慢睇。`,`mou5 man6 tai4, nei5 maan6 maan6 tai2.`,`没问题，你慢慢看。`],[`啱喇，唔該畀返張收據我。`,`ngaam1 laa3, m4 goi1 bei2 faan1 zoeng1 sau1 geoi3 ngo5.`,`金额对了，请把收据给我。`],[`好呀，張收據放咗入袋。`,`hou2 aa3, zoeng1 sau1 geoi3 fong3 zo2 jap6 doi2.`,`好的，收据已经放进袋子里。`],[`呢度收唔收現金？`,`ni1 dou6 sau1 m4 sau1 jin6 gam1?`,`这里收现金吗？`],[`可唔可以分開兩張單？`,`ho2 m4 ho2 ji5 fan1 hoi1 loeng5 zoeng1 daan1?`,`可以分成两张账单吗？`],[`好似計多咗一件，麻煩你睇吓。`,`hou2 ci5 gai3 do1 zo2 jat1 gin6, maa4 faan4 nei5 tai2 haa5.`,`好像多算了一件，麻烦你看一下。`],[`找續好似少咗十蚊。`,`zaau2 zuk6 hou2 ci5 siu2 zo2 sap6 man1.`,`找零好像少了十元。`]],words:[[`計數`,`gai3 sou3`,`结账；算钱`],[`一共`,`jat1 gung6`,`一共`],[`八達通`,`baat3 daat6 tung1`,`八达通`],[`拍`,`paak3`,`拍卡；轻触`],[`張單`,`zoeng1 daan1`,`账单`],[`收據`,`sau1 geoi3`,`收据`],[`現金`,`jin6 gam1`,`现金`],[`分開`,`fan1 hoi1`,`分开`],[`計多咗`,`gai3 do1 zo2`,`多算了`],[`找續`,`zaau2 zuk6`,`找零`]],patterns:[[`收唔收……？`,`询问店铺是否接受某种付款方式。`,`收唔收信用卡？`],[`好似……咗……`,`发现可能的差错时，先用好似缓和语气。`,`好似少咗一件。`]],cultureNote:`「拍」常用来描述八达通轻触读卡器的动作。「找续」指找零。怀疑金额不对时，可以拿着账单说「麻烦你睇吓」，让双方一起核对。具体付款方式以店内说明为准。`,practicePrompt:`结账时先问是否收现金，再核对账单。你发现多算了一件商品，请店员检查，并要求保留收据。`}),t({id:`shopping-returns`,topicId:`shopping`,level:3,title:`退換貨講清楚`,description:`商品问题、退换条件与单据`,speakers:[`客人`,`店員`],phrases:[[`唔好意思，我想換呢件衫。`,`m4 hou2 ji3 si1, ngo5 soeng2 wun6 ni1 gin6 saam1.`,`不好意思，我想换这件衣服。`],[`請問有咩問題？`,`cing2 man6 jau5 me1 man6 tai4?`,`请问有什么问题？`],[`買返去先發現手袖穿咗個窿。`,`maai5 faan1 heoi3 sin1 faat3 jin6 sau2 zau6 cyun1 zo2 go3 lung1.`,`买回去才发现袖子破了一个洞。`],[`有冇帶收據？我幫你睇吓。`,`jau5 mou5 daai3 sau1 geoi3? ngo5 bong1 nei5 tai2 haa5.`,`带收据了吗？我帮你看看。`],[`有，尋日買嘅，標籤都仲喺度。`,`jau5, cam4 jat6 maai5 ge3, biu1 cim1 dou1 zung6 hai2 dou6.`,`带了，昨天买的，标签也还在。`],[`我查吓仲有冇同款先。`,`ngo5 caa4 haa5 zung6 jau5 mou5 tung4 fun2 sin1.`,`我先查一下还有没有同款。`],[`如果冇同款，可以點處理？`,`jyu4 gwo2 mou5 tung4 fun2, ho2 ji5 dim2 cyu2 lei5?`,`如果没有同款，可以怎么处理？`],[`我請同事幫你確認換貨安排。`,`ngo5 cing2 tung4 si6 bong1 nei5 kok3 jan6 wun6 fo3 on1 paai4.`,`我请同事帮你确认换货安排。`],[`呢個拉鏈拉唔到。`,`ni1 go3 laai1 lin2 laai1 m4 dou2.`,`这个拉链拉不上。`],[`可唔可以換另一隻色？`,`ho2 m4 ho2 ji5 wun6 ling6 jat1 zek3 sik1?`,`可以换另一种颜色吗？`],[`如果要補差價，要補幾多？`,`jyu4 gwo2 jiu3 bou2 caa1 gaa3, jiu3 bou2 gei2 do1?`,`如果需要补差价，要补多少？`],[`可唔可以幫我寫低處理方法？`,`ho2 m4 ho2 ji5 bong1 ngo5 se2 dai1 cyu2 lei5 fong1 faat3?`,`可以帮我写下处理方法吗？`]],words:[[`換貨`,`wun6 fo3`,`换货`],[`手袖`,`sau2 zau6`,`袖子`],[`窿`,`lung1`,`洞`],[`收據`,`sau1 geoi3`,`收据`],[`尋日`,`cam4 jat6`,`昨天`],[`標籤`,`biu1 cim1`,`标签`],[`確認`,`kok3 jan6`,`确认`],[`拉鏈`,`laai1 lin2`,`拉链`],[`補差價`,`bou2 caa1 gaa3`,`补差价`],[`處理方法`,`cyu2 lei5 fong1 faat3`,`处理方法`]],patterns:[[`……先發現……`,`交代问题是在什么时间、什么动作之后发现的。`,`返到屋企先發現少咗個配件。`],[`如果……，可以點處理？`,`提出一种情况，再询问可行的处理办法。`,`如果冇貨，可以點處理？`]],cultureNote:`退换安排因店铺和商品而异。本课练习的是把购买时间、商品问题和希望的处理方式说清楚；保留收据和标签，有助于店员核对购买记录。`,practicePrompt:`你买的袋子拉链打不开，带着收据回店。说明何时发现问题，问同款缺货时的处理方式，并确认是否需要补差价。`})],o=[t({id:`getting-around-directions`,topicId:`getting-around`,level:1,title:`唔識路，開口問`,description:`方向、地标与步行距离`,speakers:[`問路人`,`街坊`],phrases:[[`唔該，去郵局點行？`,`m4 goi1, heoi3 jau4 guk6 dim2 haang4?`,`请问，去邮局怎么走？`],[`沿住呢條街一直行。`,`jyun4 zyu6 ni1 tiu4 gaai1 jat1 zik6 haang4.`,`沿着这条街一直走。`],[`行到路口要唔要轉彎？`,`haang4 dou3 lou6 hau2 jiu3 m4 jiu3 zyun3 waan1?`,`走到路口需要转弯吗？`],[`要，喺第二個路口轉右。`,`jiu3, hai2 dai6 ji6 go3 lou6 hau2 zyun3 jau6.`,`需要，在第二个路口右转。`],[`要唔要過對面馬路？`,`jiu3 m4 jiu3 gwo3 deoi3 min6 maa5 lou6?`,`需要到马路对面吗？`],[`要，行人天橋過去。`,`jiu3, haang4 jan4 tin1 kiu4 gwo3 heoi3.`,`需要，走人行天桥过去。`],[`大概要行幾耐？`,`daai6 koi3 jiu3 haang4 gei2 noi6?`,`大概要走多久？`],[`十分鐘左右，郵局喺銀行隔籬。`,`sap6 fan1 zung1 zo2 jau6, jau4 guk6 hai2 ngan4 hong4 gaak3 lei4.`,`十分钟左右，邮局在银行旁边。`],[`我唔熟呢頭，可唔可以指畀我睇？`,`ngo5 m4 suk6 ni1 tau4, ho2 m4 ho2 ji5 zi2 bei2 ngo5 tai2?`,`我不熟悉这一带，可以指给我看吗？`],[`係咪行過咗？`,`hai6 mai6 haang4 gwo3 zo2?`,`是不是走过头了？`],[`麻煩你講慢少少。`,`maa4 faan4 nei5 gong2 maan6 siu2 siu2.`,`麻烦你说慢一点。`],[`即係轉右之後一直行，啱唔啱？`,`zik1 hai6 zyun3 jau6 zi1 hau6 jat1 zik6 haang4, ngaam1 m4 ngaam1?`,`也就是右转后一直走，对吗？`]],words:[[`郵局`,`jau4 guk6`,`邮局`],[`沿住`,`jyun4 zyu6`,`沿着`],[`一直行`,`jat1 zik6 haang4`,`一直走`],[`路口`,`lou6 hau2`,`路口`],[`轉右`,`zyun3 jau6`,`右转`],[`對面`,`deoi3 min6`,`对面`],[`天橋`,`tin1 kiu4`,`天桥`],[`幾耐`,`gei2 noi6`,`多久`],[`隔籬`,`gaak3 lei4`,`旁边`],[`呢頭`,`ni1 tau4`,`这一带`]],patterns:[[`去……點行？`,`问步行路线的常用句。`,`去圖書館點行？`],[`即係……，啱唔啱？`,`把听到的路线复述一次，检查理解。`,`即係過馬路再轉左，啱唔啱？`]],cultureNote:`「呢头」指附近这一带。「行人天桥」里的行读 haang4，与「行路」相同。听完路线后，用地标和转弯顺序复述一遍，比只说听懂了更可靠。`,practicePrompt:`你从街市去图书馆，路线经过两个路口和一座天桥。请人指路、询问步行时间，再复述路线确认。`}),t({id:`getting-around-mtr`,topicId:`getting-around`,level:1,title:`搭港鐵唔心急`,description:`港铁方向、月台与八达通`,speakers:[`乘客`,`職員`],phrases:[[`我想搭港鐵，入口喺邊？`,`ngo5 soeng2 daap3 gong2 tit3, jap6 hau2 hai2 bin1?`,`我想坐港铁，入口在哪里？`],[`前面個地下入口就係。`,`cin4 min6 go3 dei6 haa6 jap6 hau2 zau6 hai6.`,`就是前面的地下入口。`],[`我張八達通唔知仲有幾多錢。`,`ngo5 zoeng1 baat3 daat6 tung1 m4 zi1 zung6 jau5 gei2 do1 cin2.`,`我不知道我的八达通还剩多少钱。`],[`你可以先去部機度查吓。`,`nei5 ho2 ji5 sin1 heoi3 bou6 gei1 dou6 caa4 haa5.`,`你可以先到那台机器查一下。`],[`入閘之後去邊個月台？`,`jap6 zaap6 zi1 hau6 heoi3 bin1 go3 jyut6 toi4?`,`进闸后去哪个站台？`],[`睇指示牌，揀啱方向先落去。`,`tai2 zi2 si6 paai4, gaan2 ngaam1 fong1 hoeng3 sin1 lok6 heoi3.`,`看指示牌，选对方向再下去。`],[`如果搭錯方向點算？`,`jyu4 gwo2 daap3 co3 fong1 hoeng3 dim2 syun3?`,`如果坐错方向怎么办？`],[`下一個站落車，再問職員。`,`haa6 jat1 go3 zaam6 lok6 ce1, zoi3 man6 zik1 jyun4.`,`下一站下车，再问工作人员。`],[`去呢個站要唔要轉車？`,`heoi3 ni1 go3 zaam6 jiu3 m4 jiu3 zyun3 ce1?`,`去这个站需要换乘吗？`],[`唔該，邊個出口有升降機？`,`m4 goi1, bin1 go3 ceot1 hau2 jau5 sing1 gong3 gei1?`,`请问，哪个出口有电梯？`],[`我張卡入唔到閘。`,`ngo5 zoeng1 kaat1 jap6 m4 dou2 zaap6.`,`我的卡进不了闸。`],[`仲有幾多個站先到？`,`zung6 jau5 gei2 do1 go3 zaam6 sin1 dou3?`,`还要多少站才到？`]],words:[[`港鐵`,`gong2 tit3`,`港铁`],[`入口`,`jap6 hau2`,`入口`],[`八達通`,`baat3 daat6 tung1`,`八达通`],[`入閘`,`jap6 zaap6`,`进闸`],[`月台`,`jyut6 toi4`,`站台`],[`指示牌`,`zi2 si6 paai4`,`指示牌`],[`方向`,`fong1 hoeng3`,`方向`],[`轉車`,`zyun3 ce1`,`换乘`],[`出口`,`ceot1 hau2`,`出口`],[`升降機`,`sing1 gong3 gei1`,`电梯`]],patterns:[[`……之後去邊……？`,`问完成一个步骤之后的下一步。`,`出閘之後去邊個出口？`],[`……唔到……`,`表示由于某种原因无法完成动作。`,`我張卡拍唔到。`]],cultureNote:`香港常用「月台」称站台，「升降机」称电梯。路线、出口和班次以现场指示为准；不知道往哪边走时，可以给职员看目的地名称。`,practicePrompt:`第一次到一个港铁站，向职员问去目的地是否需要换乘，再询问有电梯的出口。途中八达通无法入闸，请职员帮忙。`}),t({id:`getting-around-bus-minibus`,topicId:`getting-around`,level:2,title:`巴士小巴，有落`,description:`目的地、车费与下车地点`,speakers:[`乘客`,`司機`],phrases:[[`唔該，呢架車去唔去街市？`,`m4 goi1, ni1 gaa3 ce1 heoi3 m4 heoi3 gaai1 si5?`,`请问，这辆车去街市吗？`],[`去，你上車先。`,`heoi3, nei5 soeng5 ce1 sin1.`,`去，你先上车。`],[`上車畀錢定落車畀？`,`soeng5 ce1 bei2 cin2 ding6 lok6 ce1 bei2?`,`上车付款还是下车付款？`],[`呢架上車畀錢。`,`ni1 gaa3 soeng5 ce1 bei2 cin2.`,`这辆车上车付款。`],[`到咗街市可唔可以提我？`,`dou3 zo2 gaai1 si5 ho2 m4 ho2 ji5 tai4 ngo5?`,`到了街市可以提醒我吗？`],[`可以，你坐穩先。`,`ho2 ji5, nei5 co5 wan2 sin1.`,`可以，你先坐稳。`],[`唔該，前面有落。`,`m4 goi1, cin4 min6 jau5 lok6.`,`麻烦您，前面有人下车。`,`「有落」是小巴上常听到的下车提示。`],[`好，等車停定先落。`,`hou2, dang2 ce1 ting4 ding6 sin1 lok6.`,`好的，等车停稳再下。`],[`呢度有冇車去碼頭？`,`ni1 dou6 jau5 mou5 ce1 heoi3 maa5 tau4?`,`这里有车去码头吗？`],[`我想喺下一個站落。`,`ngo5 soeng2 hai2 haa6 jat1 go3 zaam6 lok6.`,`我想在下一站下车。`],[`架車滿咗，等下一架啦。`,`gaa3 ce1 mun5 zo2, dang2 haa6 jat1 gaa3 laa1.`,`车满了，等下一辆吧。`],[`唔該借借，我想行出去。`,`m4 goi1 ze3 ze3, ngo5 soeng2 haang4 ceot1 heoi3.`,`麻烦让一下，我想走出去。`]],words:[[`巴士`,`baa1 si2`,`公共汽车`],[`小巴`,`siu2 baa1`,`小巴`],[`上車`,`soeng5 ce1`,`上车`],[`落車`,`lok6 ce1`,`下车`],[`畀錢`,`bei2 cin2`,`付款`],[`提我`,`tai4 ngo5`,`提醒我`],[`坐穩`,`co5 wan2`,`坐稳`],[`有落`,`jau5 lok6`,`有人下车`],[`碼頭`,`maa5 tau4`,`码头`],[`借借`,`ze3 ze3`,`借过；请让一下`]],patterns:[[`呢架車去唔去……？`,`上车前确认目的地。`,`呢架車去唔去海邊？`],[`等……先……`,`先等某件事完成，再进行下一动作。`,`等前面啲人落咗先上車。`]],cultureNote:`「有落」常用于小巴；普通巴士一般按钟示意下车。不同车辆的付款和停站安排有差别，上车前问清楚。与司机交流应简短，避免影响驾驶。`,practicePrompt:`你要去码头但不熟悉路线。上车前确认目的地和付款方式，请司机提醒到站，并练习快到站时说「前面有落」。`}),t({id:`getting-around-taxi`,topicId:`getting-around`,level:2,title:`的士講地址`,description:`目的地、路线与停车位置`,speakers:[`乘客`,`司機`],phrases:[[`師傅，唔該去呢個地址。`,`si1 fu6, m4 goi1 heoi3 ni1 go3 dei6 zi2.`,`师傅，麻烦去这个地址。`],[`好，行邊條路？`,`hou2, haang4 bin1 tiu4 lou6?`,`好的，走哪条路？`],[`我唔熟路，你揀條順路嘅。`,`ngo5 m4 suk6 lou6, nei5 gaan2 tiu4 seon6 lou6 ge3.`,`我不熟路，你选一条顺路的吧。`],[`好，你趕唔趕時間？`,`hou2, nei5 gon2 m4 gon2 si4 gaan3?`,`好的，你赶时间吗？`],[`有少少趕，大概要幾耐？`,`jau5 siu2 siu2 gon2, daai6 koi3 jiu3 gei2 noi6?`,`有点赶，大概需要多久？`],[`要睇路面情況，我盡快。`,`jiu3 tai2 lou6 min6 cing4 fong3, ngo5 zeon6 faai3.`,`要看路面情况，我尽快。`],[`到咗前面個路口，唔該停一停。`,`dou3 zo2 cin4 min6 go3 lou6 hau2, m4 goi1 ting4 jat1 ting4.`,`到了前面路口，麻烦停一下。`],[`好，呢度落車得唔得？`,`hou2, ni1 dou6 lok6 ce1 dak1 m4 dak1?`,`好的，在这里下车可以吗？`],[`唔該幫我開車尾箱。`,`m4 goi1 bong1 ngo5 hoi1 ce1 mei5 soeng1.`,`麻烦帮我开后备厢。`],[`可唔可以開大啲冷氣？`,`ho2 m4 ho2 ji5 hoi1 daai6 di1 laang5 hei3?`,`可以把空调开大一点吗？`],[`喺前面可以停車嘅地方落就得。`,`hai2 cin4 min6 ho2 ji5 ting4 ce1 ge3 dei6 fong1 lok6 zau6 dak1.`,`在前面可以停车的地方下就行。`],[`唔該畀張收據我，返公司用。`,`m4 goi1 bei2 zoeng1 sau1 geoi3 ngo5, faan1 gung1 si1 jung6.`,`请给我一张收据，回公司要用。`]],words:[[`的士`,`dik1 si2`,`出租车`],[`師傅`,`si1 fu6`,`师傅`],[`地址`,`dei6 zi2`,`地址`],[`熟路`,`suk6 lou6`,`熟悉路线`],[`順路`,`seon6 lou6`,`顺路`],[`趕時間`,`gon2 si4 gaan3`,`赶时间`],[`路面情況`,`lou6 min6 cing4 fong3`,`路面情况`],[`車尾箱`,`ce1 mei5 soeng1`,`后备厢`],[`冷氣`,`laang5 hei3`,`空调`],[`收據`,`sau1 geoi3`,`收据`]],patterns:[[`唔該去……`,`简短、礼貌地报出目的地，也可出示地址。`,`唔該去海旁嗰間酒店。`],[`喺……落就得。`,`说明可接受的下车位置。`,`喺商場門口落就得。`]],cultureNote:`「的士」是出租车，「车尾箱」是后备厢。报地址时，街名、大厦名和附近地标可以一起提供；下车位置由司机结合现场停车条件判断。`,practicePrompt:`从车站乘的士去朋友家。给司机看地址，说明自己不熟路，询问所需时间，并要求在可以停车的位置下车和索取收据。`}),t({id:`getting-around-airport`,topicId:`getting-around`,level:2,title:`機場逐步嚟`,description:`值机柜台、托运行李与登机`,speakers:[`旅客`,`職員`],phrases:[[`唔該，去邊度辦登機手續？`,`m4 goi1, heoi3 bin1 dou6 baan6 dang1 gei1 sau2 zuk6?`,`请问，去哪里办理登机手续？`],[`你搭邊間航空公司？`,`nei5 daap3 bin1 gaan1 hong4 hung1 gung1 si1?`,`你乘哪家航空公司的航班？`],[`我搭呢班機，呢度有航班資料。`,`ngo5 daap3 ni1 baan1 gei1, ni1 dou6 jau5 hong4 baan1 zi1 liu6.`,`我坐这个航班，这里有航班资料。`],[`請去前面個櫃位排隊。`,`cing2 heoi3 cin4 min6 go3 gwai6 wai2 paai4 deoi6.`,`请到前面的柜台排队。`],[`我有一件行李要寄艙。`,`ngo5 jau5 jat1 gin6 hang4 lei5 jiu3 gei3 cong1.`,`我有一件行李要托运。`],[`麻煩你放上磅。`,`maa4 faan4 nei5 fong3 soeng5 bong6.`,`麻烦你把它放到秤上。`],[`登機閘口同時間喺邊度睇？`,`dang1 gei1 zaap6 hau2 tung4 si4 gaan3 hai2 bin1 dou6 tai2?`,`登机口和登机时间在哪里看？`],[`登機證有寫，亦要留意電子屏幕。`,`dang1 gei1 zing3 jau5 se2, jik6 jiu3 lau4 ji3 din6 zi2 ping4 mok6.`,`登机牌上有写，也要留意电子屏幕。`],[`我想要靠走廊嘅位。`,`ngo5 soeng2 jiu3 kaau3 zau2 long4 ge3 wai2.`,`我想要靠过道的座位。`],[`呢件行李可唔可以手提上機？`,`ni1 gin6 hang4 lei5 ho2 m4 ho2 ji5 sau2 tai4 soeng5 gei1?`,`这件行李可以随身带上飞机吗？`],[`航班有冇延誤？`,`hong4 baan1 jau5 mou5 jin4 ng6?`,`航班有延误吗？`],[`唔該，行李帶喺邊？`,`m4 goi1, hang4 lei5 daai3 hai2 bin1?`,`请问，行李转盘在哪里？`]],words:[[`登機手續`,`dang1 gei1 sau2 zuk6`,`登机手续`],[`航空公司`,`hong4 hung1 gung1 si1`,`航空公司`],[`航班`,`hong4 baan1`,`航班`],[`櫃位`,`gwai6 wai2`,`柜台`],[`排隊`,`paai4 deoi6`,`排队`],[`行李`,`hang4 lei5`,`行李`],[`寄艙`,`gei3 cong1`,`托运`],[`登機證`,`dang1 gei1 zing3`,`登机牌`],[`走廊`,`zau2 long4`,`过道；走廊`],[`延誤`,`jin4 ng6`,`延误`]],patterns:[[`我有……要……`,`说明需要办理的事情或处理的物品。`,`我有兩件行李要寄艙。`],[`……喺邊度睇？`,`询问信息的查看位置。`,`最新航班資料喺邊度睇？`]],cultureNote:`「寄舱」是托运，「手提行李」是随身行李。柜位、登机口和时间可能调整，要结合航空公司通知与现场屏幕确认；行李能否随身携带应问当班职员。`,practicePrompt:`你有一件托运行李，想要过道座位。向职员出示航班资料，提出需求，再问在哪里确认登机口和登机时间。`}),t({id:`getting-around-hotel`,topicId:`getting-around`,level:2,title:`酒店入住同寄存`,description:`预订、入住、退房与行李寄存`,speakers:[`旅客`,`接待員`],phrases:[[`你好，我訂咗房，想辦入住。`,`nei5 hou2, ngo5 deng6 zo2 fong2, soeng2 baan6 jap6 zyu6.`,`你好，我订了房，想办理入住。`],[`你好，麻煩你畀我睇吓預訂資料。`,`nei5 hou2, maa4 faan4 nei5 bei2 ngo5 tai2 haa5 jyu6 deng6 zi1 liu6.`,`你好，麻烦给我看一下预订资料。`],[`呢度有預訂號碼，我住兩晚。`,`ni1 dou6 jau5 jyu6 deng6 hou6 maa5, ngo5 zyu6 loeng5 maan5.`,`这里有预订号码，我住两晚。`],[`收到，呢張房卡請收好。`,`sau1 dou2, ni1 zoeng1 fong2 kaat1 cing2 sau1 hou2.`,`收到了，请收好这张房卡。`],[`唔該，最遲幾點退房？`,`m4 goi1, zeoi3 ci4 gei2 dim2 teoi3 fong2?`,`请问，最晚几点退房？`],[`我幫你確認今次預訂嘅退房時間。`,`ngo5 bong1 nei5 kok3 jan6 gam1 ci3 jyu6 deng6 ge3 teoi3 fong2 si4 gaan3.`,`我帮你确认这次预订的退房时间。`],[`退房之後可唔可以寄存行李？`,`teoi3 fong2 zi1 hau6 ho2 m4 ho2 ji5 gei3 cyun4 hang4 lei5?`,`退房后可以寄存行李吗？`],[`可以，到時帶行李嚟接待處。`,`ho2 ji5, dou3 si4 daai3 hang4 lei5 lai4 zip3 doi6 cyu3.`,`可以，到时把行李带到接待处。`],[`早餐喺邊度食？`,`zou2 caan1 hai2 bin1 dou6 sik6?`,`早餐在哪里吃？`],[`房間個冷氣好似唔凍。`,`fong2 gaan1 go3 laang5 hei3 hou2 ci5 m4 dung3.`,`房间的空调好像不凉。`],[`可唔可以加一張被？`,`ho2 m4 ho2 ji5 gaa1 jat1 zoeng1 pei5?`,`可以加一条被子吗？`],[`房卡開唔到門，麻煩你幫手。`,`fong2 kaat1 hoi1 m4 dou2 mun4, maa4 faan4 nei5 bong1 sau2.`,`房卡开不了门，麻烦帮忙。`]],words:[[`訂房`,`deng6 fong2`,`订房`],[`入住`,`jap6 zyu6`,`入住`],[`預訂`,`jyu6 deng6`,`预订`],[`號碼`,`hou6 maa5`,`号码`],[`房卡`,`fong2 kaat1`,`房卡`],[`最遲`,`zeoi3 ci4`,`最迟`],[`退房`,`teoi3 fong2`,`退房`],[`寄存`,`gei3 cyun4`,`寄存`],[`接待處`,`zip3 doi6 cyu3`,`接待处`],[`一張被`,`jat1 zoeng1 pei5`,`一条被子`]],patterns:[[`我……咗，想……`,`先交代已完成的事项，再提出下一步需要。`,`我訂咗房，想確認入住時間。`],[`可唔可以加……？`,`请求增加房间用品。`,`可唔可以加一個枕頭？`]],cultureNote:`香港酒店前台也常听到英语 check-in 和 check-out，但「入住」「退房」同样清楚。早餐、寄存与退房安排随预订而异，主动让接待员核对你的订单。`,practicePrompt:`办理两晚住宿的入住手续，询问早餐地点、退房时间和行李寄存。回房后发现房卡无法开门，再向接待处求助。`})],s=[t({id:`home-giving-address`,topicId:`home`,level:1,title:`地址講清楚`,description:`街名、大厦、楼层与单位`,speakers:[`訪客`,`住客`],phrases:[[`可唔可以講多次地址？`,`ho2 m4 ho2 ji5 gong2 do1 ci3 dei6 zi2?`,`可以再说一次地址吗？`],[`海景街八號，青松大廈。`,`hoi2 ging2 gaai1 baat3 hou6, cing1 cung4 daai6 haa6.`,`海景街八号，青松大厦。`,`本课地址为练习示例。`],[`大廈名點寫？`,`daai6 haa6 meng2 dim2 se2?`,`大厦名称怎么写？`],[`青色嘅青，松樹嘅松。`,`cing1 sik1 ge3 cing1, cung4 syu6 ge3 cung4.`,`青色的青，松树的松。`],[`收到，幾樓邊個單位？`,`sau1 dou2, gei2 lau4 bin1 go3 daan1 wai2?`,`收到了，几楼哪个房间？`],[`十樓三室，出升降機轉右。`,`sap6 lau4 saam1 sat1, ceot1 sing1 gong3 gei1 zyun3 jau6.`,`十楼三室，出电梯右转。`],[`大門有冇密碼？`,`daai6 mun4 jau5 mou5 mat6 maa5?`,`大门有密码吗？`],[`到咗大堂打畀我，我落嚟接你。`,`dou3 zo2 daai6 tong4 daa2 bei2 ngo5, ngo5 lok6 lai4 zip3 nei5.`,`到了大堂给我打电话，我下来接你。`],[`你傳個位置畀我，唔該。`,`nei5 cyun4 go3 wai6 zi3 bei2 ngo5, m4 goi1.`,`请把位置发给我。`],[`入口喺大廈後面。`,`jap6 hau2 hai2 daai6 haa6 hau6 min6.`,`入口在大厦后面。`],[`唔好行錯去隔籬嗰座。`,`m4 hou2 haang4 co3 heoi3 gaak3 lei4 go2 zo6.`,`别走错到旁边那栋。`],[`我到咗樓下，方便落嚟嗎？`,`ngo5 dou3 zo2 lau4 haa6, fong1 bin6 lok6 lai4 maa3?`,`我到楼下了，方便下来吗？`]],words:[[`地址`,`dei6 zi2`,`地址`],[`大廈`,`daai6 haa6`,`大厦`],[`松樹`,`cung4 syu6`,`松树`],[`單位`,`daan1 wai2`,`住宅单位；房间`],[`升降機`,`sing1 gong3 gei1`,`电梯`],[`密碼`,`mat6 maa5`,`密码`],[`大堂`,`daai6 tong4`,`大堂`],[`位置`,`wai6 zi3`,`位置`],[`後面`,`hau6 min6`,`后面`],[`樓下`,`lau4 haa6`,`楼下`]],patterns:[[`……嘅……`,`用熟悉的词解释姓名或地址中某个字的写法。`,`明天嘅明。`],[`到咗……，我……`,`约定抵达某个地点之后的接应方式。`,`到咗門口，我開門畀你。`]],cultureNote:`香港地址常把街名、门牌、大厦、楼层、单位逐项说出。「单位」在这里指一个独立房间或住宅。听不清大厦名字时，问「点写」可以避免同音字混淆。`,practicePrompt:`用虚构地址邀请朋友到家里。逐项说清街名、大厦、楼层和单位，并告诉对方到了大堂怎样联络你。`}),t({id:`home-viewing-flat`,topicId:`home`,level:3,title:`約睇樓，問細節`,description:`约看房、家具、共用设施与费用`,speakers:[`睇樓客`,`帶看人`],phrases:[[`我想睇吓間屋，幾時方便？`,`ngo5 soeng2 tai2 haa5 gaan1 uk1, gei2 si4 fong1 bin6?`,`我想看一下房子，什么时候方便？`],[`聽日下午有時間，你幾點得閒？`,`ting1 jat6 haa6 ng5 jau5 si4 gaan3, nei5 gei2 dim2 dak1 haan4?`,`明天下午有时间，你几点有空？`],[`三點左右。間屋有冇傢俬？`,`saam1 dim2 zo2 jau6. gaan1 uk1 jau5 mou5 gaa1 si1?`,`三点左右。房子里有家具吗？`],[`有張床同張枱，其他你可以自己加。`,`jau5 zoeng1 cong4 tung4 zoeng1 toi2, kei4 taa1 nei5 ho2 ji5 zi6 gei2 gaa1.`,`有一张床和一张桌子，其他可以自己添置。`],[`廚房同洗手間使唔使同人共用？`,`cyu4 fong2 tung4 sai2 sau2 gaan1 sai2 m4 sai2 tung4 jan4 gung6 jung6?`,`厨房和卫生间需要与别人共用吗？`],[`唔使，呢個單位自己用。`,`m4 sai2, ni1 go3 daan1 wai2 zi6 gei2 jung6.`,`不用，这个住宅单位独立使用。`],[`租金包唔包管理費？`,`zou1 gam1 baau1 m4 baau1 gun2 lei5 fai3?`,`租金包括管理费吗？`],[`我攞份資料畀你睇清楚。`,`ngo5 lo2 fan6 zi1 liu6 bei2 nei5 tai2 cing1 co2.`,`我拿份资料给你看清楚。`],[`可唔可以日頭再嚟睇一次？`,`ho2 m4 ho2 ji5 jat6 tau4 zoi3 lai4 tai2 jat1 ci3?`,`可以白天再来看一次吗？`],[`水電費點樣計？`,`seoi2 din6 fai3 dim2 joeng6 gai3?`,`水电费怎么算？`],[`窗邊有冇漏水嘅痕跡？`,`coeng1 bin1 jau5 mou5 lau6 seoi2 ge3 han4 zik1?`,`窗边有没有漏水的痕迹？`],[`我想記低啲問題，再慢慢確認。`,`ngo5 soeng2 gei3 dai1 di1 man6 tai4, zoi3 maan6 maan6 kok3 jan6.`,`我想记下问题，再逐一确认。`]],words:[[`睇樓`,`tai2 lau4`,`看房`],[`得閒`,`dak1 haan4`,`有空`],[`傢俬`,`gaa1 si1`,`家具`],[`廚房`,`cyu4 fong2`,`厨房`],[`洗手間`,`sai2 sau2 gaan1`,`卫生间`],[`共用`,`gung6 jung6`,`共用`],[`租金`,`zou1 gam1`,`租金`],[`管理費`,`gun2 lei5 fai3`,`管理费`],[`水電費`,`seoi2 din6 fai3`,`水电费`],[`痕跡`,`han4 zik1`,`痕迹`]],patterns:[[`……包唔包……？`,`询问总价包括哪些项目。`,`租金包唔包上網費？`],[`……使唔使同人共用？`,`询问设施是否需要与别人共同使用。`,`洗衣機使唔使同人共用？`]],cultureNote:`「睇楼」包括看房和看住宅单位，「家俬」指家具。看房时先把费用、设施和入住安排问清楚；本课提供沟通句子，具体条件应以双方确认的资料为准。`,practicePrompt:`预约一次白天看房，准备家具、共用设施、管理费和水电费四项问题，再把未确定的事项记下来。`}),t({id:`home-housework`,topicId:`home`,level:2,title:`屋企一齊做`,description:`家务分工、清洁与收纳`,speakers:[`家人甲`,`家人乙`],phrases:[[`今晚我煮飯，你可唔可以洗碗？`,`gam1 maan5 ngo5 zyu2 faan6, nei5 ho2 m4 ho2 ji5 sai2 wun2?`,`今晚我做饭，你可以洗碗吗？`],[`得呀，食完飯我洗。`,`dak1 aa3, sik6 jyun4 faan6 ngo5 sai2.`,`可以，吃完饭我来洗。`],[`洗衣機嗰機衫洗完未？`,`sai2 ji1 gei1 go2 gei1 saam1 sai2 jyun4 mei6?`,`洗衣机里那一机衣服洗完了吗？`],[`洗完喇，我一陣晾衫。`,`sai2 jyun4 laa3, ngo5 jat1 zan6 long6 saam1.`,`洗完了，我一会儿晾衣服。`],[`地板有啲污糟，等我拖地。`,`dei6 baan2 jau5 di1 wu1 zou1, dang2 ngo5 to1 dei2.`,`地板有点脏，我来拖地吧。`],[`咁我執吓枱面。`,`gam2 ngo5 zap1 haa5 toi2 min6.`,`那我收拾一下桌面。`],[`垃圾袋滿咗，幫我拎落去吖。`,`laap6 saap3 doi2 mun5 zo2, bong1 ngo5 ling1 lok6 heoi3 aa1.`,`垃圾袋满了，帮我拿下去吧。`],[`好，我出門口嗰陣順手掉。`,`hou2, ngo5 ceot1 mun4 hau2 go2 zan6 seon6 sau2 diu6.`,`好的，我出门时顺手扔掉。`],[`件衫未乾，遲啲先收。`,`gin6 saam1 mei6 gon1, ci4 di1 sin1 sau1.`,`衣服还没干，晚一点再收。`],[`呢啲碗浸一陣先洗。`,`ni1 di1 wun2 zam3 jat1 zan6 sin1 sai2.`,`这些碗先泡一会儿再洗。`],[`唔該幫我抹乾張枱。`,`m4 goi1 bong1 ngo5 maat3 gon1 zoeng1 toi2.`,`请帮我把桌子擦干。`],[`用完記得放返原位。`,`jung6 jyun4 gei3 dak1 fong3 faan1 jyun4 wai6.`,`用完记得放回原处。`]],words:[[`煮飯`,`zyu2 faan6`,`做饭`],[`洗碗`,`sai2 wun2`,`洗碗`],[`洗衣機`,`sai2 ji1 gei1`,`洗衣机`],[`晾衫`,`long6 saam1`,`晾衣服`],[`污糟`,`wu1 zou1`,`脏`],[`拖地`,`to1 dei2`,`拖地`],[`執`,`zap1`,`收拾`],[`垃圾袋`,`laap6 saap3 doi2`,`垃圾袋`],[`順手`,`seon6 sau2`,`顺手`],[`抹乾`,`maat3 gon1`,`擦干`]],patterns:[[`……完未？`,`问一个动作是否已经完成。`,`你執完間房未？`],[`……嗰陣順手……`,`借另一个动作发生的时机，一起做一件小事。`,`返屋企嗰陣順手買支奶。`]],cultureNote:`「执」很常用，可以说执房、执枱、执嘢。「等我……」在家务分工里常是主动说「我来做」，并不一定真的要求对方等待。`,practicePrompt:`与室友分配周末家务：你负责两件事，请对方负责两件事。询问一项工作的进度，再说一件可以出门时顺手做的事。`}),t({id:`home-repairs`,topicId:`home`,level:3,title:`報修講到重點`,description:`故障情况、报修与上门时间`,speakers:[`住客`,`維修師傅`],phrases:[[`你好，我屋企個水龍頭漏水。`,`nei5 hou2, ngo5 uk1 kei2 go3 seoi2 lung4 tau4 lau6 seoi2.`,`你好，我家水龙头漏水。`],[`漏咗幾耐？漏得勁唔勁？`,`lau6 zo2 gei2 noi6? lau6 dak1 ging6 m4 ging6?`,`漏了多久？漏得严重吗？`],[`尋晚開始，一路滴水。`,`cam4 maan5 hoi1 ci2, jat1 lou6 dik1 seoi2.`,`昨晚开始，一直滴水。`],[`可唔可以影張相畀我睇吓？`,`ho2 m4 ho2 ji5 jing2 zoeng1 soeng2 bei2 ngo5 tai2 haa5?`,`可以拍张照片给我看看吗？`],[`得，我而家傳畀你。`,`dak1, ngo5 ji4 gaa1 cyun4 bei2 nei5.`,`可以，我现在发给你。`],[`收到，今日下晝方唔方便上門睇吓？`,`sau1 dou2, gam1 jat6 haa6 zau3 fong1 m4 fong1 bin6 soeng5 mun4 tai2 haa5?`,`收到了，今天下午方便上门看看吗？`],[`三點之後得，整之前可唔可以先報價？`,`saam1 dim2 zi1 hau6 dak1, zing2 zi1 cin4 ho2 m4 ho2 ji5 sin1 bou3 gaa3?`,`三点后可以，修之前可以先报价吗？`],[`可以，睇清楚問題再同你講。`,`ho2 ji5, tai2 cing1 co2 man6 tai4 zoi3 tung4 nei5 gong2.`,`可以，看清楚问题再告诉你。`],[`冷氣開咗都唔凍。`,`laang5 hei3 hoi1 zo2 dou1 m4 dung3.`,`空调开了也不凉。`],[`廚房盞燈成日閃。`,`cyu4 fong2 zaan2 dang1 seng4 jat6 sim2.`,`厨房那盏灯总是闪。`],[`呢個插蘇好似鬆咗。`,`ni1 go3 caap3 sou1 hou2 ci5 sung1 zo2.`,`这个插座好像松了。`],[`唔該整完試吓仲漏唔漏。`,`m4 goi1 zing2 jyun4 si3 haa5 zung6 lau6 m4 lau6.`,`请修好后试一下还漏不漏。`]],words:[[`水龍頭`,`seoi2 lung4 tau4`,`水龙头`],[`漏水`,`lau6 seoi2`,`漏水`],[`勁`,`ging6`,`厉害；严重`],[`滴水`,`dik1 seoi2`,`滴水`],[`影相`,`jing2 soeng2`,`拍照`],[`上門`,`soeng5 mun4`,`上门`],[`整`,`zing2`,`修理；弄`],[`報價`,`bou3 gaa3`,`报价`],[`成日`,`seng4 jat6`,`经常；总是`],[`插蘇`,`caap3 sou1`,`插座；插头连接件`]],patterns:[[`……咗幾耐？`,`询问某种状态已经持续了多久。`,`壞咗幾耐？`],[`……之前可唔可以先……？`,`在正式处理前提出希望先确认的事项。`,`換零件之前可唔可以先同我講？`]],cultureNote:`「整」可表示修理，也可泛指动手处理。「报修」时按物件、症状、开始时间的顺序说，对方比较容易了解；涉及具体维修和收费，先请师傅查看并确认。`,practicePrompt:`你家的空调开了不凉，从前天开始。向师傅说明症状，约明天下午上门，并要求换零件前先确认报价。`}),t({id:`home-deliveries`,topicId:`home`,level:2,title:`速遞到樓下`,description:`收件地址、签收与改约`,speakers:[`速遞員`,`收件人`],phrases:[[`喂，你好，速遞到咗樓下。`,`wai2, nei5 hou2, cuk1 dai6 dou3 zo2 lau4 haa6.`,`喂，你好，快递到楼下了。`],[`唔該，我而家唔喺屋企。`,`m4 goi1, ngo5 ji4 gaa1 m4 hai2 uk1 kei2.`,`谢谢，我现在不在家。`],[`咁你想點樣收件？`,`gam2 nei5 soeng2 dim2 joeng6 sau1 gin6?`,`那你想怎样收件？`],[`可唔可以聽日朝早再送？`,`ho2 m4 ho2 ji5 ting1 jat6 ziu1 zou2 zoi3 sung3?`,`可以明天早上再送吗？`],[`我幫你睇吓可唔可以改時間。`,`ngo5 bong1 nei5 tai2 haa5 ho2 m4 ho2 ji5 goi2 si4 gaan3.`,`我帮你看看能不能改时间。`],[`好呀，送之前麻煩打畀我。`,`hou2 aa3, sung3 zi1 cin4 maa4 faan4 daa2 bei2 ngo5.`,`好的，送之前麻烦给我打电话。`],[`收到，請確認收件人姓名。`,`sau1 dou2, cing2 kok3 jan6 sau1 gin6 jan4 sing3 meng2.`,`收到了，请确认收件人姓名。`],[`姓陳，陳小明，唔該晒。`,`sing3 can4, can4 siu2 ming4, m4 goi1 saai3.`,`姓陈，陈小明，非常感谢。`],[`唔該等我兩分鐘，我即刻落嚟。`,`m4 goi1 dang2 ngo5 loeng5 fan1 zung1, ngo5 zik1 hak1 lok6 lai4.`,`麻烦等我两分钟，我马上下来。`],[`件貨個盒凹咗，可唔可以記低？`,`gin6 fo3 go3 hap6 nap1 zo2, ho2 m4 ho2 ji5 gei3 dai1?`,`包裹的盒子凹了，可以记录一下吗？`],[`呢件好似唔係我嘅，麻煩核對吓。`,`ni1 gin6 hou2 ci5 m4 hai6 ngo5 ge3, maa4 faan4 hat6 deoi3 haa5.`,`这件好像不是我的，麻烦核对一下。`],[`我想改去自提點攞。`,`ngo5 soeng2 goi2 heoi3 zi6 tai4 dim2 lo2.`,`我想改到自提点领取。`]],words:[[`速遞`,`cuk1 dai6`,`快递`],[`收件`,`sau1 gin6`,`收快件`],[`朝早`,`ziu1 zou2`,`早上`],[`改時間`,`goi2 si4 gaan3`,`改时间`],[`收件人`,`sau1 gin6 jan4`,`收件人`],[`姓名`,`sing3 meng2`,`姓名`],[`即刻`,`zik1 hak1`,`马上`],[`凹`,`nap1`,`凹陷`],[`核對`,`hat6 deoi3`,`核对`],[`自提點`,`zi6 tai4 dim2`,`自提点`]],patterns:[[`……之前麻煩……`,`请求对方在某个步骤前先做一件事。`,`上樓之前麻煩打畀我。`],[`我想改去……`,`提出改变原定的交收地点。`,`我想改去公司收件。`]],cultureNote:`「速递」和「快递」都能理解，香港常见前者。「攞件」就是领取包裹。改时间、改地址或自提安排，要由速递方核实能否办理。`,practicePrompt:`快递到时你不在家。先询问能否改约明早，再请求送前来电。收到包裹后发现外盒凹了，请对方记录并核对收件人。`}),t({id:`home-neighbours`,topicId:`home`,level:3,title:`隔籬住，好商量`,description:`邻里问候、噪声与公共空间`,speakers:[`住客`,`鄰居`],phrases:[[`你好，我新搬嚟，住你隔籬。`,`nei5 hou2, ngo5 san1 bun1 lai4, zyu6 nei5 gaak3 lei4.`,`你好，我刚搬来，住你旁边。`],[`你好，歡迎呀，有咩需要可以問我。`,`nei5 hou2, fun1 jing4 aa3, jau5 me1 seoi1 jiu3 ho2 ji5 man6 ngo5.`,`你好，欢迎，有什么需要可以问我。`],[`唔該晒。唔好意思，尋晚聽到啲聲。`,`m4 goi1 saai3. m4 hou2 ji3 si1, cam4 maan5 teng1 dou2 di1 seng1.`,`谢谢。不好意思，昨晚听到一些声音。`],[`係咩？可能我搬枱整到。`,`hai6 me1? ho2 nang4 ngo5 bun1 toi2 zing2 dou3.`,`是吗？可能是我搬桌子弄出来的。`],[`因為我朝早要返工，夜晚想早啲瞓。`,`jan1 wai6 ngo5 ziu1 zou2 jiu3 faan1 gung1, je6 maan5 soeng2 zou2 di1 fan3.`,`因为我早上要上班，晚上想早点睡。`],[`明白，我遲啲會小心啲。`,`ming4 baak6, ngo5 ci4 di1 wui5 siu2 sam1 di1.`,`明白，我之后会多注意。`],[`多謝你體諒，有嘢再商量。`,`do1 ze6 nei5 tai2 loeng6, jau5 je5 zoi3 soeng1 loeng4.`,`谢谢你体谅，有事再商量。`],[`好呀，大家住得舒服最緊要。`,`hou2 aa3, daai6 gaa1 zyu6 dak1 syu1 fuk6 zeoi3 gan2 jiu3.`,`好的，大家住得舒服最重要。`],[`唔好意思，呢個紙箱可唔可以移開少少？`,`m4 hou2 ji3 si1, ni1 go3 zi2 soeng1 ho2 m4 ho2 ji5 ji4 hoi1 siu2 siu2?`,`不好意思，这个纸箱可以挪开一点吗？`],[`門口留返條路畀大家行，唔該。`,`mun4 hau2 lau4 faan1 tiu4 lou6 bei2 daai6 gaa1 haang4, m4 goi1.`,`门口留出一条路让大家走，谢谢。`],[`如果太嘈，麻煩你提我一聲。`,`jyu4 gwo2 taai3 cou4, maa4 faan4 nei5 tai4 ngo5 jat1 seng1.`,`如果太吵，麻烦提醒我一声。`],[`我哋一齊問吓管理處，好唔好？`,`ngo5 dei6 jat1 cai4 man6 haa5 gun2 lei5 cyu3, hou2 m4 hou2?`,`我们一起问一下管理处，好吗？`]],words:[[`搬嚟`,`bun1 lai4`,`搬来`],[`隔籬`,`gaak3 lei4`,`隔壁；旁边`],[`歡迎`,`fun1 jing4`,`欢迎`],[`整到`,`zing2 dou3`,`弄出来；造成`],[`瞓`,`fan3`,`睡觉`],[`體諒`,`tai2 loeng6`,`体谅`],[`商量`,`soeng1 loeng4`,`商量`],[`移開`,`ji4 hoi1`,`挪开`],[`嘈`,`cou4`,`吵`],[`管理處`,`gun2 lei5 cyu3`,`管理处`]],patterns:[[`因為……，……想……`,`说明自己的实际情况，再提出需要。`,`因為聽日要早起，我想早啲瞓。`],[`如果……，麻煩你……`,`预先约定出现问题时怎样沟通。`,`如果阻到你，麻煩你提我。`]],cultureNote:`与邻居说问题时，先讲自己听到或遇到的情况，再说明需要，语气通常更容易被接受。「提我一声」是请对方简短提醒；需要共同核实时可一起找管理处。`,practicePrompt:`向新邻居打招呼，然后礼貌地提出昨晚有噪声的问题，解释自己要早起。再练习请对方把门口纸箱挪开，并约定有事互相提醒。`})],c=[t({id:`services-appointment`,topicId:`services`,level:2,title:`预约与等候`,description:`预约、报到与轮候时间`,speakers:[`顾客`,`接待员`],phrases:[[`你好，我約咗今日下晝。`,`nei5 hou2 ngo5 joek3 zo2 gam1 jat6 haa6 zau3`,`你好，我预约了今天下午。`],[`請問你貴姓？`,`cing2 man6 nei5 gwai3 sing3`,`请问您贵姓？`],[`我姓陳，約咗兩點半。`,`ngo5 sing3 can4 joek3 zo2 loeng5 dim2 bun3`,`我姓陈，预约了两点半。`],[`搵到喇，請你坐低等一陣。`,`wan2 dou2 laa3 cing2 nei5 co5 dai1 dang2 jat1 zan6`,`找到了，请你坐下等一会儿。`],[`大概要等幾耐呀？`,`daai6 koi3 jiu3 dang2 gei2 noi6 aa3`,`大概要等多久？`],[`前面仲有兩位，大概十五分鐘。`,`cin4 min6 zung6 jau5 loeng5 wai2 daai6 koi3 sap6 ng5 fan1 zung1`,`前面还有两位，大约十五分钟。`],[`我可唔可以落樓買支水先？`,`ngo5 ho2 m4 ho2 ji5 lok6 lau4 maai5 zi1 seoi2 sin1`,`我可以先下楼买瓶水吗？`],[`可以，返嚟嗰陣話我知就得。`,`ho2 ji5 faan1 lai4 go2 zan6 waa6 ngo5 zi1 zau6 dak1`,`可以，回来时告诉我就行。`],[`我想改去聽日朝早。`,`ngo5 soeng2 goi2 heoi3 ting1 jat6 ziu1 zou2`,`我想改到明天早上。`],[`唔好意思，我會遲十分鐘。`,`m4 hou2 ji3 si1 ngo5 wui5 ci4 sap6 fan1 zung1`,`不好意思，我会迟到十分钟。`],[`麻煩你幫我取消預約。`,`maa4 faan4 nei5 bong1 ngo5 ceoi2 siu1 jyu6 joek3`,`麻烦你帮我取消预约。`],[`到我嗰陣，會唔會叫名呀？`,`dou3 ngo5 go2 zan6 wui5 m4 wui5 giu3 meng2 aa3`,`轮到我时，会叫名字吗？`]],words:[[`預約`,`jyu6 joek3`,`预约`],[`貴姓`,`gwai3 sing3`,`贵姓`],[`下晝`,`haa6 zau3`,`下午`],[`坐低`,`co5 dai1`,`坐下`],[`等一陣`,`dang2 jat1 zan6`,`等一会儿`],[`幾耐`,`gei2 noi6`,`多久`],[`前面`,`cin4 min6`,`前面`],[`落樓`,`lok6 lau4`,`下楼`],[`返嚟`,`faan1 lai4`,`回来`],[`取消`,`ceoi2 siu1`,`取消`]],patterns:[[`約咗＋時間`,`用“咗”说明预约已经办好。`,`我約咗今日下晝。`],[`……嗰陣，……`,`说明某个时刻要做的事。`,`返嚟嗰陣話我知。`]],cultureNote:`报到时先说预约时间和姓氏。离开等候区前，向接待员确认会不会过号，避免只凭估计离开。`,practicePrompt:`把预约改为周五早上，询问需要提早多久到，并确认叫名还是取筹。`}),t({id:`services-bank`,topicId:`services`,level:2,title:`银行柜台办事`,description:`取号、转账、费用与所需文件`,speakers:[`顾客`,`银行职员`],phrases:[[`唔該，我想去櫃位辦手續。`,`m4 goi1 ngo5 soeng2 heoi3 gwai6 wai2 baan6 sau2 zuk6`,`你好，我想去柜台办理手续。`],[`請先攞籌，等叫號碼。`,`cing2 sin1 lo2 cau4 dang2 giu3 hou6 maa5`,`请先取号，等候叫号。`],[`我想轉錢去另一個戶口。`,`ngo5 soeng2 zyun2 cin2 heoi3 ling6 jat1 go3 wu6 hau2`,`我想把钱转到另一个账户。`],[`請你填好呢張表。`,`cing2 nei5 tin4 hou2 ni1 zoeng1 biu2`,`请你填好这张表。`],[`呢度要填收款人個名呀？`,`ni1 dou6 jiu3 tin4 sau1 fun2 jan4 go3 meng2 aa3`,`这里要填收款人的名字吗？`],[`係，仲要填戶口號碼。`,`hai6 zung6 jiu3 tin4 wu6 hau2 hou6 maa5`,`对，还要填账户号码。`],[`請問有冇手續費？`,`cing2 man6 jau5 mou5 sau2 zuk6 fai3`,`请问有手续费吗？`],[`我幫你查清楚先。`,`ngo5 bong1 nei5 caa4 cing1 co2 sin1`,`我先帮你查清楚。`],[`可唔可以俾張收據我？`,`ho2 m4 ho2 ji5 bei2 zoeng1 sau1 geoi3 ngo5`,`可以给我一张收据吗？`],[`我想更新聯絡電話。`,`ngo5 soeng2 gang1 san1 lyun4 lok3 din6 waa2`,`我想更新联系电话。`],[`需要帶邊啲文件？`,`seoi1 jiu3 daai3 bin1 di1 man4 gin6`,`需要带哪些文件？`],[`麻煩你再核對一次資料。`,`maa4 faan4 nei5 zoi3 hat6 deoi3 jat1 ci3 zi1 liu2`,`麻烦你再核对一次资料。`]],words:[[`櫃位`,`gwai6 wai2`,`柜台`],[`手續`,`sau2 zuk6`,`手续`],[`攞籌`,`lo2 cau4`,`取号`],[`號碼`,`hou6 maa5`,`号码`],[`戶口`,`wu6 hau2`,`账户`],[`收款人`,`sau1 fun2 jan4`,`收款人`],[`手續費`,`sau2 zuk6 fai3`,`手续费`],[`收據`,`sau1 geoi3`,`收据`],[`文件`,`man4 gin6`,`文件`],[`核對`,`hat6 deoi3`,`核对`]],patterns:[[`我想＋辦理事項`,`在柜台清楚说明要办理什么。`,`我想更新聯絡電話。`],[`需要＋動作＋邊啲＋名詞？`,`询问具体要准备的材料。`,`需要帶邊啲文件？`]],cultureNote:`银行通常按业务类别安排取筹。不同账户和转账方式的要求可能不同，课程里的问句用于向职员确认实际安排。`,practicePrompt:`模拟在柜台更新地址，先询问所需证明文件，再确认办理后会不会收到通知。`}),t({id:`services-mobile`,topicId:`services`,level:2,title:`手机与上网服务`,description:`月费、流量与合约`,speakers:[`顾客`,`店员`],phrases:[[`我想問吓手機上網計劃。`,`ngo5 soeng2 man6 haa5 sau2 gei1 soeng5 mong5 gai3 waak6`,`我想咨询手机上网套餐。`],[`你平時用得多唔多數據？`,`nei5 ping4 si4 jung6 dak1 do1 m4 do1 sou3 geoi3`,`你平常使用的流量多吗？`],[`我成日睇片，想要多啲數據。`,`ngo5 seng4 jat6 tai2 pin2 soeng2 jiu3 do1 di1 sou3 geoi3`,`我经常看视频，想要多一些流量。`],[`呢個計劃有合約期。`,`ni1 go3 gai3 waak6 jau5 hap6 joek3 kei4`,`这个套餐有合约期。`],[`合約要簽幾耐？`,`hap6 joek3 jiu3 cim1 gei2 noi6`,`合约要签多久？`],[`兩年，月費同其他收費寫晒喺度。`,`loeng5 nin4 jyut6 fai3 tung4 kei4 taa1 sau1 fai3 se2 saai3 hai2 dou6`,`两年，月费和其他收费全写在这里。`],[`我想睇埋冇合約嗰啲。`,`ngo5 soeng2 tai2 maai4 mou5 hap6 joek3 go2 di1`,`我还想看看没有合约的那些。`],[`得，我拎資料俾你比較。`,`dak1 ngo5 ling1 zi1 liu2 bei2 nei5 bei2 gaau3`,`行，我拿资料给你比较。`],[`可唔可以保留而家個電話號碼？`,`ho2 m4 ho2 ji5 bou2 lau4 ji4 gaa1 go3 din6 waa2 hou6 maa5`,`可以保留现在的电话号码吗？`],[`用晒數據之後會點？`,`jung6 saai3 sou3 geoi3 zi1 hau6 wui5 dim2`,`流量用完后会怎样？`],[`漫遊服務要另外申請呀？`,`maan6 jau4 fuk6 mou6 jiu3 ling6 ngoi6 san1 cing2 aa3`,`漫游服务要另外申请吗？`],[`我想取消自動續約。`,`ngo5 soeng2 ceoi2 siu1 zi6 dung6 zuk6 joek3`,`我想取消自动续约。`]],words:[[`上網`,`soeng5 mong5`,`上网`],[`計劃`,`gai3 waak6`,`套餐；计划`],[`數據`,`sou3 geoi3`,`流量；数据`],[`睇片`,`tai2 pin2`,`看视频`],[`合約`,`hap6 joek3`,`合约`],[`月費`,`jyut6 fai3`,`月费`],[`收費`,`sau1 fai3`,`收费`],[`保留`,`bou2 lau4`,`保留`],[`漫遊`,`maan6 jau4`,`漫游`],[`續約`,`zuk6 joek3`,`续约`]],patterns:[[`動詞＋晒＋賓語`,`“晒”表示全部完成或用尽。`,`用晒數據之後會點？`],[`想＋動詞＋埋＋其他選項`,`“埋”表示把另一个选项也包括进来。`,`我想睇埋冇合約嗰啲。`]],cultureNote:`香港日常说“上台”常指办理月费手机服务，“儲值卡”指预付费卡。办理前可请店员把合约期、收费和续约方式逐项说清。`,practicePrompt:`你只住三个月，向店员说明使用需求，询问无合约方案，并确认流量用完后的安排。`}),t({id:`services-clinic`,topicId:`services`,level:2,title:`预约看医生`,description:`诊症时段、身体不适与登记`,speakers:[`来电者`,`诊所职员`],phrases:[[`你好，我想預約睇醫生。`,`nei5 hou2 ngo5 soeng2 jyu6 joek3 tai2 ji1 sang1`,`你好，我想预约看医生。`],[`你想約今日定聽日？`,`nei5 soeng2 joek3 gam1 jat6 ding6 ting1 jat6`,`你想约今天还是明天？`],[`今日仲有冇位？`,`gam1 jat6 zung6 jau5 mou5 wai2`,`今天还有名额吗？`],[`下晝四點仲有一個位。`,`haa6 zau3 sei3 dim2 zung6 jau5 jat1 go3 wai2`,`下午四点还有一个名额。`],[`可以，我第一次嚟呢間診所。`,`ho2 ji5 ngo5 dai6 jat1 ci3 lai4 ni1 gaan1 can2 so2`,`可以，我第一次来这家诊所。`],[`請你早少少嚟登記。`,`cing2 nei5 zou2 siu2 siu2 lai4 dang1 gei3`,`请你提前一点来登记。`],[`要帶啲咩資料？`,`jiu3 daai3 di1 me1 zi1 liu2`,`要带什么资料？`],[`請帶身份證，同埋你想俾醫生睇嘅紀錄。`,`cing2 daai3 san1 fan6 zing3 tung4 maai4 nei5 soeng2 bei2 ji1 sang1 tai2 ge3 gei3 luk6`,`请带身份证，以及你想给医生看的记录。`],[`我由尋晚開始唔舒服。`,`ngo5 jau4 cam4 maan5 hoi1 ci2 m4 syu1 fuk6`,`我从昨晚开始不舒服。`],[`我想同醫生講清楚個情況。`,`ngo5 soeng2 tung4 ji1 sang1 gong2 cing1 co2 go3 cing4 fong3`,`我想向医生说清楚情况。`],[`我對某啲藥有敏感。`,`ngo5 deoi3 mau5 di1 joek6 jau5 man5 gam2`,`我对某些药物过敏。`,`就诊时应进一步告诉医护人员已知的具体药名和反应。`],[`可唔可以寫低俾我睇？`,`ho2 m4 ho2 ji5 se2 dai1 bei2 ngo5 tai2`,`可以写下来给我看吗？`]],words:[[`睇醫生`,`tai2 ji1 sang1`,`看医生`],[`診所`,`can2 so2`,`诊所`],[`登記`,`dang1 gei3`,`登记`],[`身份證`,`san1 fan6 zing3`,`身份证`],[`紀錄`,`gei3 luk6`,`记录`],[`尋晚`,`cam4 maan5`,`昨晚`],[`唔舒服`,`m4 syu1 fuk6`,`不舒服`],[`情況`,`cing4 fong3`,`情况`],[`敏感`,`man5 gam2`,`过敏；敏感`],[`寫低`,`se2 dai1`,`写下来`]],patterns:[[`由＋時間＋開始……`,`交代情况开始的时间。`,`我由尋晚開始唔舒服。`],[`今日定聽日？`,`“定”连接问句中的两个选择。`,`你想約今日定聽日？`]],cultureNote:`“睇醫生”是日常说法；“有敏感”在就医语境可指过敏。描述症状、既往用药和过敏情况时，可请医护人员复述或写下重点。`,practicePrompt:`打电话预约明天上午，说明这是首次到诊，再练习向医生交代不适从什么时候开始。`}),t({id:`services-pharmacy`,topicId:`services`,level:2,title:`药房咨询`,description:`药剂师咨询、用药情况与药品标签`,speakers:[`顾客`,`药房职员`],phrases:[[`唔該，我想搵藥劑師問吓。`,`m4 goi1 ngo5 soeng2 wan2 joek6 zai1 si1 man6 haa5`,`你好，我想找药剂师咨询一下。`],[`請等一陣，我幫你叫佢。`,`cing2 dang2 jat1 zan6 ngo5 bong1 nei5 giu3 keoi5`,`请等一会儿，我帮你叫他。`],[`我想問呢隻藥嘅資料。`,`ngo5 soeng2 man6 ni1 zek3 joek6 ge3 zi1 liu2`,`我想问这种药的相关信息。`],[`你有冇帶個藥盒嚟？`,`nei5 jau5 mou5 daai3 go3 joek6 hap6 lai4`,`你带药盒来了吗？`],[`有，標籤有啲字我睇唔明。`,`jau5 biu1 cim1 jau5 di1 zi6 ngo5 tai2 m4 ming4`,`有，标签上有些字我看不懂。`],[`你想問邊一部分？`,`nei5 soeng2 man6 bin1 jat1 bou6 fan6`,`你想问哪一部分？`],[`想請你講解用法同注意事項。`,`soeng2 cing2 nei5 gong2 gaai2 jung6 faat3 tung4 zyu3 ji3 si6 hong6`,`想请你解释用法和注意事项。`],[`好，我請藥劑師同你講清楚。`,`hou2 ngo5 cing2 joek6 zai1 si1 tung4 nei5 gong2 cing1 co2`,`好的，我请药剂师向你说明白。`],[`我而家食緊其他藥。`,`ngo5 ji4 gaa1 sik6 gan2 kei4 taa1 joek6`,`我现在正在服用其他药物。`],[`呢張相有齊啲藥名。`,`ni1 zoeng1 soeng2 jau5 cai4 di1 joek6 meng2`,`这张照片列全了药名。`],[`呢個藥盒上面嘅日期係咩意思？`,`ni1 go3 joek6 hap6 soeng6 min6 ge3 jat6 kei4 hai6 me1 ji3 si1`,`这个药盒上面的日期是什么意思？`],[`可唔可以寫低要留意嘅嘢？`,`ho2 m4 ho2 ji5 se2 dai1 jiu3 lau4 ji3 ge3 je5`,`可以写下需要注意的事项吗？`]],words:[[`藥房`,`joek6 fong4`,`药房`],[`藥劑師`,`joek6 zai1 si1`,`药剂师`],[`藥盒`,`joek6 hap6`,`药盒`],[`標籤`,`biu1 cim1`,`标签`],[`睇唔明`,`tai2 m4 ming4`,`看不懂`],[`講解`,`gong2 gaai2`,`解释`],[`用法`,`jung6 faat3`,`用法`],[`注意事項`,`zyu3 ji3 si6 hong6`,`注意事项`],[`藥名`,`joek6 meng2`,`药名`],[`日期`,`jat6 kei4`,`日期`]],patterns:[[`睇唔明＋內容`,`表示看到了文字却不理解意思。`,`標籤有啲字我睇唔明。`],[`動詞＋緊＋賓語`,`表示动作正在进行。`,`我而家食緊其他藥。`]],cultureNote:`本课练习的是咨询与核对信息。可带原包装或清晰照片，让药剂师识别具体药物，再由药剂师解释适用信息。`,practicePrompt:`拿着一张药盒照片，请药剂师解释标签，并说明自己另有正在服用的药物。`}),t({id:`services-lost-property`,topicId:`services`,level:2,title:`失物与求助`,description:`失物特征、遗失地点与联系方式`,speakers:[`失主`,`服务台职员`],phrases:[[`唔該，我唔見咗個銀包。`,`m4 goi1 ngo5 m4 gin3 zo2 go3 ngan4 baau1`,`你好，我的钱包不见了。`],[`你最後喺邊度見過？`,`nei5 zeoi3 hau6 hai2 bin1 dou6 gin3 gwo3`,`你最后在哪里见过它？`],[`頭先喺樓下間咖啡店。`,`tau4 sin1 hai2 lau4 haa6 gaan1 gaa3 fe1 dim3`,`刚才在楼下那家咖啡店。`],[`個銀包咩顏色㗎？`,`go3 ngan4 baau1 me1 ngaan4 sik1 gaa3`,`钱包是什么颜色的？`],[`深藍色，入面有張交通卡。`,`sam1 laam4 sik1 jap6 min6 jau5 zoeng1 gaau1 tung1 kaat1`,`深蓝色，里面有一张交通卡。`],[`我幫你問吓有冇人執到。`,`ngo5 bong1 nei5 man6 haa5 jau5 mou5 jan4 zap1 dou2`,`我帮你问问有没有人捡到。`],[`麻煩你，有消息可以打俾我。`,`maa4 faan4 nei5 jau5 siu1 sik1 ho2 ji5 daa2 bei2 ngo5`,`麻烦你，有消息可以打电话给我。`],[`好，請留低你個名同電話。`,`hou2 cing2 lau4 dai1 nei5 go3 meng2 tung4 din6 waa2`,`好的，请留下姓名和电话。`],[`我大概一個鐘之前仲用過。`,`ngo5 daai6 koi3 jat1 go3 zung1 zi1 cin4 zung6 jung6 gwo3`,`我大约一小时前还用过。`],[`請問失物認領處喺邊？`,`cing2 man6 sat1 mat6 jing6 ling5 cyu3 hai2 bin1`,`请问失物认领处在哪里？`],[`我想報失，要去邊度？`,`ngo5 soeng2 bou3 sat1 jiu3 heoi3 bin1 dou6`,`我想报失，要去哪里？`],[`攞返嗰陣要帶啲咩證明？`,`lo2 faan1 go2 zan6 jiu3 daai3 di1 me1 zing3 ming4`,`领回时要带什么证明？`]],words:[[`唔見咗`,`m4 gin3 zo2`,`不见了`],[`銀包`,`ngan4 baau1`,`钱包`],[`最後`,`zeoi3 hau6`,`最后`],[`頭先`,`tau4 sin1`,`刚才`],[`深藍色`,`sam1 laam4 sik1`,`深蓝色`],[`執到`,`zap1 dou2`,`捡到`],[`消息`,`siu1 sik1`,`消息`],[`留低`,`lau4 dai1`,`留下`],[`報失`,`bou3 sat1`,`报失`],[`認領`,`jing6 ling5`,`认领`]],patterns:[[`唔見咗＋物品`,`说明物品遗失。`,`我唔見咗個銀包。`],[`有＋情況＋可以……`,`说明条件出现后可采取的行动。`,`有消息可以打俾我。`]],cultureNote:`描述失物时，颜色、特征、最后使用的地点和时间比只说物品名称更有帮助。领取时可主动询问核实身份所需的证明。`,practicePrompt:`你的黑色背包遗留在巴士上，向服务台描述背包，交代路线和下车时间，并留下联系方式。`})],l=[t({id:`friends-interests`,topicId:`friends`,level:2,title:`从兴趣聊起来`,description:`徒步、摄影与休闲爱好`,speakers:[`阿欣`,`阿杰`],phrases:[[`你平時放假鍾意做啲咩？`,`nei5 ping4 si4 fong3 gaa3 zung1 ji3 zou6 di1 me1`,`你平常放假喜欢做什么？`],[`我鍾意行山，你呢？`,`ngo5 zung1 ji3 haang4 saan1 nei5 ne1`,`我喜欢爬山，你呢？`],[`我都鍾意，不過行得唔多。`,`ngo5 dou1 zung1 ji3 bat1 gwo3 haang4 dak1 m4 do1`,`我也喜欢，不过去得不多。`],[`你通常去邊度行？`,`nei5 tung1 soeng4 heoi3 bin1 dou6 haang4`,`你通常去哪里爬山？`],[`多數去近屋企嗰啲路線。`,`do1 sou3 heoi3 gan6 uk1 kei2 go2 di1 lou6 sin3`,`多数去离家近的那些路线。`],[`我仲鍾意沿途影相。`,`ngo5 zung6 zung1 ji3 jyun4 tou4 jing2 soeng2`,`我还喜欢沿途拍照。`],[`咁啱嘅，我最近都學緊影相。`,`gam3 ngaam1 ge2 ngo5 zeoi3 gan6 dou1 hok6 gan2 jing2 soeng2`,`这么巧，我最近也在学摄影。`],[`下次可以一齊去試吓。`,`haa6 ci3 ho2 ji5 jat1 cai4 heoi3 si3 haa5`,`下次可以一起去试试。`],[`除咗行山，你仲有咩興趣？`,`ceoi4 zo2 haang4 saan1 nei5 zung6 jau5 me1 hing3 ceoi3`,`除了爬山，你还有什么兴趣？`],[`我間中會去睇戲。`,`ngo5 gaan3 zung1 wui5 heoi3 tai2 hei3`,`我偶尔会去看电影。`],[`我對呢方面唔係好熟。`,`ngo5 deoi3 ni1 fong1 min6 m4 hai6 hou2 suk6`,`我对这方面不太熟悉。`],[`有冇好介紹？`,`jau5 mou5 hou2 gaai3 siu6`,`有什么好推荐吗？`]],words:[[`放假`,`fong3 gaa3`,`放假；休息`],[`鍾意`,`zung1 ji3`,`喜欢`],[`行山`,`haang4 saan1`,`爬山；徒步`],[`通常`,`tung1 soeng4`,`通常`],[`路線`,`lou6 sin3`,`路线`],[`沿途`,`jyun4 tou4`,`沿途`],[`影相`,`jing2 soeng2`,`拍照`],[`興趣`,`hing3 ceoi3`,`兴趣`],[`間中`,`gaan3 zung1`,`偶尔`],[`介紹`,`gaai3 siu6`,`介绍；推荐`]],patterns:[[`除咗＋事情，仲有……`,`从已知话题延伸到其他内容。`,`除咗行山，你仲有咩興趣？`],[`我對＋方面＋唔係好熟`,`说明自己了解有限，也可请对方继续介绍。`,`我對呢方面唔係好熟。`]],cultureNote:`闲聊时，一句“你呢？”能把话题交回对方。对不熟悉的兴趣不必假装懂，问“有冇好介紹？”也能自然接话。`,practicePrompt:`向新朋友介绍你真正喜欢的一项活动，再追问对方的频率、地点和入门建议。`}),t({id:`friends-invitation`,topicId:`friends`,level:2,title:`约朋友见面`,description:`聚会邀请、时间与地点`,speakers:[`阿欣`,`阿杰`],phrases:[[`星期六得唔得閒食飯？`,`sing1 kei4 luk6 dak1 m4 dak1 haan4 sik6 faan6`,`星期六有空吃饭吗？`],[`得呀，約幾點？`,`dak1 aa3 joek3 gei2 dim2`,`有空，约几点？`],[`七點左右，你方唔方便？`,`cat1 dim2 zo2 jau6 nei5 fong1 m4 fong1 bin6`,`七点左右，你方便吗？`],[`我六點收工，七點應該趕得切。`,`ngo5 luk6 dim2 sau1 gung1 cat1 dim2 jing1 goi1 gon2 dak1 cit3`,`我六点下班，七点应该来得及。`],[`想食啲咩？你揀吖。`,`soeng2 sik6 di1 me1 nei5 gaan2 aa1`,`想吃什么？你选吧。`],[`不如試吓地鐵站附近間新舖。`,`bat1 jyu4 si3 haa5 dei6 tit3 zaam6 fu6 gan6 gaan1 san1 pou3`,`不如试试地铁站附近那家新店。`],[`好呀，我訂位，再發地址俾你。`,`hou2 aa3 ngo5 deng6 wai2 zoi3 faat3 dei6 zi2 bei2 nei5`,`好呀，我订位后再把地址发给你。`],[`好，當日見，有變再聯絡。`,`hou2 dong1 jat6 gin3 jau5 bin3 zoi3 lyun4 lok3`,`好，当天见，有变化再联系。`],[`介唔介意我帶個朋友嚟？`,`gaai3 m4 gaai3 ji3 ngo5 daai3 go3 pang4 jau5 lai4`,`介意我带一位朋友来吗？`],[`我哋喺邊個出口等？`,`ngo5 dei6 hai2 bin1 go3 ceot1 hau2 dang2`,`我们在哪个出口等？`],[`我到咗會發訊息俾你。`,`ngo5 dou3 zo2 wui5 faat3 seon3 sik1 bei2 nei5`,`我到了会发消息给你。`],[`如果落雨，我哋改去室內。`,`jyu4 gwo2 lok6 jyu5 ngo5 dei6 goi2 heoi3 sat1 noi6`,`如果下雨，我们改去室内。`]],words:[[`得閒`,`dak1 haan4`,`有空`],[`左右`,`zo2 jau6`,`左右；大约`],[`方便`,`fong1 bin6`,`方便`],[`收工`,`sau1 gung1`,`下班`],[`趕得切`,`gon2 dak1 cit3`,`来得及`],[`揀`,`gaan2`,`挑选`],[`訂位`,`deng6 wai2`,`订位`],[`地址`,`dei6 zi2`,`地址`],[`出口`,`ceot1 hau2`,`出口`],[`室內`,`sat1 noi6`,`室内`]],patterns:[[`得唔得閒＋活動？`,`先询问对方有无时间，语气自然。`,`星期六得唔得閒食飯？`],[`如果＋情況，我哋＋安排`,`为不确定的情况预先商量替代安排。`,`如果落雨，我哋改去室內。`]],cultureNote:`朋友间“食飯”可以是简单邀约。确定后补充具体时间、分店和出口，能减少到场后的来回找路。`,practicePrompt:`约一位朋友周日下午喝茶，商量一个交通方便的地点，并约定下雨时的安排。`}),t({id:`friends-decline`,topicId:`friends`,level:2,title:`婉拒与改约`,description:`婉拒理由、改约与回复`,speakers:[`阿杰`,`阿欣`],phrases:[[`今晚一齊去睇戲，好唔好？`,`gam1 maan5 jat1 cai4 heoi3 tai2 hei3 hou2 m4 hou2`,`今晚一起去看电影，好吗？`],[`多謝你約我，不過今晚唔得閒。`,`do1 ze6 nei5 joek3 ngo5 bat1 gwo3 gam1 maan5 m4 dak1 haan4`,`谢谢你约我，不过今晚没有空。`],[`咁聽晚得唔得？`,`gam2 ting1 maan5 dak1 m4 dak1`,`那明晚行吗？`],[`聽晚都約咗人，真係唔好意思。`,`ting1 maan5 dou1 joek3 zo2 jan4 zan1 hai6 m4 hou2 ji3 si1`,`明晚也已经约了人，真不好意思。`],[`唔緊要，下次先啦。`,`m4 gan2 jiu3 haa6 ci3 sin1 laa1`,`没关系，下次吧。`],[`不如下個星期再約？`,`bat1 jyu4 haa6 go3 sing1 kei4 zoi3 joek3`,`不如下个星期再约？`],[`好呀，你得閒嗰陣話我知。`,`hou2 aa3 nei5 dak1 haan4 go2 zan6 waa6 ngo5 zi1`,`好呀，你有空时告诉我。`],[`得，我睇吓時間再覆你。`,`dak1 ngo5 tai2 haa5 si4 gaan3 zoi3 fuk1 nei5`,`行，我看看时间再回复你。`],[`我今次想留喺屋企休息。`,`ngo5 gam1 ci3 soeng2 lau4 hai2 uk1 kei2 jau1 sik1`,`我这次想留在家里休息。`],[`我未肯定去唔去到。`,`ngo5 mei6 hang2 ding6 heoi3 m4 heoi3 dou2`,`我还不能确定能不能去。`],[`你哋玩得開心啲。`,`nei5 dei6 waan2 dak1 hoi1 sam1 di1`,`你们玩得开心点。`],[`今次去唔到，下次預埋我。`,`gam1 ci3 heoi3 m4 dou2 haa6 ci3 jyu6 maai4 ngo5`,`这次去不了，下次算上我。`]],words:[[`今晚`,`gam1 maan5`,`今晚`],[`聽晚`,`ting1 maan5`,`明晚`],[`不過`,`bat1 gwo3`,`不过`],[`約咗人`,`joek3 zo2 jan4`,`已与别人有约`],[`唔緊要`,`m4 gan2 jiu3`,`没关系`],[`下次`,`haa6 ci3`,`下次`],[`再覆`,`zoi3 fuk1`,`再回复`],[`休息`,`jau1 sik1`,`休息`],[`肯定`,`hang2 ding6`,`确定`],[`預埋`,`jyu6 maai4`,`也算上`]],patterns:[[`多謝……，不過……`,`先回应好意，再清楚说明自己的安排。`,`多謝你約我，不過今晚唔得閒。`],[`動詞＋唔到`,`表示无法做到或无法参加。`,`今次去唔到。`]],cultureNote:`婉拒可以简洁，不必编造复杂理由。如果确实想再见面，提出具体的改约时间，会比只说“下次”更明确。`,practicePrompt:`朋友约你周日逛街，但你想休息。礼貌拒绝，再提出下周六下午这个替代时间。`}),t({id:`friends-gathering`,topicId:`friends`,level:2,title:`去朋友家聚会`,description:`登门问候、帮忙与用餐`,speakers:[`客人`,`主人`],phrases:[[`唔好意思，我遲咗少少。`,`m4 hou2 ji3 si1 ngo5 ci4 zo2 siu2 siu2`,`不好意思，我迟到了一会儿。`],[`唔緊要，入嚟坐吖。`,`m4 gan2 jiu3 jap6 lai4 co5 aa1`,`没关系，进来坐吧。`],[`我帶咗啲水果嚟。`,`ngo5 daai3 zo2 di1 seoi2 gwo2 lai4`,`我带了些水果来。`],[`你太客氣喇，多謝晒。`,`nei5 taai3 haak3 hei3 laa3 do1 ze6 saai3`,`你太客气了，非常感谢。`],[`有冇嘢要我幫手？`,`jau5 mou5 je5 jiu3 ngo5 bong1 sau2`,`有什么需要我帮忙的吗？`],[`麻煩你幫我擺碗筷。`,`maa4 faan4 nei5 bong1 ngo5 baai2 wun2 faai3`,`麻烦你帮我摆碗筷。`],[`冇問題，碗筷放咗喺邊？`,`mou5 man6 tai4 wun2 faai3 fong3 zo2 hai2 bin1`,`没问题，碗筷放在哪里了？`],[`廚房左手邊個櫃入面。`,`cyu4 fong4 zo2 sau2 bin1 go3 gwai6 jap6 min6`,`厨房左边那个柜子里。`],[`呢碟餸好好食，點整㗎？`,`ni1 dip6 sung3 hou2 hou2 sik6 dim2 zing2 gaa3`,`这道菜很好吃，怎么做的？`],[`我唔飲酒，飲水就得喇。`,`ngo5 m4 jam2 zau2 jam2 seoi2 zau6 dak1 laa3`,`我不喝酒，喝水就行了。`],[`大家慢慢食，唔使等我。`,`daai6 gaa1 maan6 maan6 sik6 m4 sai2 dang2 ngo5`,`大家慢慢吃，不用等我。`],[`今日麻煩晒你，下次到我請。`,`gam1 jat6 maa4 faan4 saai3 nei5 haa6 ci3 dou3 ngo5 ceng2`,`今天辛苦你了，下次轮到我请。`]],words:[[`入嚟`,`jap6 lai4`,`进来`],[`水果`,`seoi2 gwo2`,`水果`],[`客氣`,`haak3 hei3`,`客气`],[`幫手`,`bong1 sau2`,`帮忙`],[`擺`,`baai2`,`摆放`],[`碗筷`,`wun2 faai3`,`碗筷`],[`廚房`,`cyu4 fong4`,`厨房`],[`碟`,`dip6`,`碟；盘`],[`餸`,`sung3`,`菜肴`],[`到我請`,`dou3 ngo5 ceng2`,`轮到我请客`]],patterns:[[`有冇嘢要我＋動詞？`,`主动询问有没有可帮忙的事情。`,`有冇嘢要我幫手？`],[`……就得喇`,`表示这样已经足够，可温和表达自己的需求。`,`飲水就得喇。`]],cultureNote:`带小礼物、到场后主动问能否帮忙，都是常见的到访表达。对饮食偏好或限制，可以直接而客气地说明。`,practicePrompt:`你去朋友家吃饭，带了甜品。先说明带来的东西，再主动帮忙，最后礼貌表示自己不喝酒。`}),t({id:`friends-weekend`,topicId:`friends`,level:2,title:`一起安排周末`,description:`周末活动、天气与预算`,speakers:[`阿欣`,`阿杰`],phrases:[[`今個週末想唔想出去行吓？`,`gam1 go3 zau1 mut6 soeng2 m4 soeng2 ceot1 heoi3 haang4 haa5`,`这个周末想不想出去逛逛？`],[`想呀，不過我唔想太早起身。`,`soeng2 aa3 bat1 gwo3 ngo5 m4 soeng2 taai3 zou2 hei2 san1`,`想呀，不过我不想太早起床。`],[`咁食完晏先出發啦。`,`gam2 sik6 jyun4 aan3 sin1 ceot1 faat3 laa1`,`那吃完午饭再出发吧。`],[`好，不過天氣預報話可能落雨。`,`hou2 bat1 gwo3 tin1 hei3 jyu6 bou3 waa6 ho2 nang4 lok6 jyu5`,`好，不过天气预报说可能下雨。`],[`不如揀個室內活動？`,`bat1 jyu4 gaan2 go3 sat1 noi6 wut6 dung6`,`不如选个室内活动？`],[`我想睇展覽，順便飲杯咖啡。`,`ngo5 soeng2 tai2 zin2 laam5 seon6 bin6 jam2 bui1 gaa3 fe1`,`我想看展览，顺便喝杯咖啡。`],[`聽落幾好，門票貴唔貴？`,`teng1 lok6 gei2 hou2 mun4 piu3 gwai3 m4 gwai3`,`听起来不错，门票贵吗？`],[`我查吓先，睇埋開放時間。`,`ngo5 caa4 haa5 sin1 tai2 maai4 hoi1 fong3 si4 gaan3`,`我先查一下，也看看开放时间。`],[`我想留返半日做自己啲嘢。`,`ngo5 soeng2 lau4 faan1 bun3 jat6 zou6 zi6 gei2 di1 je5`,`我想留半天处理自己的事。`],[`我哋預幾多預算好？`,`ngo5 dei6 jyu6 gei2 do1 jyu6 syun3 hou2`,`我们预留多少预算合适？`],[`如果多人，不如早啲買飛。`,`jyu4 gwo2 do1 jan4 bat1 jyu4 zou2 di1 maai5 fei1`,`如果人多，不如早点买票。`],[`行攰咗就搵個地方坐吓。`,`haang4 gui6 zo2 zau6 wan2 go3 dei6 fong1 co5 haa5`,`走累了就找个地方坐坐。`]],words:[[`週末`,`zau1 mut6`,`周末`],[`起身`,`hei2 san1`,`起床`],[`食晏`,`sik6 aan3`,`吃午饭`],[`出發`,`ceot1 faat3`,`出发`],[`天氣預報`,`tin1 hei3 jyu6 bou3`,`天气预报`],[`展覽`,`zin2 laam5`,`展览`],[`順便`,`seon6 bin6`,`顺便`],[`門票`,`mun4 piu3`,`门票`],[`預算`,`jyu6 syun3`,`预算`],[`攰`,`gui6`,`累`]],patterns:[[`動詞＋完＋事情＋先……`,`先完成前一件事，再做后一件事。`,`食完晏先出發。`],[`聽落＋評價`,`表达听到建议之后的初步感受。`,`聽落幾好。`]],cultureNote:`“買飛”的“飛”指票。“行吓”可以是随意逛逛，不一定指徒步。一起安排活动时，也可以清楚说明自己的时间和预算。`,practicePrompt:`两个人想周日出游，一人怕晒，一人预算有限。商量一项两个人都愿意参加的活动。`}),t({id:`friends-festivals`,topicId:`friends`,level:2,title:`节日问候与祝福`,description:`节日安排、祝福与伴手礼`,speakers:[`阿欣`,`阿杰`],phrases:[[`就嚟過年喇，你有咩安排？`,`zau6 lai4 gwo3 nin4 laa3 nei5 jau5 me1 on1 paai4`,`快过年了，你有什么安排？`],[`我會返屋企，同屋企人食團年飯。`,`ngo5 wui5 faan1 uk1 kei2 tung4 uk1 kei2 jan4 sik6 tyun4 nin4 faan6`,`我会回家，和家人吃团年饭。`],[`咁提早祝你新年快樂！`,`gam2 tai4 zou2 zuk1 nei5 san1 nin4 faai3 lok6`,`那提前祝你新年快乐！`],[`多謝，祝你身體健康，事事順利。`,`do1 ze6 zuk1 nei5 san1 tai2 gin6 hong1 si6 si6 seon6 lei6`,`谢谢，祝你身体健康，事事顺利。`],[`放完假返嚟再約飲茶吖。`,`fong3 jyun4 gaa3 faan1 lai4 zoi3 joek3 jam2 caa4 aa1`,`休完假回来再约喝茶吧。`],[`好呀，我到時帶啲手信俾你。`,`hou2 aa3 ngo5 dou3 si4 daai3 di1 sau2 seon3 bei2 nei5`,`好呀，我到时给你带些伴手礼。`],[`有心喇，唔使咁客氣。`,`jau5 sam1 laa3 m4 sai2 gam3 haak3 hei3`,`谢谢你的心意，不用这么客气。`],[`祝你假期過得開心。`,`zuk1 nei5 gaa3 kei4 gwo3 dak1 hoi1 sam1`,`祝你假期过得开心。`],[`中秋節快樂，今晚有冇去賞月？`,`zung1 cau1 zit3 faai3 lok6 gam1 maan5 jau5 mou5 heoi3 soeng2 jyut6`,`中秋节快乐，今晚有没有去赏月？`],[`生日快樂，祝你心想事成！`,`saang1 jat6 faai3 lok6 zuk1 nei5 sam1 soeng2 si6 sing4`,`生日快乐，祝你心想事成！`],[`恭喜你，終於完成咗！`,`gung1 hei2 nei5 zung1 jyu1 jyun4 sing4 zo2`,`恭喜你，终于完成了！`],[`多謝你記得，真係好開心。`,`do1 ze6 nei5 gei3 dak1 zan1 hai6 hou2 hoi1 sam1`,`谢谢你记得，真的很开心。`]],words:[[`就嚟`,`zau6 lai4`,`快要`],[`過年`,`gwo3 nin4`,`过年`],[`屋企人`,`uk1 kei2 jan4`,`家人`],[`團年飯`,`tyun4 nin4 faan6`,`团年饭`],[`提早`,`tai4 zou2`,`提前`],[`祝`,`zuk1`,`祝愿`],[`順利`,`seon6 lei6`,`顺利`],[`手信`,`sau2 seon3`,`伴手礼`],[`有心`,`jau5 sam1`,`有心意；费心`],[`賞月`,`soeng2 jyut6`,`赏月`]],patterns:[[`祝你＋祝願`,`根据对方的近况送上合适的祝福。`,`祝你假期過得開心。`],[`就嚟＋事情＋喇`,`表示某件事快要到来。`,`就嚟過年喇。`]],cultureNote:`“有心喇”是在感谢对方记挂自己，常用于礼物或祝福。节日问候可以配一句具体关心，让交流更贴近彼此的生活。`,practicePrompt:`朋友即将放假回乡，向对方送上祝福；另一位朋友刚完成一个项目，再换一句合适的祝贺。`})],u=[t({id:`work-first-day`,topicId:`work`,level:2,title:`第一天认识同事`,description:`岗位介绍、同事与工作分工`,speakers:[`新同事`,`同事`],phrases:[[`大家好，我今日第一日返工。`,`daai6 gaa1 hou2 ngo5 gam1 jat6 dai6 jat1 jat6 faan1 gung1`,`大家好，今天是我第一天上班。`],[`歡迎你，你負責邊方面？`,`fun1 jing4 nei5 nei5 fu6 zaak3 bin1 fong1 min6`,`欢迎你，你负责哪方面？`],[`我主要負責客戶聯絡。`,`ngo5 zyu2 jiu3 fu6 zaak3 haak3 wu6 lyun4 lok3`,`我主要负责客户联络。`],[`咁我哋之後會成日合作。`,`gam2 ngo5 dei6 zi1 hau6 wui5 seng4 jat6 hap6 zok3`,`那我们以后会经常合作。`],[`多多指教，有嘢唔明想請教你。`,`do1 do1 zi2 gaau3 jau5 je5 m4 ming4 soeng2 cing2 gaau3 nei5`,`请多指教，有不懂的地方想向你请教。`],[`冇問題，你可以隨時問我。`,`mou5 man6 tai4 nei5 ho2 ji5 ceoi4 si4 man6 ngo5`,`没问题，你可以随时问我。`],[`唔該，請問平時點樣分工？`,`m4 goi1 cing2 man6 ping4 si4 dim2 joeng6 fan1 gung1`,`谢谢，请问平常怎样分工？`],[`我陣間帶你認識其他同事。`,`ngo5 zan6 gaan1 daai3 nei5 jing6 sik1 kei4 taa1 tung4 si6`,`我一会儿带你认识其他同事。`],[`呢個項目由邊位跟進？`,`ni1 go3 hong6 muk6 jau4 bin1 wai2 gan1 zeon3`,`这个项目由哪位跟进？`],[`我想了解吓工作流程。`,`ngo5 soeng2 liu5 gaai2 haa5 gung1 zok3 lau4 cing4`,`我想了解一下工作流程。`],[`有冇共用文件？`,`jau5 mou5 gung6 jung6 man4 gin6`,`有没有共享文件？`],[`麻煩你加我入工作群組。`,`maa4 faan4 nei5 gaa1 ngo5 jap6 gung1 zok3 kwan4 zou2`,`麻烦你把我加进工作群。`]],words:[[`返工`,`faan1 gung1`,`上班`],[`歡迎`,`fun1 jing4`,`欢迎`],[`負責`,`fu6 zaak3`,`负责`],[`客戶`,`haak3 wu6`,`客户`],[`合作`,`hap6 zok3`,`合作`],[`指教`,`zi2 gaau3`,`指教`],[`請教`,`cing2 gaau3`,`请教`],[`分工`,`fan1 gung1`,`分工`],[`跟進`,`gan1 zeon3`,`跟进`],[`流程`,`lau4 cing4`,`流程`]],patterns:[[`我主要負責＋工作`,`用一句话说明自己的职责范围。`,`我主要負責客戶聯絡。`],[`由＋人物＋跟進`,`说明或询问一件事由谁负责推进。`,`呢個項目由邊位跟進？`]],cultureNote:`“多多指教”适合初次认识同事。实际合作时，把职责、对接人和资料位置问清楚，能让后续沟通更顺畅。`,practicePrompt:`第一天加入设计团队，介绍你的岗位，询问谁负责审核，以及到哪里找共用资料。`}),t({id:`work-meeting`,topicId:`work`,level:2,title:`开会时接得上话`,description:`议题、建议、补充与提问`,speakers:[`主持人`,`同事`],phrases:[[`我哋今日先傾活動安排。`,`ngo5 dei6 gam1 jat6 sin1 king1 wut6 dung6 on1 paai4`,`我们今天先讨论活动安排。`],[`開始之前，我想確認吓目標。`,`hoi1 ci2 zi1 cin4 ngo5 soeng2 kok3 jing6 haa5 muk6 biu1`,`开始之前，我想确认一下目标。`],[`今次想吸引多啲新客參加。`,`gam1 ci3 soeng2 kap1 jan5 do1 di1 san1 haak3 caam1 gaa1`,`这次想吸引更多新客户参加。`],[`明白，我有一個建議。`,`ming4 baak6 ngo5 jau5 jat1 go3 gin3 ji5`,`明白，我有一个建议。`],[`你講吖，大家一齊聽吓。`,`nei5 gong2 aa1 daai6 gaa1 jat1 cai4 teng1 haa5`,`你说吧，大家一起听听。`],[`不如先做個簡單示範。`,`bat1 jyu4 sin1 zou6 go3 gaan2 daan1 si6 faan6`,`不如先做一个简单示范。`],[`呢個諗法唔錯，我記低先。`,`ni1 go3 nam2 faat3 m4 co3 ngo5 gei3 dai1 sin1`,`这个想法不错，我先记下来。`],[`我會後補返具體資料。`,`ngo5 wui6 hau6 bou2 faan1 geoi6 tai2 zi1 liu2`,`我会在会后补上具体资料。`],[`唔好意思，我想補充少少。`,`m4 hou2 ji3 si1 ngo5 soeng2 bou2 cung1 siu2 siu2`,`不好意思，我想补充一点。`],[`頭先嗰點，可唔可以再解釋吓？`,`tau4 sin1 go2 dim2 ho2 m4 ho2 ji5 zoi3 gaai2 sik1 haa5`,`刚才那一点，可以再解释一下吗？`],[`我同意呢個方向。`,`ngo5 tung4 ji3 ni1 go3 fong1 hoeng3`,`我同意这个方向。`],[`我哋先總結吓今日嘅決定。`,`ngo5 dei6 sin1 zung2 git3 haa5 gam1 jat6 ge3 kyut3 ding6`,`我们先总结一下今天的决定。`]],words:[[`傾`,`king1`,`谈；讨论`],[`確認`,`kok3 jing6`,`确认`],[`目標`,`muk6 biu1`,`目标`],[`吸引`,`kap1 jan5`,`吸引`],[`建議`,`gin3 ji5`,`建议`],[`示範`,`si6 faan6`,`示范`],[`記低`,`gei3 dai1`,`记下来`],[`補充`,`bou2 cung1`,`补充`],[`解釋`,`gaai2 sik1`,`解释`],[`總結`,`zung2 git3`,`总结`]],patterns:[[`開始之前，我想……`,`在进入下一步前提出需要先确认的事。`,`開始之前，我想確認吓目標。`],[`可唔可以再＋動作＋吓？`,`礼貌请求对方重复或进一步说明。`,`可唔可以再解釋吓？`]],cultureNote:`“我想補充少少”是接话时常用的铺垫。线上会议若听漏了，可以明确指出“頭先嗰點”，让对方知道需要重说哪一部分。`,practicePrompt:`在筹备会议上，先确认活动目标，再提出一个安排建议，最后请求解释一项你没听懂的决定。`}),t({id:`work-progress`,topicId:`work`,level:2,title:`汇报进度与困难`,description:`完成情况、问题与交付时间`,speakers:[`负责人`,`同事`],phrases:[[`想問吓份報告進度點呀？`,`soeng2 man6 haa5 fan6 bou3 gou3 zeon3 dou6 dim2 aa3`,`想问一下报告进度怎样？`],[`初稿寫好咗，仲差數據核對。`,`co1 gou2 se2 hou2 zo2 zung6 caa1 sou3 geoi3 hat6 deoi3`,`初稿写好了，还差数据核对。`],[`有冇遇到咩問題？`,`jau5 mou5 jyu6 dou3 me1 man6 tai4`,`有没有遇到什么问题？`],[`有啲資料未齊，我等緊回覆。`,`jau5 di1 zi1 liu2 mei6 cai4 ngo5 dang2 gan2 wui4 fuk1`,`有些资料还不齐，我正在等回复。`],[`預計幾時可以交？`,`jyu6 gai3 gei2 si4 ho2 ji5 gaau1`,`预计什么时候可以交？`],[`如果今日收到，聽日下晝可以交。`,`jyu4 gwo2 gam1 jat6 sau1 dou2 ting1 jat6 haa6 zau3 ho2 ji5 gaau1`,`如果今天收到，明天下午可以交。`],[`好，有變動就早啲通知我。`,`hou2 jau5 bin3 dung6 zau6 zou2 di1 tung1 zi1 ngo5`,`好，有变动就早点通知我。`],[`明白，我今晚再更新一次。`,`ming4 baak6 ngo5 gam1 maan5 zoi3 gang1 san1 jat1 ci3`,`明白，我今晚再更新一次。`],[`呢部分已經完成咗。`,`ni1 bou6 fan6 ji5 ging1 jyun4 sing4 zo2`,`这部分已经完成了。`],[`我需要多一日時間。`,`ngo5 seoi1 jiu3 do1 jat1 jat6 si4 gaan3`,`我需要多一天时间。`],[`可唔可以先交現有版本？`,`ho2 m4 ho2 ji5 sin1 gaau1 jin6 jau5 baan2 bun2`,`可以先交现有版本吗？`],[`我會列低仲未解決嘅問題。`,`ngo5 wui5 lit6 dai1 zung6 mei6 gaai2 kyut3 ge3 man6 tai4`,`我会列出还没解决的问题。`]],words:[[`報告`,`bou3 gou3`,`报告`],[`進度`,`zeon3 dou6`,`进度`],[`初稿`,`co1 gou2`,`初稿`],[`仲差`,`zung6 caa1`,`还差`],[`核對`,`hat6 deoi3`,`核对`],[`回覆`,`wui4 fuk1`,`回复`],[`預計`,`jyu6 gai3`,`预计`],[`變動`,`bin3 dung6`,`变动`],[`版本`,`baan2 bun2`,`版本`],[`解決`,`gaai2 kyut3`,`解决`]],patterns:[[`……好咗，仲差……`,`把已经完成和仍欠缺的部分分开说明。`,`初稿寫好咗，仲差數據核對。`],[`如果＋條件，＋時間＋可以＋結果`,`给出有条件的时间估计。`,`如果今日收到，聽日下晝可以交。`]],cultureNote:`汇报进度时，只说“做緊”通常信息不够。补充剩余任务、卡住的原因和下一次更新时间，对方会更容易安排工作。`,practicePrompt:`你已经完成演示文稿，但仍在等图片。向负责人汇报现状，并给出资料准时到达和延迟时的两种安排。`}),t({id:`work-clarification`,topicId:`work`,level:2,title:`把要求问清楚`,description:`交付内容、格式、期限与优先顺序`,speakers:[`负责人`,`同事`],phrases:[[`麻煩你整理吓上個月啲資料。`,`maa4 faan4 nei5 zing2 lei5 haa5 soeng6 go3 jyut6 di1 zi1 liu2`,`麻烦你整理一下上个月的资料。`],[`好，想確認吓要包括邊幾部分？`,`hou2 soeng2 kok3 jing6 haa5 jiu3 baau1 kut3 bin1 gei2 bou6 fan6`,`好，想确认一下要包括哪几个部分？`],[`銷售數字同客戶意見都要。`,`siu1 sau6 sou3 zi6 tung4 haak3 wu6 ji3 gin3 dou1 jiu3`,`销售数字和客户意见都要。`],[`要做成表格，定寫成報告？`,`jiu3 zou6 sing4 biu2 gaak3 ding6 se2 sing4 bou3 gou3`,`要做成表格，还是写成报告？`],[`先做表格，再加幾句重點。`,`sin1 zou6 biu2 gaak3 zoi3 gaa1 gei2 geoi3 cung5 dim2`,`先做表格，再加几句重点说明。`],[`明白，最遲幾時要？`,`ming4 baak6 zeoi3 ci4 gei2 si4 jiu3`,`明白，最晚什么时候要？`],[`星期四收工之前俾我。`,`sing1 kei4 sei3 sau1 gung1 zi1 cin4 bei2 ngo5`,`星期四下班前给我。`],[`收到，我做完會先俾你過目。`,`sau1 dou2 ngo5 zou6 jyun4 wui5 sin1 bei2 nei5 gwo3 muk6`,`收到，我做完会先给你过目。`],[`你嘅意思係先做呢份，啱唔啱？`,`nei5 ge3 ji3 si1 hai6 sin1 zou6 ni1 fan6 ngaam1 m4 ngaam1`,`你的意思是先做这份，对吗？`],[`有冇格式可以參考？`,`jau5 mou5 gaak3 sik1 ho2 ji5 caam1 haau2`,`有没有可以参考的格式？`],[`呢兩樣邊樣急啲？`,`ni1 loeng5 joeng6 bin1 joeng6 gap1 di1`,`这两项哪项更急？`],[`如果要求有改，麻煩你話我知。`,`jyu4 gwo2 jiu1 kau4 jau5 goi2 maa4 faan4 nei5 waa6 ngo5 zi1`,`如果要求有改动，麻烦你告诉我。`]],words:[[`整理`,`zing2 lei5`,`整理`],[`包括`,`baau1 kut3`,`包括`],[`銷售`,`siu1 sau6`,`销售`],[`意見`,`ji3 gin3`,`意见`],[`表格`,`biu2 gaak3`,`表格`],[`重點`,`cung5 dim2`,`重点`],[`最遲`,`zeoi3 ci4`,`最晚`],[`過目`,`gwo3 muk6`,`过目`],[`格式`,`gaak3 sik1`,`格式`],[`急`,`gap1`,`紧急`]],patterns:[[`要＋方式甲，定＋方式乙？`,`用两个具体选项帮助对方说明要求。`,`要做成表格，定寫成報告？`],[`你嘅意思係……，啱唔啱？`,`复述自己的理解，请对方核实。`,`你嘅意思係先做呢份，啱唔啱？`]],cultureNote:`“收到”表示已接收信息，不一定等于所有细节都明白。可以先回应，再问清范围、格式和时间；“過目”指请对方查看。`,practicePrompt:`负责人让你准备会议资料。问清需要哪些内容、做成什么格式、何时交，以及是否要先审阅。`}),t({id:`work-phone-message`,topicId:`work`,level:2,title:`接电话与留口讯`,description:`转接、口信、电话号码与回电`,speakers:[`来电者`,`接线同事`],phrases:[[`你好，唔該搵李小姐。`,`nei5 hou2 m4 goi1 wan2 lei5 siu2 ze2`,`你好，麻烦找李小姐。`],[`佢而家開緊會，請問邊位搵佢？`,`keoi5 ji4 gaa1 hoi1 gan2 wui6 cing2 man6 bin1 wai2 wan2 keoi5`,`她现在正在开会，请问哪位找她？`],[`我姓黃，想同佢確認交貨時間。`,`ngo5 sing3 wong4 soeng2 tung4 keoi5 kok3 jing6 gaau1 fo3 si4 gaan3`,`我姓黄，想和她确认交货时间。`],[`要唔要我幫你留個口訊？`,`jiu3 m4 jiu3 ngo5 bong1 nei5 lau4 go3 hau2 seon3`,`要我帮你留个口信吗？`],[`麻煩你請佢方便嗰陣覆我電話。`,`maa4 faan4 nei5 cing2 keoi5 fong1 bin6 go2 zan6 fuk1 ngo5 din6 waa2`,`麻烦你请她方便时给我回电话。`],[`好，請問你個聯絡電話？`,`hou2 cing2 man6 nei5 go3 lyun4 lok3 din6 waa2`,`好的，请问你的联系电话？`],[`我慢慢讀一次，你幫我記低。`,`ngo5 maan6 maan6 duk6 jat1 ci3 nei5 bong1 ngo5 gei3 dai1`,`我慢慢读一遍，你帮我记下来。`],[`記低咗，我再讀返一次俾你核對。`,`gei3 dai1 zo2 ngo5 zoi3 duk6 faan1 jat1 ci3 bei2 nei5 hat6 deoi3`,`记下了，我再读一遍给你核对。`],[`唔好意思，條線唔係好清楚。`,`m4 hou2 ji3 si1 tiu4 sin3 m4 hai6 hou2 cing1 co2`,`不好意思，通话线路不太清楚。`],[`可唔可以講慢少少？`,`ho2 m4 ho2 ji5 gong2 maan6 siu2 siu2`,`可以说慢一点吗？`],[`你稍等，我幫你轉線。`,`nei5 saau2 dang2 ngo5 bong1 nei5 zyun2 sin3`,`你稍等，我帮你转接。`],[`我遲啲再打嚟，唔該晒。`,`ngo5 ci4 di1 zoi3 daa2 lai4 m4 goi1 saai3`,`我晚些再打来，谢谢。`]],words:[[`開會`,`hoi1 wui6`,`开会`],[`邊位`,`bin1 wai2`,`哪位`],[`交貨`,`gaau1 fo3`,`交货`],[`口訊`,`hau2 seon3`,`口信`],[`覆電話`,`fuk1 din6 waa2`,`回电话`],[`聯絡電話`,`lyun4 lok3 din6 waa2`,`联系电话`],[`讀返`,`duk6 faan1`,`再读一遍`],[`條線`,`tiu4 sin3`,`线路`],[`轉線`,`zyun2 sin3`,`转接电话`],[`遲啲`,`ci4 di1`,`晚些`]],patterns:[[`唔該搵＋人物`,`电话中礼貌说明想找谁。`,`唔該搵李小姐。`],[`請佢＋方便嗰陣＋動作`,`请对方转达一个时间较灵活的请求。`,`請佢方便嗰陣覆我電話。`]],cultureNote:`代留口讯时，核对来电者姓名、公司、事项和回电号码比只说“有人找”更有用。号码最好逐位读，并请对方复述。`,practicePrompt:`打电话找一位正在外出的同事，请接线员转告你希望改交货日期，并留下回电方式。`}),t({id:`work-leave`,topicId:`work`,level:2,title:`请假与工作交接`,description:`请假日期、证明与工作交接`,speakers:[`同事`,`负责人`],phrases:[[`我想下個星期請一日假。`,`ngo5 soeng2 haa6 go3 sing1 kei4 cing2 jat1 jat6 gaa3`,`我想下个星期请一天假。`],[`想請邊日？有冇嘢要交接？`,`soeng2 cing2 bin1 jat6 jau5 mou5 je5 jiu3 gaau1 zip3`,`想请哪天？有没有工作需要交接？`],[`星期三，我會先完成手頭啲嘢。`,`sing1 kei4 saam1 ngo5 wui5 sin1 jyun4 sing4 sau2 tau4 di1 je5`,`星期三，我会先完成手头的工作。`],[`嗰日個客戶會議點安排？`,`go2 jat6 go3 haak3 wu6 wui6 ji5 dim2 on1 paai4`,`那天的客户会议怎么安排？`],[`我問過阿明，佢可以幫手。`,`ngo5 man6 gwo3 aa3 ming4 keoi5 ho2 ji5 bong1 sau2`,`我问过阿明，他可以帮忙。`],[`好，記得俾齊資料佢。`,`hou2 gei3 dak1 bei2 cai4 zi1 liu2 keoi5`,`好，记得把资料给齐。`],[`明白，我會寫低要跟進嘅事項。`,`ming4 baak6 ngo5 wui5 se2 dai1 jiu3 gan1 zeon3 ge3 si6 hong6`,`明白，我会写下需要跟进的事项。`],[`咁你填好申請，我再確認。`,`gam2 nei5 tin4 hou2 san1 cing2 ngo5 zoi3 kok3 jing6`,`那你填好申请，我再确认。`],[`我今日唔舒服，想請病假。`,`ngo5 gam1 jat6 m4 syu1 fuk6 soeng2 cing2 beng6 gaa3`,`我今天不舒服，想请病假。`],[`請問要點樣交證明？`,`cing2 man6 jiu3 dim2 joeng6 gaau1 zing3 ming4`,`请问要怎样提交证明？`],[`有急事可以先搵我同事。`,`jau5 gap1 si6 ho2 ji5 sin1 wan2 ngo5 tung4 si6`,`有急事可以先找我的同事。`],[`我返嚟之後會接返手。`,`ngo5 faan1 lai4 zi1 hau6 wui5 zip3 faan1 sau2`,`我回来之后会重新接手。`]],words:[[`請假`,`cing2 gaa3`,`请假`],[`交接`,`gaau1 zip3`,`交接`],[`手頭`,`sau2 tau4`,`手头`],[`會議`,`wui6 ji5`,`会议`],[`俾齊`,`bei2 cai4`,`给齐`],[`事項`,`si6 hong6`,`事项`],[`申請`,`san1 cing2`,`申请`],[`病假`,`beng6 gaa3`,`病假`],[`證明`,`zing3 ming4`,`证明`],[`接返手`,`zip3 faan1 sau2`,`重新接手`]],patterns:[[`我想＋時間＋請＋時長＋假`,`说明计划请假的时间和天数。`,`我想下個星期請一日假。`],[`……之後會……`,`说明前一件事完成后的安排。`,`我返嚟之後會接返手。`]],cultureNote:`请假方式和证明要求由工作单位的实际制度决定。沟通时同时交代交接人、资料和待办事项，可帮助团队安排工作。`,practicePrompt:`你下周二下午需要请假。说明手头工作会如何安排，并确认请假申请的提交方式。`})],d=[t({id:`express-yourself-experience`,topicId:`express-yourself`,level:3,title:`把一次经历讲完整`,description:`旅行经历、事情经过与感受`,speakers:[`阿欣`,`阿杰`],phrases:[[`你上次自己去旅行，順唔順利？`,`nei5 soeng6 ci3 zi6 gei2 heoi3 leoi5 hang4 seon6 m4 seon6 lei6`,`你上次自己去旅行，顺利吗？`],[`一開始有啲緊張，後尾就習慣咗。`,`jat1 hoi1 ci2 jau5 di1 gan2 zoeng1 hau6 mei5 zau6 zaap6 gwaan3 zo2`,`一开始有点紧张，后来就习惯了。`],[`有冇發生啲咩特別嘅事？`,`jau5 mou5 faat3 sang1 di1 me1 dak6 bit6 ge3 si6`,`有没有发生什么特别的事？`],[`有次搭錯車，去咗另一個地方。`,`jau5 ci3 daap3 co3 ce1 heoi3 zo2 ling6 jat1 go3 dei6 fong1`,`有一次坐错车，去了另一个地方。`],[`咁你之後點算？`,`gam2 nei5 zi1 hau6 dim2 syun3`,`那你之后怎么办？`],[`我先問路，再搭返車去目的地。`,`ngo5 sin1 man6 lou6 zoi3 daap3 faan1 ce1 heoi3 muk6 dik1 dei6`,`我先问路，再乘车回到目的地。`],[`最後趕唔趕得切？`,`zeoi3 hau6 gon2 m4 gon2 dak1 cit3`,`最后来得及吗？`],[`趕得切，仲識咗個好好人嘅街坊。`,`gon2 dak1 cit3 zung6 sik1 zo2 go3 hou2 hou2 jan4 ge3 gaai1 fong1`,`来得及，还认识了一位很友善的当地居民。`],[`講返嗰日，我而家仲記得好清楚。`,`gong2 faan1 go2 jat6 ngo5 ji4 gaa1 zung6 gei3 dak1 hou2 cing1 co2`,`说起那天，我现在还记得很清楚。`],[`本來以為好難，點知做落又唔係。`,`bun2 loi4 ji5 wai4 hou2 naan4 dim2 zi1 zou6 lok6 jau6 m4 hai6`,`本来以为很难，没想到做起来又不是那样。`],[`嗰次之後，我學識咗早啲出門。`,`go2 ci3 zi1 hau6 ngo5 hok6 sik1 zo2 zou2 di1 ceot1 mun4`,`那次之后，我学会了早点出门。`],[`諗返起都覺得幾好笑。`,`nam2 faan1 hei2 dou1 gok3 dak1 gei2 hou2 siu3`,`回想起来也觉得挺好笑。`]],words:[[`旅行`,`leoi5 hang4`,`旅行`],[`緊張`,`gan2 zoeng1`,`紧张`],[`後尾`,`hau6 mei5`,`后来`],[`習慣`,`zaap6 gwaan3`,`习惯`],[`發生`,`faat3 sang1`,`发生`],[`搭錯車`,`daap3 co3 ce1`,`坐错车`],[`點算`,`dim2 syun3`,`怎么办`],[`目的地`,`muk6 dik1 dei6`,`目的地`],[`街坊`,`gaai1 fong1`,`街坊；附近居民`],[`諗返起`,`nam2 faan1 hei2`,`回想起来`]],patterns:[[`一開始……，後尾就……`,`用前后变化讲清一段经历的发展。`,`一開始有啲緊張，後尾就習慣咗。`],[`本來以為……，點知……`,`表达原先预期与实际结果不同。`,`本來以為好難，點知做落又唔係。`]],cultureNote:`讲经历时，“有次”能自然引入一个具体片段。“咁之後呢？”或“點算？”是听者鼓励对方继续讲的常用回应。`,practicePrompt:`用“一開始—後尾—最後”讲一次迷路、第一次上班或参加活动的经历，让伙伴追问两次。`}),t({id:`express-yourself-reasons`,topicId:`express-yourself`,level:3,title:`说明原因与结果`,description:`原因、结果与补充理由`,speakers:[`阿杰`,`阿欣`],phrases:[[`你點解決定搬屋？`,`nei5 dim2 gaai2 kyut3 ding6 bun1 uk1`,`你为什么决定搬家？`],[`因為返工太遠，每日搭車好攰。`,`jan1 wai6 faan1 gung1 taai3 jyun5 mui5 jat6 daap3 ce1 hou2 gui6`,`因为上班太远，每天坐车很累。`],[`新地方近公司好多？`,`san1 dei6 fong1 gan6 gung1 si1 hou2 do1`,`新地方离公司近很多吗？`],[`係，所以可以慳返唔少時間。`,`hai6 so2 ji5 ho2 ji5 haan1 faan1 m4 siu2 si4 gaan3`,`对，所以可以省下不少时间。`],[`除咗近公司，仲有其他原因？`,`ceoi4 zo2 gan6 gung1 si1 zung6 jau5 kei4 taa1 jyun4 jan1`,`除了离公司近，还有其他原因吗？`],[`附近有公園，放工可以行吓。`,`fu6 gan6 jau5 gung1 jyun2 fong3 gung1 ho2 ji5 haang4 haa5`,`附近有公园，下班可以走走。`],[`明白，咁搬屋嗰陣使唔使幫手？`,`ming4 baak6 gam2 bun1 uk1 go2 zan6 sai2 m4 sai2 bong1 sau2`,`明白，那搬家时需要帮忙吗？`],[`多謝，我安排好再話你知。`,`do1 ze6 ngo5 on1 paai4 hou2 zoi3 waa6 nei5 zi1`,`谢谢，我安排好再告诉你。`],[`主要原因係想多啲時間休息。`,`zyu2 jiu3 jyun4 jan1 hai6 soeng2 do1 di1 si4 gaan3 jau1 sik1`,`主要原因是想多一点时间休息。`],[`唔單止方便，仲可以減少開支。`,`m4 daan1 zi2 fong1 bin6 zung6 ho2 ji5 gaam2 siu2 hoi1 zi1`,`不但方便，还可以减少开支。`],[`由於時間唔夠，我哋改咗安排。`,`jau4 jyu1 si4 gaan3 m4 gau3 ngo5 dei6 goi2 zo2 on1 paai4`,`由于时间不够，我们改变了安排。`,`“由於”比“因為”稍正式，也可用于说明工作安排。`],[`結果比我預期好。`,`git3 gwo2 bei2 ngo5 jyu6 kei4 hou2`,`结果比我预期的好。`]],words:[[`點解`,`dim2 gaai2`,`为什么`],[`決定`,`kyut3 ding6`,`决定`],[`搬屋`,`bun1 uk1`,`搬家`],[`因為`,`jan1 wai6`,`因为`],[`所以`,`so2 ji5`,`所以`],[`慳返`,`haan1 faan1`,`省下`],[`原因`,`jyun4 jan1`,`原因`],[`減少`,`gaam2 siu2`,`减少`],[`開支`,`hoi1 zi1`,`支出`],[`預期`,`jyu6 kei4`,`预期`]],patterns:[[`因為……，所以……`,`先交代原因，再说明结果；对话中两部分可分开说。`,`因為返工太遠，所以我決定搬屋。`],[`唔單止……，仲……`,`在已有理由上补充另一个好处或事实。`,`唔單止方便，仲可以減少開支。`]],cultureNote:`“點解？”的语气会受场合影响。对不太熟悉的人，可以先说“想問吓”，再问对方是否方便分享原因。`,practicePrompt:`解释你为什么决定学粤语，说出一个主要原因、一个额外原因，以及你希望达到的结果。`}),t({id:`express-yourself-comparison`,topicId:`express-yourself`,level:3,title:`比较后再选择`,description:`价格、距离、体验与选择`,speakers:[`阿欣`,`阿杰`],phrases:[[`呢兩個地方，你想揀邊個？`,`ni1 loeng5 go3 dei6 fong1 nei5 soeng2 gaan2 bin1 go3`,`这两个地方，你想选哪个？`],[`第一個近啲，不過比較嘈。`,`dai6 jat1 go3 gan6 di1 bat1 gwo3 bei2 gaau3 cou4`,`第一个近一点，不过比较吵。`],[`第二個係咪靜好多？`,`dai6 ji6 go3 hai6 mai6 zing6 hou2 do1`,`第二个是不是安静很多？`],[`靜啲，而且地方大啲。`,`zing6 di1 ji4 ce2 dei6 fong1 daai6 di1`,`安静一点，而且地方大一些。`],[`但係價錢差幾多？`,`daan6 hai6 gaa3 cin2 caa1 gei2 do1`,`但是价钱差多少？`],[`第二個比第一個貴兩成。`,`dai6 ji6 go3 bei2 dai6 jat1 go3 gwai3 loeng5 sing4`,`第二个比第一个贵两成。`],[`如果只坐一陣，我覺得近啲好。`,`jyu4 gwo2 zi2 co5 jat1 zan6 ngo5 gok3 dak1 gan6 di1 hou2`,`如果只坐一会儿，我觉得近一点好。`],[`同意，咁今次揀第一個。`,`tung4 ji3 gam2 gam1 ci3 gaan2 dai6 jat1 go3`,`同意，那这次选第一个。`],[`呢個冇嗰個咁重。`,`ni1 go3 mou5 go2 go3 gam3 cung5`,`这个没有那个那么重。`],[`兩個差唔多，睇你鍾意邊種。`,`loeng5 go3 caa1 m4 do1 tai2 nei5 zung1 ji3 bin1 zung2`,`两个差不多，看你喜欢哪一种。`],[`對我嚟講，方便比價錢重要。`,`deoi3 ngo5 lai4 gong2 fong1 bin6 bei2 gaa3 cin2 zung6 jiu3`,`对我来说，方便比价格重要。`],[`各有各好，要睇實際需要。`,`gok3 jau5 gok3 hou2 jiu3 tai2 sat6 zai3 seoi1 jiu3`,`各有优点，要看实际需要。`]],words:[[`比較`,`bei2 gaau3`,`比较`],[`嘈`,`cou4`,`吵`],[`靜`,`zing6`,`安静`],[`而且`,`ji4 ce2`,`而且`],[`價錢`,`gaa3 cin2`,`价格`],[`兩成`,`loeng5 sing4`,`两成；百分之二十`],[`重`,`cung5`,`重`],[`差唔多`,`caa1 m4 do1`,`差不多`],[`重要`,`zung6 jiu3`,`重要`],[`實際`,`sat6 zai3`,`实际`]],patterns:[[`甲＋比＋乙＋形容詞＋差額`,`直接比较两者，并给出差距。`,`第二個比第一個貴兩成。`],[`甲＋冇＋乙＋咁＋形容詞`,`表示甲在某方面不及乙。`,`呢個冇嗰個咁重。`]],cultureNote:`“啲”可表示程度上的一点差异，“好多”表示差距明显。比较时说出使用场景，会比笼统地问哪个好更容易得到有用建议。`,practicePrompt:`比较两间咖啡店：一间近但吵，一间远但安静。分别为短暂会面和长时间阅读做选择。`}),t({id:`express-yourself-opinions`,topicId:`express-yourself`,level:3,title:`有礼貌地表达观点`,description:`个人看法、同意与不同意见`,speakers:[`阿杰`,`阿欣`],phrases:[[`你覺得學語言最重要係咩？`,`nei5 gok3 dak1 hok6 jyu5 jin4 zeoi3 zung6 jiu3 hai6 me1`,`你觉得学语言最重要的是什么？`],[`我覺得要每日用，唔怕講錯。`,`ngo5 gok3 dak1 jiu3 mui5 jat6 jung6 m4 paa3 gong2 co3`,`我觉得要每天使用，不怕说错。`],[`我都同意，不過基礎都好重要。`,`ngo5 dou1 tung4 ji3 bat1 gwo3 gei1 co2 dou1 hou2 zung6 jiu3`,`我也同意，不过基础也很重要。`],[`係呀，有基礎先會講得清楚。`,`hai6 aa3 jau5 gei1 co2 sin1 wui5 gong2 dak1 cing1 co2`,`是呀，有基础才能说得清楚。`],[`咁初學嗰陣，應該先學啲咩？`,`gam2 co1 hok6 go2 zan6 jing1 goi1 sin1 hok6 di1 me1`,`那刚开始学时，应该先学什么？`],[`以我經驗，常用句可以先學。`,`ji5 ngo5 ging1 jim6 soeng4 jung6 geoi3 ho2 ji5 sin1 hok6`,`根据我的经验，可以先学常用句。`],[`有道理，每個人需要都唔同。`,`jau5 dou6 lei5 mui5 go3 jan4 seoi1 jiu3 dou1 m4 tung4`,`有道理，每个人的需要也不同。`],[`係，搵到適合自己嘅方法最緊要。`,`hai6 wan2 dou2 sik1 hap6 zi6 gei2 ge3 fong1 faat3 zeoi3 gan2 jiu3`,`对，找到适合自己的方法最要紧。`],[`我嘅睇法有少少唔同。`,`ngo5 ge3 tai2 faat3 jau5 siu2 siu2 m4 tung4`,`我的看法有一点不同。`],[`我明你意思，不過想補充一點。`,`ngo5 ming4 nei5 ji3 si1 bat1 gwo3 soeng2 bou2 cung1 jat1 dim2`,`我明白你的意思，不过想补充一点。`],[`可能我了解得未夠全面。`,`ho2 nang4 ngo5 liu5 gaai2 dak1 mei6 gau3 cyun4 min6`,`可能我了解得还不够全面。`],[`你可唔可以舉個例子？`,`nei5 ho2 m4 ho2 ji5 geoi2 go3 lai6 zi2`,`你可以举个例子吗？`]],words:[[`語言`,`jyu5 jin4`,`语言`],[`講錯`,`gong2 co3`,`说错`],[`基礎`,`gei1 co2`,`基础`],[`初學`,`co1 hok6`,`初学`],[`經驗`,`ging1 jim6`,`经验`],[`道理`,`dou6 lei5`,`道理`],[`適合`,`sik1 hap6`,`适合`],[`睇法`,`tai2 faat3`,`看法`],[`全面`,`cyun4 min6`,`全面`],[`例子`,`lai6 zi2`,`例子`]],patterns:[[`我覺得……，因為……`,`用理由支撑自己的判断。`,`我覺得要每日用，因為咁樣先容易記得。`],[`我明你意思，不過……`,`先确认理解，再补充或提出不同意见。`,`我明你意思，不過想補充一點。`]],cultureNote:`“有少少唔同”能缓和分歧，但仍应接着说清楚不同在哪里。“你可唔可以舉個例子？”有助于把抽象观点变成具体讨论。`,practicePrompt:`和伙伴讨论线上学习与线下学习。先说自己的偏好和理由，再回应一个与你不同的意见。`}),t({id:`express-yourself-negotiation`,topicId:`express-yourself`,level:3,title:`商量一个双方都行的办法`,description:`时间限制、替代方案与分工`,speakers:[`阿欣`,`阿杰`],phrases:[[`我哋星期五之前要完成呢份嘢。`,`ngo5 dei6 sing1 kei4 ng5 zi1 cin4 jiu3 jyun4 sing4 ni1 fan6 je5`,`我们要在星期五之前完成这份工作。`],[`全部做晒有啲趕，可唔可以分兩次？`,`cyun4 bou6 zou6 saai3 jau5 di1 gon2 ho2 m4 ho2 ji5 fan1 loeng5 ci3`,`全部做完有点赶，可以分两次吗？`],[`你諗住點樣分？`,`nei5 nam2 zyu6 dim2 joeng6 fan1`,`你打算怎样分？`],[`先交主要部分，其餘下星期補返。`,`sin1 gaau1 zyu2 jiu3 bou6 fan6 kei4 jyu4 haa6 sing1 kei4 bou2 faan1`,`先交主要部分，其余下周补上。`],[`但係有啲資料星期五一定要用。`,`daan6 hai6 jau5 di1 zi1 liu2 sing1 kei4 ng5 jat1 ding6 jiu3 jung6`,`但是有些资料星期五一定要用。`],[`咁我先處理嗰部分，你睇得唔得？`,`gam2 ngo5 sin1 cyu2 lei5 go2 bou6 fan6 nei5 tai2 dak1 m4 dak1`,`那我先处理那部分，你看行吗？`],[`得，其他部分星期一再交。`,`dak1 kei4 taa1 bou6 fan6 sing1 kei4 jat1 zoi3 gaau1`,`行，其他部分星期一再交。`],[`好，我寫低個安排，大家確認吓。`,`hou2 ngo5 se2 dai1 go3 on1 paai4 daai6 gaa1 kok3 jing6 haa5`,`好，我把安排写下来，大家确认一下。`],[`我明白你急，不過我需要多啲時間。`,`ngo5 ming4 baak6 nei5 gap1 bat1 gwo3 ngo5 seoi1 jiu3 do1 di1 si4 gaan3`,`我明白你着急，不过我需要多一点时间。`],[`可唔可以各自退一步？`,`ho2 m4 ho2 ji5 gok3 zi6 teoi3 jat1 bou6`,`可以各自退让一步吗？`],[`如果改到下晝，我就可以配合。`,`jyu4 gwo2 goi2 dou3 haa6 zau3 ngo5 zau6 ho2 ji5 pui3 hap6`,`如果改到下午，我就可以配合。`],[`咁就照呢個方法做啦。`,`gam2 zau6 ziu3 ni1 go3 fong1 faat3 zou6 laa1`,`那就按照这个办法做吧。`]],words:[[`完成`,`jyun4 sing4`,`完成`],[`全部`,`cyun4 bou6`,`全部`],[`趕`,`gon2`,`赶；时间紧`],[`分兩次`,`fan1 loeng5 ci3`,`分两次`],[`諗住`,`nam2 zyu6`,`打算`],[`其餘`,`kei4 jyu4`,`其余`],[`處理`,`cyu2 lei5`,`处理`],[`各自`,`gok3 zi6`,`各自`],[`退一步`,`teoi3 jat1 bou6`,`退让一步`],[`配合`,`pui3 hap6`,`配合`]],patterns:[[`可唔可以＋替代方案？`,`提出可执行的替代办法，让对方回应。`,`可唔可以分兩次？`],[`如果＋調整，我就可以＋配合事項`,`清楚说明在什么条件下自己能够做到。`,`如果改到下晝，我就可以配合。`]],cultureNote:`商量时，说明做不到的具体原因，再提出可以做到的部分，会更容易推进。达成一致后，把时间和交付范围再确认一次。`,practicePrompt:`朋友希望周六一早出发，但你上午有事。说明限制，给出两个替代时间，商量后复述最终约定。`}),t({id:`express-yourself-apology`,topicId:`express-yourself`,level:3,title:`道歉与解开误会`,description:`道歉、误会与补救`,speakers:[`阿杰`,`阿欣`],phrases:[[`你尋日點解冇嚟？我等咗好耐。`,`nei5 cam4 jat6 dim2 gaai2 mou5 lai4 ngo5 dang2 zo2 hou2 noi6`,`你昨天为什么没有来？我等了很久。`],[`對唔住，我記錯咗時間。`,`deoi3 m4 zyu6 ngo5 gei3 co3 zo2 si4 gaan3`,`对不起，我记错了时间。`],[`我發咗訊息俾你，你都冇覆。`,`ngo5 faat3 zo2 seon3 sik1 bei2 nei5 nei5 dou1 mou5 fuk1`,`我发了消息给你，你也没有回复。`],[`我部電話冇電，返到屋企先睇到。`,`ngo5 bou6 din6 waa2 mou5 din6 faan1 dou3 uk1 kei2 sin1 tai2 dou2`,`我的手机没电了，回到家才看到。`],[`下次有變，麻煩你早啲講。`,`haa6 ci3 jau5 bin3 maa4 faan4 nei5 zou2 di1 gong2`,`下次有变化，麻烦你早点说。`],[`你講得啱，今次令你白等。`,`nei5 gong2 dak1 ngaam1 gam1 ci3 ling6 nei5 baak6 dang2`,`你说得对，这次让你白等了。`],[`好啦，講清楚就得。`,`hou2 laa1 gong2 cing1 co2 zau6 dak1`,`好吧，说清楚就行。`],[`我會記低提醒，唔會再搞錯。`,`ngo5 wui5 gei3 dai1 tai4 sing2 m4 wui5 zoi3 gaau2 co3`,`我会记下提醒，不会再弄错。`],[`唔好意思，可能我頭先講得唔清楚。`,`m4 hou2 ji3 si1 ho2 nang4 ngo5 tau4 sin1 gong2 dak1 m4 cing1 co2`,`不好意思，可能我刚才没说清楚。`],[`我唔係嗰個意思，想再解釋吓。`,`ngo5 m4 hai6 go2 go3 ji3 si1 soeng2 zoi3 gaai2 sik1 haa5`,`我不是那个意思，想再解释一下。`],[`原來咁，我誤會咗你。`,`jyun4 loi4 gam2 ngo5 ng6 wui6 zo2 nei5`,`原来如此，我误会你了。`],[`我可以點樣補救？`,`ngo5 ho2 ji5 dim2 joeng6 bou2 gau3`,`我可以怎样补救？`]],words:[[`對唔住`,`deoi3 m4 zyu6`,`对不起`],[`記錯`,`gei3 co3`,`记错`],[`冇電`,`mou5 din6`,`没电`],[`白等`,`baak6 dang2`,`白等`],[`提醒`,`tai4 sing2`,`提醒`],[`搞錯`,`gaau2 co3`,`弄错`],[`講清楚`,`gong2 cing1 co2`,`说清楚`],[`原來`,`jyun4 loi4`,`原来`],[`誤會`,`ng6 wui6`,`误会`],[`補救`,`bou2 gau3`,`补救`]],patterns:[[`對唔住，我＋做錯嘅事`,`直接承认具体疏漏，避免只有笼统道歉。`,`對唔住，我記錯咗時間。`],[`……先……`,`在回顾经过时，说明直到某个节点才发生另一件事。`,`返到屋企先睇到。`]],cultureNote:`“對唔住”适合对自己的失误道歉。解释经过时，也要承认对对方造成的影响，再提出一个能落实的补救或预防办法。`,practicePrompt:`你把一份旧文件发给了伙伴。承认错误、说清影响，并提出重新发送和核对版本的补救办法。`})],f=[t({id:`first-words-contact`,topicId:`first-words`,level:1,title:`核对姓名和电话`,description:`姓名写法、电话号码、逐位确认`,minutes:12,speakers:[`阿欣`,`阿晴`],phrases:[[`你個名點寫呀？`,`nei5 go3 meng2 dim2 se2 aa3`,`你的名字怎么写？`],[`耳東陳，晴天嘅晴。`,`ji5 dung1 can4 cing4 tin1 ge3 cing4`,`耳东陈，晴天的晴。`],[`電話號碼係幾多呀？`,`din6 waa2 hou6 maa5 hai6 gei2 do1 aa3`,`电话号码是多少？`],[`九三六二，五八一七。`,`gau2 saam1 luk6 ji6 ng5 baat3 jat1 cat1`,`九三六二，五八一七。`,`这里把示例号码分成两组，每个数字分开读。`],[`尾四個數字係五八一七？`,`mei5 sei3 go3 sou3 zi6 hai6 ng5 baat3 jat1 cat1`,`最后四个数字是五八一七？`],[`係呀，冇錯。`,`hai6 aa3 mou5 co3`,`对，没错。`],[`我而家打俾你，睇吓啱唔啱。`,`ngo5 ji4 gaa1 daa2 bei2 nei5 tai2 haa5 ngaam1 m4 ngaam1`,`我现在给你打电话，看看对不对。`],[`響喇，我記低你個名先。`,`hoeng2 laa3 ngo5 gei3 dai1 nei5 go3 meng2 sin1`,`响了，我先记下你的名字。`],[`個姓寫錯咗，係姓陳。`,`go3 sing3 se2 co3 zo2 hai6 sing3 can4`,`姓写错了，是姓陈。`],[`中間嗰個字唔係咁寫。`,`zung1 gaan1 go2 go3 zi6 m4 hai6 gam2 se2`,`中间那个字不是这样写的。`],[`呢個係我新電話號碼。`,`ni1 go3 hai6 ngo5 san1 din6 waa2 hou6 maa5`,`这是我的新电话号码。`],[`可唔可以讀返一次俾我聽？`,`ho2 m4 ho2 ji5 duk6 faan1 jat1 ci3 bei2 ngo5 teng1`,`可以再读一遍给我听吗？`]],words:[[`名`,`meng2`,`名字`],[`點寫`,`dim2 se2`,`怎么写`],[`晴天`,`cing4 tin1`,`晴天`],[`電話號碼`,`din6 waa2 hou6 maa5`,`电话号码`],[`尾`,`mei5`,`末尾；最后`],[`數字`,`sou3 zi6`,`数字`],[`冇錯`,`mou5 co3`,`没错`],[`響`,`hoeng2`,`响`],[`姓`,`sing3`,`姓氏；姓`],[`讀返`,`duk6 faan1`,`再读一遍`]],patterns:[[`名詞＋點寫？`,`用“点写”询问姓名或字词的写法。`,`你個姓點寫呀？`],[`尾＋數量＋個數字係……？`,`复述号码末尾的几位数字，请对方核对。`,`尾兩個數字係一七？`]],cultureNote:`说名字时，可以用熟悉的字词解释写法，例如“晴天嘅晴”。核对电话号码则逐位读，不把四位数字读成一个数。`,practicePrompt:`用虚构的姓名和八位号码练习交换联系方式。故意写错一个字或数字，请伙伴指出并重新确认。`}),t({id:`first-words-introduce-others`,topicId:`first-words`,level:2,title:`介绍两位朋友认识`,description:`人物关系、共同兴趣、称呼`,minutes:12,speakers:[`阿欣`,`阿晴`],phrases:[[`阿晴，介紹個同事俾你識。`,`aa3 cing4 gaai3 siu6 go3 tung4 si6 bei2 nei5 sik1`,`阿晴，介绍一位同事给你认识。`],[`好呀，佢點稱呼呀？`,`hou2 aa3 keoi5 dim2 cing1 fu1 aa3`,`好啊，他怎么称呼？`],[`佢叫阿文，同我一齊返工。`,`keoi5 giu3 aa3 man4 tung4 ngo5 jat1 cai4 faan1 gung1`,`他叫阿文，和我一起上班。`],[`你哋識咗幾耐呀？`,`nei5 dei6 sik1 zo2 gei2 noi6 aa3`,`你们认识多久了？`],[`兩年喇，佢都鍾意影相。`,`loeng5 nin4 laa3 keoi5 dou1 zung1 ji3 jing2 soeng2`,`两年了，他也喜欢拍照。`],[`咁啱嘅，我最近買咗部相機。`,`gam3 ngaam1 ge2 ngo5 zeoi3 gan6 maai5 zo2 bou6 soeng3 gei1`,`这么巧，我最近买了一台相机。`],[`佢喺門口，我哋過去搵佢啦。`,`keoi5 hai2 mun4 hau2 ngo5 dei6 gwo3 heoi3 wan2 keoi5 laa1`,`他在门口，我们过去找他吧。`],[`好呀，我都想問吓佢邊度影相靚。`,`hou2 aa3 ngo5 dou1 soeng2 man6 haa5 keoi5 bin1 dou6 jing2 soeng2 leng3`,`好啊，我也想问问他哪里适合拍照。`],[`呢位係我朋友阿晴。`,`ni1 wai2 hai6 ngo5 pang4 jau5 aa3 cing4`,`这位是我的朋友阿晴。`],[`我哋以前係同學。`,`ngo5 dei6 ji5 cin4 hai6 tung4 hok6`,`我们以前是同学。`],[`原來你哋一早識㗎喇？`,`jyun4 loi4 nei5 dei6 jat1 zou2 sik1 gaa3 laa3`,`原来你们早就认识了？`],[`大家叫我阿晴就得。`,`daai6 gaa1 giu3 ngo5 aa3 cing4 zau6 dak1`,`大家叫我阿晴就行。`]],words:[[`介紹`,`gaai3 siu6`,`介绍`],[`同事`,`tung4 si6`,`同事`],[`稱呼`,`cing1 fu1`,`称呼`],[`識咗幾耐`,`sik1 zo2 gei2 noi6`,`认识多久了`],[`影相`,`jing2 soeng2`,`拍照`],[`相機`,`soeng3 gei1`,`相机`],[`呢位`,`ni1 wai2`,`这位`],[`以前`,`ji5 cin4`,`以前`],[`同學`,`tung4 hok6`,`同学`],[`一早`,`jat1 zou2`,`早就；一早`]],patterns:[[`介紹＋人物＋俾你識`,`把某人介绍给对方认识。`,`介紹個朋友俾你識。`],[`呢位係我＋關係＋名字`,`面对面介绍第三个人的身份和姓名。`,`呢位係我同事阿文。`]],cultureNote:`介绍别人时，“呢位”比“呢個”客气。提一句双方都喜欢的活动，方便他们自己聊下去；称呼可以让本人再确认。`,practicePrompt:`把一位同事介绍给老同学，说明你们的关系和一个共同兴趣。再换角色，练习询问认识多久及希望使用的称呼。`}),t({id:`first-words-good-news`,topicId:`first-words`,level:1,title:`听到好消息`,description:`祝贺、致谢、邀请庆祝`,minutes:12,speakers:[`阿欣`,`阿晴`],phrases:[[`聽講你考到車牌喇？`,`teng1 gong2 nei5 haau2 dou2 ce1 paai4 laa3`,`听说你考到驾照了？`],[`係呀，今次終於考到喇！`,`hai6 aa3 gam1 ci3 zung1 jyu1 haau2 dou2 laa3`,`是啊，这次终于考到了！`],[`恭喜晒！你一定好開心。`,`gung1 hei2 saai3 nei5 jat1 ding6 hou2 hoi1 sam1`,`恭喜！你一定很开心。`],[`多謝呀，我練咗好耐。`,`do1 ze6 aa3 ngo5 lin6 zo2 hou2 noi6`,`谢谢，我练了很久。`],[`今晚一齊食飯慶祝吓？`,`gam1 maan5 jat1 cai4 sik6 faan6 hing3 zuk1 haa5`,`今晚一起吃饭庆祝一下？`],[`好呀，不過我七點先得閒。`,`hou2 aa3 bat1 gwo3 ngo5 cat1 dim2 sin1 dak1 haan4`,`好啊，不过我七点才有空。`],[`冇問題，七點喺樓下等。`,`mou5 man6 tai4 cat1 dim2 hai2 lau4 haa6 dang2`,`没问题，七点在楼下碰面。`],[`好，到時見！`,`hou2 dou3 si4 gin3`,`好，到时见！`],[`真係戥你開心。`,`zan1 hai6 dang2 nei5 hoi1 sam1`,`真替你高兴。`],[`你之前啲努力冇白費。`,`nei5 zi1 cin4 di1 nou5 lik6 mou5 baak6 fai3`,`你之前的努力没有白费。`],[`多謝你一路支持我。`,`do1 ze6 nei5 jat1 lou6 zi1 ci4 ngo5`,`谢谢你一直支持我。`],[`等我同屋企人講埋先。`,`dang2 ngo5 tung4 uk1 kei2 jan4 gong2 maai4 sin1`,`让我也先告诉家里人。`]],words:[[`聽講`,`teng1 gong2`,`听说`],[`車牌`,`ce1 paai4`,`驾照；车辆牌照`],[`終於`,`zung1 jyu1`,`终于`],[`恭喜`,`gung1 hei2`,`恭喜`],[`練`,`lin6`,`练习`],[`慶祝`,`hing3 zuk1`,`庆祝`],[`戥`,`dang2`,`替；为别人`],[`努力`,`nou5 lik6`,`努力`],[`白費`,`baak6 fai3`,`白费`],[`支持`,`zi1 ci4`,`支持`]],patterns:[[`聽講＋消息＋喇？`,`提起刚听说的消息，请本人确认。`,`聽講你搬咗新屋喇？`],[`戥＋人物＋開心`,`表达替别人高兴。`,`我哋都戥你開心。`]],cultureNote:`“戥你開心”里的“戥”表示替别人产生某种感受。收到祝贺可以直接说“多謝”；这里的“車牌”按对话语境指驾照。`,practicePrompt:`朋友考上了想读的课程。先确认消息并祝贺，再约一个双方方便的时间庆祝；朋友回应致谢并告诉家人。`}),t({id:`time-plans-opening-hours`,topicId:`time-plans`,level:1,title:`几点开门、几点关门`,description:`开放时间、最后入场、休息日`,minutes:12,speakers:[`访客`,`职员`],phrases:[[`唔該，你哋聽日幾點開門？`,`m4 goi1 nei5 dei6 ting1 jat6 gei2 dim2 hoi1 mun4`,`请问，你们明天几点开门？`],[`朝早十點開，下晝六點關。`,`ziu1 zou2 sap6 dim2 hoi1 haa6 zau3 luk6 dim2 gwaan1`,`上午十点开门，下午六点关门。`],[`最遲幾點可以入場呀？`,`zeoi3 ci4 gei2 dim2 ho2 ji5 jap6 coeng4 aa3`,`最晚几点可以入场？`],[`五點半之後就唔俾入喇。`,`ng5 dim2 bun3 zi1 hau6 zau6 m4 bei2 jap6 laa3`,`五点半之后就不能入场了。`],[`咁我五點到，仲入唔入得？`,`gam2 ngo5 ng5 dim2 dou3 zung6 jap6 m4 jap6 dak1`,`那我五点到，还能入场吗？`],[`入得，不過得返一個鐘睇。`,`jap6 dak1 bat1 gwo3 dak1 faan1 jat1 go3 zung1 tai2`,`能，不过只剩一个小时参观。`],[`明白，星期一都開㗎？`,`ming4 baak6 sing1 kei4 jat1 dou1 hoi1 gaa3`,`明白，星期一也开门吗？`],[`星期一休息，你星期二先嚟啦。`,`sing1 kei4 jat1 jau1 sik1 nei5 sing1 kei4 ji6 sin1 lai4 laa1`,`星期一休息，你星期二再来吧。`],[`我哋中午照常開放。`,`ngo5 dei6 zung1 ng5 ziu3 soeng4 hoi1 fong3`,`我们中午照常开放。`],[`今日提早半個鐘關門。`,`gam1 jat6 tai4 zou2 bun3 go3 zung1 gwaan1 mun4`,`今天提前半小时关门。`],[`假期會唔會改開放時間？`,`gaa3 kei4 wui5 m4 wui5 goi2 hoi1 fong3 si4 gaan3`,`假期会改变开放时间吗？`],[`我睇吓門口張通告先。`,`ngo5 tai2 haa5 mun4 hau2 zoeng1 tung1 gou3 sin1`,`我先看看门口的通知。`]],words:[[`開門`,`hoi1 mun4`,`开门；开始营业`],[`關門`,`gwaan1 mun4`,`关门；结束营业`],[`最遲`,`zeoi3 ci4`,`最晚`],[`入場`,`jap6 coeng4`,`入场`],[`得返`,`dak1 faan1`,`只剩下`],[`休息`,`jau1 sik1`,`休息`],[`照常`,`ziu3 soeng4`,`照常`],[`開放時間`,`hoi1 fong3 si4 gaan3`,`开放时间`],[`提早`,`tai4 zou2`,`提前`],[`通告`,`tung1 gou3`,`通知；通告`]],patterns:[[`幾點＋開門／關門？`,`询问营业或开放的开始、结束时间。`,`你哋星期六幾點關門？`],[`時間＋之後＋就唔＋動作`,`说明某个时间之后停止做什么。`,`五點半之後就唔俾入喇。`]],cultureNote:`“關門”时间和最后入场时间可以不同。“得返一個鐘”表示只剩一个小时，问清这两个时间后，便能算出还有多久可以参观。`,practicePrompt:`打电话问展馆明天几点开关门、最晚几点入场，以及周一是否开放。再选择一个够时间参观的到达时间。`}),t({id:`time-plans-running-late`,topicId:`time-plans`,level:2,title:`路上更新到达时间`,description:`误车、当前位置、改碰面点`,minutes:13,speakers:[`阿晴`,`阿欣`],phrases:[[`我啱啱上車，會遲十分鐘到。`,`ngo5 ngaam1 ngaam1 soeng5 ce1 wui5 ci4 sap6 fan1 zung1 dou3`,`我刚上车，会晚十分钟到。`],[`你而家去到邊個站？`,`nei5 ji4 gaa1 heoi3 dou3 bin1 go3 zaam6`,`你现在到哪个站了？`],[`仲有兩個站，五點十分應該到。`,`zung6 jau5 loeng5 go3 zaam6 ng5 dim2 sap6 fan1 jing1 goi1 dou3`,`还有两站，应该五点十分到。`],[`好，我行去天橋下面等你。`,`hou2 ngo5 haang4 heoi3 tin1 kiu4 haa6 min6 dang2 nei5`,`好，我走到天桥下面等你。`],[`唔好意思，頭先等錯咗車。`,`m4 hou2 ji3 si1 tau4 sin1 dang2 co3 zo2 ce1`,`不好意思，刚才等错车了。`],[`唔緊要，到咗再搵我。`,`m4 gan2 jiu3 dou3 zo2 zoi3 wan2 ngo5`,`没关系，到了再联系我。`],[`我落車喇，行過去仲要兩分鐘。`,`ngo5 lok6 ce1 laa3 haang4 gwo3 heoi3 zung6 jiu3 loeng5 fan1 zung1`,`我下车了，走过去还要两分钟。`],[`見到你喇，我喺你左手邊。`,`gin3 dou2 nei5 laa3 ngo5 hai2 nei5 zo2 sau2 bin1`,`看到你了，我在你左边。`],[`架車仲未開，可能要再遲啲。`,`gaa3 ce1 zung6 mei6 hoi1 ho2 nang4 jiu3 zoi3 ci4 di1`,`车还没开，可能要再晚一点。`],[`我行緊去出口，唔使轉地方。`,`ngo5 haang4 gan2 heoi3 ceot1 hau2 m4 sai2 zyun3 dei6 fong1`,`我正在往出口走，不用换地方。`],[`如果你趕時間，可以先走。`,`jyu4 gwo2 nei5 gon2 si4 gaan3 ho2 ji5 sin1 zau2`,`如果你赶时间，可以先走。`],[`多謝你等我咁耐。`,`do1 ze6 nei5 dang2 ngo5 gam3 noi6`,`谢谢你等我这么久。`]],words:[[`上車`,`soeng5 ce1`,`上车`],[`遲十分鐘`,`ci4 sap6 fan1 zung1`,`晚十分钟`],[`去到`,`heoi3 dou3`,`到达；到`],[`應該`,`jing1 goi1`,`应该；预计`],[`天橋`,`tin1 kiu4`,`天桥`],[`下面`,`haa6 min6`,`下面`],[`等錯`,`dang2 co3`,`等错`],[`落車`,`lok6 ce1`,`下车`],[`左手邊`,`zo2 sau2 bin1`,`左边`],[`趕時間`,`gon2 si4 gaan3`,`赶时间`]],patterns:[[`仲有＋數量＋個站`,`用剩余站数说明自己离目的地还有多远。`,`仲有三個站先到。`],[`時間＋應該到`,`给出预计到达时间，保留估计的语气。`,`五點十分應該到。`]],cultureNote:`“去到邊”问的是当前位置。“遲十分鐘”说晚了多久，“五點十分到”说具体几点到，两种说法可以一起用来说明情况。`,practicePrompt:`和朋友约好五点见面，却等错了车。说明晚多久、还有几站及预计几点到，再确认朋友换到哪个地方等。`}),t({id:`time-plans-errands`,topicId:`time-plans`,level:2,title:`安排一周的杂事`,description:`取衣、寄包裹、还书、顺路安排`,minutes:13,speakers:[`阿欣`,`阿晴`],phrases:[[`你今個星期有啲咩要辦？`,`nei5 gam1 go3 sing1 kei4 jau5 di1 me1 jiu3 baan6`,`你这星期有什么事要办？`],[`要攞衫、寄包裹，仲要還書。`,`jiu3 lo2 saam1 gei3 baau1 gwo2 zung6 jiu3 waan4 syu1`,`要取衣服、寄包裹，还要还书。`],[`咁你諗住點樣安排？`,`gam2 nei5 nam2 zyu6 dim2 joeng6 on1 paai4`,`那你打算怎么安排？`],[`星期二收工先去攞衫。`,`sing1 kei4 ji6 sau1 gung1 sin1 heoi3 lo2 saam1`,`星期二下班先去取衣服。`],[`寄包裹同還書呢？`,`gei3 baau1 gwo2 tung4 waan4 syu1 ne1`,`寄包裹和还书呢？`],[`星期四放假，一個朝早做晒。`,`sing1 kei4 sei3 fong3 gaa3 jat1 go3 ziu1 zou2 zou6 saai3`,`星期四休息，一个上午全部办完。`],[`郵局同圖書館近唔近？`,`jau4 guk6 tung4 tou4 syu1 gun2 gan6 m4 gan6`,`邮局和图书馆近吗？`],[`好近，可以順路去。`,`hou2 gan6 ho2 ji5 seon6 lou6 heoi3`,`很近，可以顺路去。`],[`我列張清單，免得漏咗嘢。`,`ngo5 lit6 zoeng1 cing1 daan1 min5 dak1 lau6 zo2 je5`,`我列张清单，免得漏了事情。`],[`呢樣唔急，下星期先做。`,`ni1 joeng6 m4 gap1 haa6 sing1 kei4 sin1 zou6`,`这件事不急，下星期再做。`],[`寄之前要包好份嘢。`,`gei3 zi1 cin4 jiu3 baau1 hou2 fan6 je5`,`寄之前要把东西包好。`],[`做完一樣就剔一樣。`,`zou6 jyun4 jat1 joeng6 zau6 tik1 jat1 joeng6`,`做完一项就勾掉一项。`]],words:[[`辦`,`baan6`,`办理；办事`],[`攞衫`,`lo2 saam1`,`取衣服`],[`寄包裹`,`gei3 baau1 gwo2`,`寄包裹`],[`還書`,`waan4 syu1`,`还书`],[`收工`,`sau1 gung1`,`下班`],[`做晒`,`zou6 saai3`,`全部做完`],[`順路`,`seon6 lou6`,`顺路`],[`清單`,`cing1 daan1`,`清单`],[`漏`,`lau6`,`遗漏`],[`剔`,`tik1`,`打勾`]],patterns:[[`時間＋先＋動作`,`用时间交代先做哪件事，或把事情留到何时做。`,`星期二先去攞衫。`],[`做完一樣就＋動作＋一樣`,`每完成一项，就对这一项做相应处理。`,`做完一樣就剔一樣。`]],cultureNote:`“攞衫”在这个场景指到洗衣店取衣服。“做晒”的“晒”表示全部完成；“剔”指在项目旁打勾，读第一声。`,practicePrompt:`列出这周要办的三件杂事，安排不同日期和先后次序。向伙伴说明哪两件可以顺路做，哪一件可以延后。`}),t({id:`work-interview`,topicId:`work`,level:2,title:`面试时介绍工作经历`,description:`之前的工作、职责、到岗时间`,minutes:14,speakers:[`招聘同事`,`求职者`],phrases:[[`你之前做過咩工作？`,`nei5 zi1 cin4 zou6 gwo3 me1 gung1 zok3`,`你之前做过什么工作？`],[`我喺書店做咗兩年。`,`ngo5 hai2 syu1 dim3 zou6 zo2 loeng5 nin4`,`我在书店做了两年。`],[`主要負責啲咩？`,`zyu2 jiu3 fu6 zaak3 di1 me1`,`主要负责些什么？`],[`招呼客人，同埋整理新書。`,`ziu1 fu1 haak3 jan4 tung4 maai4 zing2 lei5 san1 syu1`,`接待客人，还有整理新书。`],[`如果請你，幾時可以返工？`,`jyu4 gwo2 cing2 nei5 gei2 si4 ho2 ji5 faan1 gung1`,`如果录用你，什么时候可以上班？`],[`下個月一號可以開始。`,`haa6 go3 jyut6 jat1 hou6 ho2 ji5 hoi1 ci2`,`下个月一号可以开始。`],[`星期六同日都可以返？`,`sing1 kei4 luk6 tung4 jat6 dou1 ho2 ji5 faan1`,`星期六和星期日都可以来上班吗？`],[`可以，不過星期三夜晚要上堂。`,`ho2 ji5 bat1 gwo3 sing1 kei4 saam1 je6 maan5 jiu3 soeng5 tong4`,`可以，不过星期三晚上要上课。`],[`我份履歷有寫之前嘅工作。`,`ngo5 fan6 leoi5 lik6 jau5 se2 zi1 cin4 ge3 gung1 zok3`,`我的简历写了以前的工作。`],[`我未做過呢方面，但願意學。`,`ngo5 mei6 zou6 gwo3 ni1 fong1 min6 daan6 jyun6 ji3 hok6`,`我没做过这方面的工作，但愿意学。`],[`想問吓平時點樣編更？`,`soeng2 man6 haa5 ping4 si4 dim2 joeng6 pin1 gang1`,`想问问平时怎样排班？`],[`唔該，我會等你哋通知。`,`m4 goi1 ngo5 wui5 dang2 nei5 dei6 tung1 zi1`,`谢谢，我会等你们通知。`]],words:[[`之前`,`zi1 cin4`,`以前；之前`],[`做過`,`zou6 gwo3`,`做过`],[`書店`,`syu1 dim3`,`书店`],[`主要`,`zyu2 jiu3`,`主要`],[`負責`,`fu6 zaak3`,`负责`],[`招呼`,`ziu1 fu1`,`接待；招呼`],[`整理`,`zing2 lei5`,`整理`],[`履歷`,`leoi5 lik6`,`简历`],[`願意`,`jyun6 ji3`,`愿意`],[`編更`,`pin1 gang1`,`排班`]],patterns:[[`喺＋地方＋做咗＋時長`,`介绍在某个单位工作的时间。`,`我喺書店做咗兩年。`],[`可以，不過＋時間限制`,`先回应可以做到的部分，再说明不能配合的时段。`,`可以，不過星期三夜晚要上堂。`]],cultureNote:`“見工”指求职面试，“更”在排班话题中指一个工作班次。这里用“請你”表示录用你，不能一律理解成请客。`,practicePrompt:`面试书店职位：说明做过什么、做了多久和主要职责，再回答何时能到岗、哪段时间不方便，并询问排班。`}),t({id:`work-printing`,topicId:`work`,level:2,title:`打印和复印文件`,description:`份数、单双面、缺纸、装订`,minutes:13,speakers:[`阿晴`,`同事`],phrases:[[`呢份文件要印幾多份？`,`ni1 fan6 man4 gin6 jiu3 jan3 gei2 do1 fan6`,`这份文件要打印多少份？`],[`印六份，黑白就得。`,`jan3 luk6 fan6 hak1 baak6 zau6 dak1`,`打印六份，黑白就行。`],[`要單面定雙面呀？`,`jiu3 daan1 min6 ding6 soeng1 min6 aa3`,`要单面还是双面？`],[`雙面，印好每份都釘埋一齊。`,`soeng1 min6 jan3 hou2 mui5 fan6 dou1 deng1 maai4 jat1 cai4`,`双面，打印好后每份都订在一起。`],[`部機冇紙喇，啲紙擺喺邊？`,`bou6 gei1 mou5 zi2 laa3 di1 zi2 baai2 hai2 bin1`,`机器没纸了，纸放在哪儿？`],[`下面個櫃有，你攞一包啦。`,`haa6 min6 go3 gwai6 jau5 nei5 lo2 jat1 baau1 laa1`,`下面的柜子有，你拿一包吧。`],[`搵到喇，我印一份俾你睇先。`,`wan2 dou2 laa3 ngo5 jan3 jat1 fan6 bei2 nei5 tai2 sin1`,`找到了，我先打一份给你看看。`],[`冇問題就照呢份印其餘嗰啲。`,`mou5 man6 tai4 zau6 ziu3 ni1 fan6 jan3 kei4 jyu4 go2 di1`,`没问题就按这一份打印其余的。`],[`唔該，幫我影印呢兩頁。`,`m4 goi1 bong1 ngo5 jing2 jan3 ni1 loeng5 jip6`,`麻烦帮我复印这两页。`],[`呢頁印得太淡，睇唔清楚。`,`ni1 jip6 jan3 dak1 taai3 taam5 tai2 m4 cing1 co2`,`这一页印得太浅，看不清楚。`],[`印之前先睇吓頁數啱唔啱。`,`jan3 zi1 cin4 sin1 tai2 haa5 jip6 sou3 ngaam1 m4 ngaam1`,`打印之前先看看页数对不对。`],[`印好嘅文件放喺枱面。`,`jan3 hou2 ge3 man4 gin6 fong3 hai2 toi2 min6`,`打印好的文件放在桌面上。`]],words:[[`印`,`jan3`,`打印；印刷`],[`份`,`fan6`,`份；文件的量词`],[`黑白`,`hak1 baak6`,`黑白`],[`單面`,`daan1 min6`,`单面`],[`雙面`,`soeng1 min6`,`双面`],[`釘`,`deng1`,`装订；钉上`],[`紙`,`zi2`,`纸`],[`櫃`,`gwai6`,`柜子`],[`影印`,`jing2 jan3`,`复印`],[`頁數`,`jip6 sou3`,`页数`]],patterns:[[`要＋選項甲＋定＋選項乙？`,`确认文件的打印方式。`,`要黑白定彩色呀？`],[`動作＋好＋幫我＋另一動作`,`说明前一项做完后，还要顺手做什么。`,`印好幫我釘埋一齊。`]],cultureNote:`“印六份”说的是六套文件，“印六頁”说的是页数。“影印”一般指复印，交代单双面、份数和装订方式时可分开说。`,practicePrompt:`请同事复印一份两页的文件，说明份数、颜色和单双面。机器缺纸时问纸放哪儿，并先印一份核对。`}),t({id:`work-handover`,topicId:`work`,level:3,title:`核对交接清单`,description:`已完成、待处理、资料位置、接手人`,minutes:15,speakers:[`阿晴`,`阿文`],phrases:[[`我哋逐項對吓張交接清單。`,`ngo5 dei6 zuk6 hong6 deoi3 haa5 zoeng1 gaau1 zip3 cing1 daan1`,`我们逐项核对一下交接清单。`],[`好，邊啲已經做完？`,`hou2 bin1 di1 ji5 ging1 zou6 jyun4`,`好，哪些已经做完？`],[`書已經點好，仲有兩箱未送到。`,`syu1 ji5 ging1 dim2 hou2 zung6 jau5 loeng5 soeng1 mei6 sung3 dou3`,`书已经清点好了，还有两箱没送到。`],[`嗰兩箱由邊個跟？`,`go2 loeng5 soeng1 jau4 bin1 go3 gan1`,`那两箱由谁跟进？`],[`阿文，你接手收貨，單喺呢度。`,`aa3 man4 nei5 zip3 sau2 sau1 fo3 daan1 hai2 ni1 dou6`,`阿文，你接手收货，单据在这里。`],[`收到，我會先對數量再簽收。`,`sau1 dou2 ngo5 wui5 sin1 deoi3 sou3 loeng6 zoi3 cim1 sau1`,`收到，我会先核对数量再签收。`],[`有唔啱就記低，再話我知。`,`jau5 m4 ngaam1 zau6 gei3 dai1 zoi3 waa6 ngo5 zi1`,`有不对的就记下来，再告诉我。`],[`好，收齊之後我會更新張表。`,`hou2 sau1 cai4 zi1 hau6 ngo5 wui5 gang1 san1 zoeng1 biu2`,`好，收齐之后我会更新表格。`],[`未做完嗰啲，我用黃色標咗。`,`mei6 zou6 jyun4 go2 di1 ngo5 jung6 wong4 sik1 biu1 zo2`,`没做完的那些，我用黄色标出来了。`],[`最新嗰份資料擺喺共用電腦入面。`,`zeoi3 san1 go2 fan6 zi1 liu2 baai2 hai2 gung6 jung6 din6 nou5 jap6 min6`,`最新的资料放在共用电脑里。`],[`呢項等對方覆咗先處理。`,`ni1 hong6 dang2 deoi3 fong1 fuk1 zo2 sin1 cyu2 lei5`,`这一项等对方回复后再处理。`],[`我再講一次，睇吓有冇漏。`,`ngo5 zoi3 gong2 jat1 ci3 tai2 haa5 jau5 mou5 lau6`,`我再说一遍，看看有没有遗漏。`]],words:[[`逐項`,`zuk6 hong6`,`逐项`],[`交接清單`,`gaau1 zip3 cing1 daan1`,`交接清单`],[`點好`,`dim2 hou2`,`清点好`],[`箱`,`soeng1`,`箱；箱子`],[`接手`,`zip3 sau2`,`接手`],[`收貨`,`sau1 fo3`,`收货`],[`數量`,`sou3 loeng6`,`数量`],[`簽收`,`cim1 sau1`,`签收`],[`更新`,`gang1 san1`,`更新`],[`共用電腦`,`gung6 jung6 din6 nou5`,`共用电脑`]],patterns:[[`已經＋完成事項，仲有＋未完成事項`,`把完成的部分和剩下的部分分开说明。`,`書已經點好，仲有兩箱未送到。`],[`先＋核對事項＋再＋下一步`,`交代两个动作的先后次序。`,`先對數量再簽收。`]],cultureNote:`“點書”里的“點”是清点，“跟”可以简指跟进某件事。核对清单时，用“做完”和“未做完”区分状态，再说清由谁接手。`,practicePrompt:`交接一批新书：两箱未到，其他已清点。说明单据放在哪里、谁负责收货、收齐后更新什么，并请对方复述。`}),t({id:`express-yourself-disagreement`,topicId:`express-yourself`,level:3,title:`和朋友有不同意见`,description:`聚会安排、具体顾虑、替代办法`,minutes:14,speakers:[`阿欣`,`阿晴`],phrases:[[`生日會喺公園搞，你覺得點？`,`saang1 jat6 wui6 hai2 gung1 jyun2 gaau2 nei5 gok3 dak1 dim2`,`生日会在公园办，你觉得怎么样？`],[`地方係靚，不過我有啲擔心。`,`dei6 fong1 hai6 leng3 bat1 gwo3 ngo5 jau5 di1 daam1 sam1`,`地方是漂亮，不过我有点担心。`],[`你擔心會落雨？`,`nei5 daam1 sam1 wui5 lok6 jyu5`,`你担心会下雨？`],[`除咗落雨，搬枱凳都幾麻煩。`,`ceoi4 zo2 lok6 jyu5 bun1 toi2 dang3 dou1 gei2 maa4 faan4`,`除了下雨，搬桌椅也挺麻烦。`],[`但係我想有多啲地方俾細路玩。`,`daan6 hai6 ngo5 soeng2 jau5 do1 di1 dei6 fong1 bei2 sai3 lou6 waan2`,`但我想有更多地方让孩子们玩。`],[`我明，不過搵個有室內地方嘅場會好啲。`,`ngo5 ming4 bat1 gwo3 wan2 go3 jau5 sat1 noi6 dei6 fong1 ge3 coeng4 wui5 hou2 di1`,`我明白，不过找个有室内空间的场地会好一些。`],[`咁我哋睇多兩個地方先決定？`,`gam2 ngo5 dei6 tai2 do1 loeng5 go3 dei6 fong1 sin1 kyut3 ding6`,`那我们再看两个地方才决定？`],[`好呀，搵到再一齊比較。`,`hou2 aa3 wan2 dou2 zoi3 jat1 cai4 bei2 gaau3`,`好啊，找到再一起比较。`],[`呢點我唔太同意。`,`ni1 dim2 ngo5 m4 taai3 tung4 ji3`,`这一点我不太同意。`],[`我唔係反對，只係想問清楚。`,`ngo5 m4 hai6 faan2 deoi3 zi2 hai6 soeng2 man6 cing1 co2`,`我不是反对，只是想问清楚。`],[`你講嗰點有道理，我再諗吓。`,`nei5 gong2 go2 dim2 jau5 dou6 lei5 ngo5 zoi3 nam2 haa5`,`你说的那一点有道理，我再想想。`],[`我哋對呢件事嘅睇法唔同。`,`ngo5 dei6 deoi3 ni1 gin6 si6 ge3 tai2 faat3 m4 tung4`,`我们对这件事的看法不同。`]],words:[[`生日會`,`saang1 jat6 wui6`,`生日会`],[`搞`,`gaau2`,`举办；弄`],[`擔心`,`daam1 sam1`,`担心`],[`枱凳`,`toi2 dang3`,`桌椅`],[`細路`,`sai3 lou6`,`小孩`],[`室內`,`sat1 noi6`,`室内`],[`決定`,`kyut3 ding6`,`决定`],[`反對`,`faan2 deoi3`,`反对`],[`道理`,`dou6 lei5`,`道理`],[`睇法`,`tai2 faat3`,`看法`]],patterns:[[`……係……，不過……`,`承认对方提到的优点，再提出顾虑。`,`地方係靚，不過我有啲擔心。`],[`我唔係＋甲，只係＋乙`,`澄清自己的意思，说明真正想表达什么。`,`我唔係反對，只係想問清楚。`]],cultureNote:`“細路”是口语中的小孩。“地方係靚”把“靚”作为已经认可的部分，后面的“不过”再引出保留意见，语气取决于说话方式。`,practicePrompt:`朋友想在公园办生日会，你担心搬桌椅和下雨。先回应公园的优点，再说明两点顾虑，商量下一步看场地。`}),t({id:`express-yourself-advice`,topicId:`express-yourself`,level:3,title:`给朋友一点建议`,description:`预算、用途、取舍、保留意见`,minutes:14,speakers:[`阿晴`,`阿欣`],phrases:[[`我想買部相機，你有咩建議？`,`ngo5 soeng2 maai5 bou6 soeng3 gei1 nei5 jau5 me1 gin3 ji5`,`我想买台相机，你有什么建议？`],[`你打算用嚟影啲咩？`,`nei5 daa2 syun3 jung6 lai4 jing2 di1 me1`,`你打算用来拍什么？`],[`主要去旅行影相，唔想太重。`,`zyu2 jiu3 heoi3 leoi5 hang4 jing2 soeng2 m4 soeng2 taai3 cung5`,`主要旅行时拍照，不想太重。`],[`咁不如先睇吓細部嗰啲。`,`gam2 bat1 jyu4 sin1 tai2 haa5 sai3 bou6 go2 di1`,`那不如先看看体积小的那些。`],[`細部係方便，不過會唔會貴啲？`,`sai3 bou6 hai6 fong1 bin6 bat1 gwo3 wui5 m4 wui5 gwai3 di1`,`体积小是方便，不过会不会贵一些？`],[`唔一定，要睇你預幾多錢。`,`m4 jat1 ding6 jiu3 tai2 nei5 jyu6 gei2 do1 cin2`,`不一定，要看你预算多少钱。`],[`我預四千蚊，最緊要帶出街方便。`,`ngo5 jyu6 sei3 cin1 man1 zeoi3 gan2 jiu3 daai3 ceot1 gaai1 fong1 bin6`,`我预算四千元，最要紧是带出门方便。`],[`咁去舖頭試吓，睇吓重量同手感啱唔啱。`,`gam2 heoi3 pou3 tau4 si3 haa5 tai2 haa5 cung5 loeng6 tung4 sau2 gam2 ngaam1 m4 ngaam1`,`那去店里试试，看看重量和手感合不合适。`],[`如果係我，我會先借部嚟試。`,`jyu4 gwo2 hai6 ngo5 ngo5 wui5 sin1 ze3 bou6 lai4 si3`,`如果是我，我会先借一台来试。`],[`各有好處，要睇你重視啲咩。`,`gok3 jau5 hou2 cyu3 jiu3 tai2 nei5 zung6 si6 di1 me1`,`各有好处，要看你看重什么。`],[`我未用過呢款，唔敢亂講。`,`ngo5 mei6 jung6 gwo3 ni1 fun2 m4 gam2 lyun6 gong2`,`我没用过这一款，不敢乱说。`],[`你可以參考吓，唔使即刻決定。`,`nei5 ho2 ji5 caam1 haau2 haa5 m4 sai2 zik1 hak1 kyut3 ding6`,`你可以参考一下，不用马上决定。`]],words:[[`建議`,`gin3 ji5`,`建议`],[`打算`,`daa2 syun3`,`打算`],[`用嚟`,`jung6 lai4`,`用来`],[`細部`,`sai3 bou6`,`体积小`],[`預`,`jyu6`,`预计；预留预算`],[`重量`,`cung5 loeng6`,`重量`],[`手感`,`sau2 gam2`,`手感`],[`重視`,`zung6 si6`,`重视`],[`亂講`,`lyun6 gong2`,`乱说`],[`參考`,`caam1 haau2`,`参考`]],patterns:[[`打算＋用嚟＋動作`,`先问物品的用途，再讨论选择。`,`你打算用嚟影啲咩？`],[`如果係我，我會……`,`把建议说成自己的选择，留给对方决定。`,`如果係我，我會先借部嚟試。`]],cultureNote:`“部”常作相机、电话等机器的量词，“細部”说的是机器体积小。“預四千蚊”是在说预算，“最緊要”用来说明自己最看重的条件。`,practicePrompt:`朋友要买一台旅行用相机。先问用途、预算和最看重什么，再给出一个有条件的建议，并说明自己没试过的部分。`}),t({id:`express-yourself-description`,topicId:`express-yourself`,level:3,title:`描述找不到的东西`,description:`外观、大小、特征、最后出现的位置`,minutes:14,speakers:[`阿晴`,`阿欣`],phrases:[[`你有冇見到我個銀包？`,`nei5 jau5 mou5 gin3 dou2 ngo5 go3 ngan4 baau1`,`你有没有看到我的钱包？`],[`你個銀包係點樣㗎？`,`nei5 go3 ngan4 baau1 hai6 dim2 joeng6 gaa3`,`你的钱包是什么样的？`],[`深藍色，長方形，前面有個扣。`,`sam1 laam4 sik1 coeng4 fong1 jing4 cin4 min6 jau5 go3 kau3`,`深蓝色，长方形，前面有个扣子。`],[`大概有幾大個？`,`daai6 koi3 jau5 gei2 daai6 go3`,`大概有多大？`],[`比手掌長少少，個角有啲甩皮。`,`bei2 sau2 zoeng2 coeng4 siu2 siu2 go3 gok3 jau5 di1 lat1 pei4`,`比手掌长一点，角上有点掉皮。`],[`你最後一次用係喺邊度？`,`nei5 zeoi3 hau6 jat1 ci3 jung6 hai6 hai2 bin1 dou6`,`你最后一次是在哪里用的？`],[`頭先買完嘢，可能擺咗喺梳化。`,`tau4 sin1 maai5 jyun4 je5 ho2 nang4 baai2 zo2 hai2 so1 faa2`,`刚才买完东西，可能放在沙发上了。`],[`等我睇吓，係咪呢個？`,`dang2 ngo5 tai2 haa5 hai6 mai6 ni1 go3`,`我看看，是不是这个？`],[`就係呢個，喺坐墊下面。`,`zau6 hai6 ni1 go3 hai2 co5 din3 haa6 min6`,`就是这个，在坐垫下面。`],[`佢有條紅色拉鏈。`,`keoi5 jau5 tiu4 hung4 sik1 laai1 lin2`,`它有一条红色拉链。`],[`側邊貼咗張細貼紙。`,`zak1 bin1 tip3 zo2 zoeng1 sai3 tip3 zi2`,`侧面贴了一张小贴纸。`],[`我再搵吓個袋入面先。`,`ngo5 zoi3 wan2 haa5 go3 doi2 jap6 min6 sin1`,`我再找找包里面。`]],words:[[`銀包`,`ngan4 baau1`,`钱包`],[`深藍色`,`sam1 laam4 sik1`,`深蓝色`],[`長方形`,`coeng4 fong1 jing4`,`长方形`],[`扣`,`kau3`,`扣子`],[`手掌`,`sau2 zoeng2`,`手掌`],[`甩皮`,`lat1 pei4`,`掉皮；表层脱落`],[`梳化`,`so1 faa2`,`沙发`],[`坐墊`,`co5 din3`,`坐垫`],[`拉鏈`,`laai1 lin2`,`拉链`],[`貼紙`,`tip3 zi2`,`贴纸`]],patterns:[[`比＋參照物＋形容詞＋少少`,`借熟悉的物品说明大小差异。`,`比手掌長少少。`],[`位置＋有／貼咗＋特徵`,`说出物品某个部位容易认出的特征。`,`側邊貼咗張細貼紙。`]],cultureNote:`“銀包”指钱包，“梳化”指沙发。“甩皮”可以形容钱包表面材料脱落；描述失物时，颜色以外的特征更容易区分相似物品。`,practicePrompt:`选一件物品，向朋友描述颜色、形状、大小和特别标记，再说最后一次在哪里用，让朋友拿两件相似物品请你确认。`})],p=[t({id:`food-drink-reservation`,topicId:`food-drink`,level:2,minutes:13,title:`订餐厅与选座位`,description:`订位时间、卡位与到店确认`,speakers:[`你`,`店员`],phrases:[[`唔該，我想訂位，聽晚嚟。`,`m4 goi1 ngo5 soeng2 deng6 wai2 ting1 maan5 lai4`,`您好，我想订座位，明晚来。`],[`幾位用餐，同埋想訂幾點？`,`gei2 wai2 jung6 caan1 tung4 maai4 soeng2 deng6 gei2 dim2`,`几位用餐，还有想订几点？`],[`四位，夜晚七點有冇位？`,`sei3 wai2 je6 maan5 cat1 dim2 jau5 mou5 wai2`,`四位，晚上七点有座位吗？`],[`七點滿咗，六點半得唔得？`,`cat1 dim2 mun5 zo2 luk6 dim2 bun3 dak1 m4 dak1`,`七点已经满了，六点半可以吗？`],[`得呀，有冇卡位？`,`dak1 aa3 jau5 mou5 kaa1 wai2`,`可以，有卡座吗？`],[`有，我幫你留張卡位枱。`,`jau5 ngo5 bong1 nei5 lau4 zoeng1 kaa1 wai2 toi2`,`有，我帮你留一张卡座的桌子。`],[`唔該，姓陳，電話號碼寫喺呢度。`,`m4 goi1 sing3 can4 din6 waa2 hou6 maa5 se2 hai2 ni1 dou6`,`谢谢，我姓陈，电话号码写在这里。`],[`好，聽晚六點半，四位，陳生。`,`hou2 ting1 maan5 luk6 dim2 bun3 sei3 wai2 can4 saang1`,`好的，明晚六点半，四位，陈先生。`],[`可唔可以安排靠窗嘅位？`,`ho2 m4 ho2 ji5 on1 paai4 kaau3 coeng1 ge3 wai2`,`可以安排靠窗的座位吗？`],[`我哋有位小朋友，需要一張兒童椅。`,`ngo5 dei6 jau5 wai2 siu2 pang4 jau5 seoi1 jiu3 jat1 zoeng1 ji4 tung4 ji2`,`我们有一位小朋友，需要一张儿童椅。`],[`唔該，我訂咗位，姓陳。`,`m4 goi1 ngo5 deng6 zo2 wai2 sing3 can4`,`您好，我订了座位，姓陈。`],[`我哋會遲十分鐘到，張枱可以留到幾點？`,`ngo5 dei6 wui5 ci4 sap6 fan1 zung1 dou3 zoeng1 toi2 ho2 ji5 lau4 dou3 gei2 dim2`,`我们会晚十分钟到，桌子可以保留到几点？`]],words:[[`訂位`,`deng6 wai2`,`预订座位`],[`聽晚`,`ting1 maan5`,`明晚`],[`用餐`,`jung6 caan1`,`用餐`],[`夜晚`,`je6 maan5`,`晚上`],[`滿咗`,`mun5 zo2`,`已经满了`],[`卡位`,`kaa1 wai2`,`卡座`],[`靠窗`,`kaau3 coeng1`,`靠窗`],[`安排`,`on1 paai4`,`安排`],[`兒童椅`,`ji4 tung4 ji2`,`儿童椅`],[`留到`,`lau4 dou3`,`保留到`]],patterns:[[`時間＋有冇位？`,`把日期和时间放在前面，询问该时段能否订位。`,`夜晚七點有冇位？`],[`留到＋時間`,`“到”后面接保留座位的截止时间；“幾點”用来询问这个时间。`,`張枱可以留到幾點？`]],cultureNote:`卡位指相对而坐的卡座。订位后可复述日期、人数和时间；靠窗、卡位及儿童椅都需要向店员确认，不能只凭订位就认定已经安排。`,practicePrompt:`订周六晚三个人的座位。原定七点已满，接受六点半，询问靠窗座位，再报姓氏并复述订位信息。`}),t({id:`food-drink-bakery`,topicId:`food-drink`,level:2,minutes:13,title:`买面包与预订蛋糕`,description:`蛋糕份量、口味、写字与取货`,speakers:[`你`,`店员`],phrases:[[`唔該，我想訂個生日蛋糕。`,`m4 goi1 ngo5 soeng2 deng6 go3 saang1 jat6 daan6 gou1`,`您好，我想订一个生日蛋糕。`],[`幾多人食，想要咩口味？`,`gei2 do1 jan4 sik6 soeng2 jiu3 me1 hau2 mei6`,`几个人吃，想要什么口味？`],[`四個人食，想要水果蛋糕。`,`sei3 go3 jan4 sik6 soeng2 jiu3 seoi2 gwo2 daan6 gou1`,`四个人吃，想要水果蛋糕。`],[`呢款細蛋糕夠四個人食。`,`ni1 fun2 sai3 daan6 gou1 gau3 sei3 go3 jan4 sik6`,`这款小蛋糕够四个人吃。`],[`可唔可以寫生日快樂？`,`ho2 m4 ho2 ji5 se2 saang1 jat6 faai3 lok6`,`可以写生日快乐吗？`],[`可以，想幾時嚟攞？`,`ho2 ji5 soeng2 gei2 si4 lai4 lo2`,`可以，想什么时候来取？`],[`聽日下午五點，我帶張單嚟。`,`ting1 jat6 haa6 ng5 ng5 dim2 ngo5 daai3 zoeng1 daan1 lai4`,`明天下午五点，我带着单据来。`],[`好，幫你寫低，聽日見。`,`hou2 bong1 nei5 se2 dai1 ting1 jat6 gin3`,`好，帮你记下来了，明天见。`],[`呢個菠蘿包係咪啱啱出爐？`,`ni1 go3 bo1 lo4 baau1 hai6 mai6 ngaam1 ngaam1 ceot1 lou4`,`这个菠萝包是不是刚出炉的？`],[`唔該，兩個蛋撻，分開裝。`,`m4 goi1 loeng5 go3 daan6 taat1 fan1 hoi1 zong1`,`麻烦给我两个蛋挞，分开装。`],[`呢款麵包入面有冇果仁？`,`ni1 fun2 min6 baau1 jap6 min6 jau5 mou5 gwo2 jan4`,`这款面包里面有坚果吗？`],[`我嚟攞蛋糕，呢張係訂單。`,`ngo5 lai4 lo2 daan6 gou1 ni1 zoeng1 hai6 deng6 daan1`,`我来取蛋糕，这张是订单。`]],words:[[`生日蛋糕`,`saang1 jat6 daan6 gou1`,`生日蛋糕`],[`口味`,`hau2 mei6`,`口味`],[`水果`,`seoi2 gwo2`,`水果`],[`寫低`,`se2 dai1`,`记下来`],[`菠蘿包`,`bo1 lo4 baau1`,`菠萝包`],[`出爐`,`ceot1 lou4`,`出炉`],[`蛋撻`,`daan6 taat1`,`蛋挞`],[`分開裝`,`fan1 hoi1 zong1`,`分开包装`],[`果仁`,`gwo2 jan4`,`坚果`],[`訂單`,`deng6 daan1`,`订单`]],patterns:[[`夠＋人數＋食`,`“夠”说明食物的份量足够多少人吃。`,`呢款細蛋糕夠四個人食。`],[`動詞＋低`,`“低”接在“寫”等动作后，表示把结果留下来；“寫低”就是记下。`,`幫你寫低。`]],cultureNote:`菠萝包的名字来自表面外观，并不表示馅料一定有菠萝。蛋糕尺寸、写字和取货安排可在落单时问清楚，取货时出示店方提供的订单。`,practicePrompt:`为四位朋友订一个蛋糕，选口味、提出写字要求，并约好取货时间。再买两样面包，询问出炉时间或馅料。`}),t({id:`food-drink-cooking`,topicId:`food-drink`,level:2,minutes:14,title:`一起下厨做晚饭`,description:`分工、备料与烹调顺序`,speakers:[`阿欣`,`阿杰`],phrases:[[`今晚整番茄炒蛋，屋企仲有冇雞蛋？`,`gam1 maan5 zing2 faan1 ke2 caau2 daan2 uk1 kei2 zung6 jau5 mou5 gai1 daan2`,`今晚做番茄炒蛋，家里还有鸡蛋吗？`],[`有三隻，番茄就要落街買。`,`jau5 saam1 zek3 faan1 ke2 zau6 jiu3 lok6 gaai1 maai5`,`有三个，番茄要下楼去买。`],[`咁你買番茄，我先煮飯。`,`gam2 nei5 maai5 faan1 ke2 ngo5 sin1 zyu2 faan6`,`那你买番茄，我先煮饭。`],[`好，我買完返嚟幫你切番茄。`,`hou2 ngo5 maai5 jyun4 faan1 lai4 bong1 nei5 cit3 faan1 ke2`,`好，我买完回来帮你切番茄。`],[`唔該，返嚟仲要幫我洗菜。`,`m4 goi1 faan1 lai4 zung6 jiu3 bong1 ngo5 sai2 coi3`,`谢谢，回来还要帮我洗菜。`],[`我洗菜，你炒蛋，咁樣分工得唔得？`,`ngo5 sai2 coi3 nei5 caau2 daan2 gam2 joeng2 fan1 gung1 dak1 m4 dak1`,`我洗菜，你炒蛋，这样分工可以吗？`],[`得，啲蛋先炒好拎起，再炒番茄。`,`dak1 di1 daan2 sin1 caau2 hou2 ling1 hei2 zoi3 caau2 faan1 ke2`,`可以，鸡蛋先炒好盛出来，再炒番茄。`],[`最後放返啲蛋落去，一齊炒勻。`,`zeoi3 hau6 fong3 faan1 di1 daan2 lok6 heoi3 jat1 cai4 caau2 wan4`,`最后把鸡蛋放回去，一起炒匀。`],[`鹽喺邊？我想試味。`,`jim4 hai2 bin1 ngo5 soeng2 si3 mei6`,`盐在哪里？我想尝尝味道。`],[`味道夠喇，唔使再落鹽。`,`mei6 dou6 gau3 laa3 m4 sai2 zoi3 lok6 jim4`,`味道够了，不用再放盐。`],[`唔該，幫我將啲餸上碟。`,`m4 goi1 bong1 ngo5 zoeng1 di1 sung3 soeng5 dip6`,`麻烦帮我把菜装盘。`],[`我洗碗，你抹枱，得唔得？`,`ngo5 sai2 wun2 nei5 maat3 toi2 dak1 m4 dak1`,`我洗碗，你擦桌子，可以吗？`]],words:[[`番茄`,`faan1 ke2`,`番茄`],[`雞蛋`,`gai1 daan2`,`鸡蛋`],[`落街`,`lok6 gaai1`,`下楼外出`],[`煮飯`,`zyu2 faan6`,`煮饭；做饭`],[`洗菜`,`sai2 coi3`,`洗菜`],[`切`,`cit3`,`切`],[`炒勻`,`caau2 wan4`,`炒匀`],[`試味`,`si3 mei6`,`尝味道`],[`上碟`,`soeng5 dip6`,`装盘`],[`抹枱`,`maat3 toi2`,`擦桌子`]],patterns:[[`先＋動作，再＋動作`,`说明两个步骤的先后；也可以在结尾用“最後”补上最后一步。`,`先炒蛋，再炒番茄。`],[`放返＋物件＋落去`,`“返”表示放回原处，“落去”表示往容器里面放。`,`放返啲蛋落去。`]],cultureNote:`“整餸”是做菜，“煮飯”既可以指煮米饭，也可以泛指做饭。两个人一起下厨时，可分别讲清买菜、备料、煮食和收拾的分工。`,practicePrompt:`和朋友商量两菜一饭。分别安排买菜、洗菜和煮饭，再用“先、再、最後”说明一道你熟悉的菜的步骤。`}),t({id:`shopping-online-order`,topicId:`shopping`,level:3,minutes:15,title:`查询网购订单`,description:`发货进度、送货地址与漏发物品`,speakers:[`你`,`客服`],phrases:[[`你好，我想查吓張訂單送到邊。`,`nei5 hou2 ngo5 soeng2 caa4 haa5 zoeng1 deng6 daan1 sung3 dou3 bin1`,`你好，我想查一下订单送到哪里了。`],[`唔該，請提供訂單號碼。`,`m4 goi1 ceng2 tai4 gung1 deng6 daan1 hou6 maa5`,`麻烦提供订单号码。`],[`號碼係五三八六，尋日已經出貨。`,`hou6 maa5 hai6 ng5 saam1 baat3 luk6 cam4 jat6 ji5 ging1 ceot1 fo3`,`号码是五三八六，昨天已经发货了。`],[`我查到個包裹仲喺送貨途中。`,`ngo5 caa4 dou2 go3 baau1 gwo2 zung6 hai2 sung3 fo3 tou4 zung1`,`我查到包裹还在配送途中。`],[`聽日我唔喺屋企，可唔可以改送貨時間？`,`ting1 jat6 ngo5 m4 hai2 uk1 kei2 ho2 m4 ho2 ji5 goi2 sung3 fo3 si4 gaan3`,`明天我不在家，可以改配送时间吗？`],[`我幫你問吓送貨公司，再覆你。`,`ngo5 bong1 nei5 man6 haa5 sung3 fo3 gung1 si1 zoi3 fuk1 nei5`,`我帮你问一下配送公司，再回复你。`],[`好，唔該用訊息通知我。`,`hou2 m4 goi1 jung6 seon3 sik1 tung1 zi1 ngo5`,`好，麻烦用消息通知我。`],[`收到，確認咗安排就發訊息俾你。`,`sau1 dou2 kok3 jan6 zo2 on1 paai4 zau6 faat3 seon3 sik1 bei2 nei5`,`收到，确认安排后就发消息给你。`],[`送貨地址少咗個樓層，點樣改返？`,`sung3 fo3 dei6 zi2 siu2 zo2 go3 lau4 cang4 dim2 joeng2 goi2 faan1`,`配送地址漏了楼层，怎样改过来？`],[`個盒入面少咗條充電線。`,`go3 hap6 jap6 min6 siu2 zo2 tiu4 cung1 din6 sin3`,`盒子里少了一条充电线。`],[`我影咗張相，可以喺邊度傳俾你？`,`ngo5 jing2 zo2 zoeng1 soeng2 ho2 ji5 hai2 bin1 dou6 cyun4 bei2 nei5`,`我拍了照片，可以在哪里发给你？`],[`可唔可以俾個查詢編號我？`,`ho2 m4 ho2 ji5 bei2 go3 caa4 seon1 pin1 hou6 ngo5`,`可以给我一个查询编号吗？`]],words:[[`訂單號碼`,`deng6 daan1 hou6 maa5`,`订单号码`],[`出貨`,`ceot1 fo3`,`发货`],[`包裹`,`baau1 gwo2`,`包裹`],[`送貨途中`,`sung3 fo3 tou4 zung1`,`配送途中`],[`送貨公司`,`sung3 fo3 gung1 si1`,`配送公司`],[`通知`,`tung1 zi1`,`通知`],[`樓層`,`lau4 cang4`,`楼层`],[`充電線`,`cung1 din6 sin3`,`充电线`],[`傳`,`cyun4`,`传送`],[`查詢編號`,`caa4 seon1 pin1 hou6`,`查询编号`]],patterns:[[`確認咗＋事情＋就＋動作`,`“咗”表示前一件事完成，“就”带出随后会做的事。`,`確認咗安排就發訊息俾你。`],[`少咗＋物件`,`指出实际收到或填写的内容，比应有的内容少了什么。`,`個盒入面少咗條充電線。`]],cultureNote:`联系客服时，订单号码、缺少的物品和希望修改的安排可以分开说明。能否改送货时间或地址，需要等商户或送货公司核实回复。`,practicePrompt:`网购物品已发货，但你原定收货当天不在家。提供订单号码，询问更改时间的办法；再另练一次收到包裹后说明漏发配件。`}),t({id:`shopping-housewares`,topicId:`shopping`,level:2,minutes:13,title:`选收纳盒与家居用品`,description:`尺寸、材质、盖子与摆放空间`,speakers:[`你`,`店员`],phrases:[[`唔該，我想搵個收納盒。`,`m4 goi1 ngo5 soeng2 wan2 go3 sau1 naap6 hap6`,`您好，我想找一个收纳盒。`],[`想放啲咩，大概要幾大？`,`soeng2 fong3 di1 me1 daai6 koi3 jiu3 gei2 daai6`,`想放什么，大概要多大的？`],[`放冬天啲衫，要擺喺床下底。`,`fong3 dung1 tin1 di1 saam1 jiu3 baai2 hai2 cong4 haa6 dai2`,`放冬天的衣服，要放在床底下。`],[`呢款矮啲，你量咗床底個高度未？`,`ni1 fun2 ai2 di1 nei5 loeng4 zo2 cong4 dai2 go3 gou1 dou6 mei6`,`这款矮一些，你量过床底的高度了吗？`],[`量咗，只有廿厘米高，呢個幾高？`,`loeng4 zo2 zi2 jau5 jaa6 lei4 mai5 gou1 ni1 go3 gei2 gou1`,`量过了，只有二十厘米高，这个多高？`],[`連蓋十八厘米，係膠造嘅。`,`lin4 goi3 sap6 baat3 lei4 mai5 hai6 gaau1 zou6 ge3`,`连盖子十八厘米，是塑料做的。`],[`咁放得落，我要兩個連蓋嘅。`,`gam2 fong3 dak1 lok6 ngo5 jiu3 loeng5 go3 lin4 goi3 ge3`,`那能放得下，我要两个带盖的。`],[`好，我幫你拎兩個新嘅。`,`hou2 ngo5 bong1 nei5 ling1 loeng5 go3 san1 ge3`,`好，我帮你拿两个新的。`],[`呢個玻璃杯有冇細一個碼？`,`ni1 go3 bo1 lei1 bui1 jau5 mou5 sai3 jat1 go3 maa5`,`这个玻璃杯有没有小一号的？`],[`呢張凳係木造定膠造？`,`ni1 zoeng1 dang3 hai6 muk6 zou6 ding6 gaau1 zou6`,`这张凳子是木制还是塑料的？`],[`可唔可以俾我睇吓包裝上面嘅尺寸？`,`ho2 m4 ho2 ji5 bei2 ngo5 tai2 haa5 baau1 zong1 soeng6 min6 ge3 cek3 cyun3`,`可以让我看看包装上的尺寸吗？`],[`我個櫃唔夠深，有冇短啲嘅？`,`ngo5 go3 gwai6 m4 gau3 sam1 jau5 mou5 dyun2 di1 ge3`,`我的柜子不够深，有没有短一点的？`]],words:[[`收納盒`,`sau1 naap6 hap6`,`收纳盒`],[`床下底`,`cong4 haa6 dai2`,`床底下`],[`量`,`loeng4`,`测量`],[`高度`,`gou1 dou6`,`高度`],[`厘米`,`lei4 mai5`,`厘米`],[`連蓋`,`lin4 goi3`,`连同盖子；带盖`],[`膠造`,`gaau1 zou6`,`塑料制的`],[`玻璃杯`,`bo1 lei1 bui1`,`玻璃杯`],[`木造`,`muk6 zou6`,`木制的`],[`尺寸`,`cek3 cyun3`,`尺寸`]],patterns:[[`量咗＋物件＋未？`,`用“咗……未”询问测量这件事是否已经做过。`,`你量咗床底個高度未？`],[`動詞＋得落／唔落`,`说明空间能否容纳物件；“放得落”就是放得下。`,`咁放得落，我要兩個。`]],cultureNote:`选收纳用品时，“連蓋”可以说明尺寸包含盖子，也可以说明售价所含的配件。长、阔、高和单位最好一起核对，避免只看商品大小的称呼。`,practicePrompt:`你的床底高二十厘米，要买两个有盖的盒子。询问高度和材质，确认能放下；再替一个不够深的柜子找较短的盒子。`}),t({id:`shopping-phone-repair`,topicId:`shopping`,level:3,minutes:15,title:`手机维修前问清楚`,description:`故障、检查费、报价与资料保留`,speakers:[`你`,`店员`],phrases:[[`我部電話跌過，而家開唔到機。`,`ngo5 bou6 din6 waa2 dit3 gwo3 ji4 gaa1 hoi1 m4 dou2 gei1`,`我的手机摔过，现在开不了机。`],[`我先幫你檢查，睇吓邊度有問題。`,`ngo5 sin1 bong1 nei5 gim2 caa4 tai2 haa5 bin1 dou6 jau5 man6 tai4`,`我先帮你检查，看看哪里有问题。`],[`檢查收唔收費，會唔會先報價？`,`gim2 caa4 sau1 m4 sau1 fai3 wui5 m4 wui5 sin1 bou3 gaa3`,`检查收费吗，会先报价吗？`],[`檢查費五十蚊，整之前會先報價。`,`gim2 caa4 fai3 ng5 sap6 man1 zing2 zi1 cin4 wui5 sin1 bou3 gaa3`,`检查费五十元，维修之前会先报价。`],[`入面有啲相未備份，我想保留啲資料。`,`jap6 min6 jau5 di1 soeng2 mei6 bei6 fan6 ngo5 soeng2 bou2 lau4 di1 zi1 liu6`,`里面有些照片还没备份，我想保留资料。`],[`我記低先，處理資料之前會同你確認。`,`ngo5 gei3 dai1 sin1 cyu2 lei5 zi1 liu6 zi1 cin4 wui5 tung4 nei5 kok3 jan6`,`我先记下来，处理资料之前会和你确认。`],[`如果要清除資料，唔好住，先聯絡我。`,`jyu4 gwo2 jiu3 cing1 ceoi4 zi1 liu6 m4 hou2 zyu6 sin1 lyun4 lok3 ngo5`,`如果要清除资料，先别操作，先联系我。`],[`明白，報價同處理方法都會先問你。`,`ming4 baak6 bou3 gaa3 tung4 cyu2 lei5 fong1 faat3 dou1 wui5 sin1 man6 nei5`,`明白，报价和处理办法都会先问你。`],[`如果只係換電池，要整幾耐？`,`jyu4 gwo2 zi2 hai6 wun6 din6 ci4 jiu3 zing2 gei2 noi6`,`如果只是换电池，要修多久？`],[`呢個價錢包唔包零件同人工？`,`ni1 go3 gaa3 cin2 baau1 m4 baau1 ling4 gin6 tung4 jan4 gung1`,`这个价格包括零件和人工吗？`],[`我想要張維修單，寫低部機嘅情況。`,`ngo5 soeng2 jiu3 zoeng1 wai4 sau1 daan1 se2 dai1 bou6 gei1 ge3 cing4 fong3`,`我想要一张维修单，写下手机的情况。`],[`整好之後，唔該打電話通知我。`,`zing2 hou2 zi1 hau6 m4 goi1 daa2 din6 waa2 tung1 zi1 ngo5`,`修好之后，麻烦打电话通知我。`]],words:[[`開唔到機`,`hoi1 m4 dou2 gei1`,`开不了机`],[`檢查費`,`gim2 caa4 fai3`,`检查费`],[`報價`,`bou3 gaa3`,`报价`],[`備份`,`bei6 fan6`,`备份`],[`保留`,`bou2 lau4`,`保留`],[`資料`,`zi1 liu6`,`资料`],[`清除`,`cing1 ceoi4`,`清除`],[`電池`,`din6 ci4`,`电池`],[`零件`,`ling4 gin6`,`零件`],[`維修單`,`wai4 sau1 daan1`,`维修单`]],patterns:[[`動作＋之前，先＋動作`,`用“之前”说明先后，也可用来要求先确认再操作。`,`處理資料之前，先聯絡我。`],[`唔好住`,`“住”表示暂缓某个动作；可以接着说明要先做什么。`,`唔好住，先聯絡我。`]],cultureNote:`“整電話”就是修手机。检查费、维修报价和资料处理是不同问题，可逐项询问。费用和资料能否保留，要等店方检查后确认，对话里的检查费只是例子。`,practicePrompt:`手机摔落后不能开机，里面有未备份的照片。说明故障，问检查费和报价，再明确提出任何清除资料的操作都要先联系你。`}),t({id:`friends-cinema`,topicId:`friends`,level:2,minutes:13,title:`约朋友看电影`,description:`电影类型、场次、座位与取票`,speakers:[`阿欣`,`阿杰`],phrases:[[`今晚去睇戲，你想睇邊套？`,`gam1 maan5 heoi3 tai2 hei3 nei5 soeng2 tai2 bin1 tou3`,`今晚去看电影，你想看哪一部？`],[`我想睇喜劇，唔想睇恐怖片。`,`ngo5 soeng2 tai2 hei2 kek6 m4 soeng2 tai2 hung2 bou3 pin2`,`我想看喜剧，不想看恐怖片。`],[`咁呢套喜劇點呀？有六點半嗰場。`,`gam2 ni1 tou3 hei2 kek6 dim2 aa3 jau5 luk6 dim2 bun3 go2 coeng4`,`那这部喜剧怎么样？有六点半那一场。`],[`可以呀，邊間戲院？`,`ho2 ji5 aa3 bin1 gaan1 hei3 jyun2`,`可以啊，哪家电影院？`],[`地鐵站隔籬嗰間，我哋坐中間好唔好？`,`dei6 tit3 zaam6 gaak3 lei4 go2 gaan1 ngo5 dei6 co5 zung1 gaan1 hou2 m4 hou2`,`地铁站旁边那家，我们坐中间好吗？`],[`好呀，不過我想坐近通道。`,`hou2 aa3 bat1 gwo3 ngo5 soeng2 co5 gan6 tung1 dou6`,`好啊，不过我想坐靠近过道的位置。`],[`仲有兩個連位，我而家買飛。`,`zung6 jau5 loeng5 go3 lin4 wai2 ngo5 ji4 gaa1 maai5 fei1`,`还有两个相连的座位，我现在买票。`],[`唔該晒，我哋六點喺戲院門口等。`,`m4 goi1 saai3 ngo5 dei6 luk6 dim2 hai2 hei3 jyun2 mun4 hau2 dang2`,`谢谢，我们六点在电影院门口等。`],[`呢套戲有冇中文字幕？`,`ni1 tou3 hei3 jau5 mou5 zung1 man4 zi6 mou6`,`这部电影有中文字幕吗？`],[`套戲幾點散場？`,`tou3 hei3 gei2 dim2 saan3 coeng4`,`电影几点散场？`],[`我買咗飛，要唔要去櫃位攞？`,`ngo5 maai5 zo2 fei1 jiu3 m4 jiu3 heoi3 gwai6 wai2 lo2`,`我买了票，要去柜台取吗？`],[`睇完我哋先去食飯。`,`tai2 jyun4 ngo5 dei6 sin1 heoi3 sik6 faan6`,`我们看完再去吃饭。`]],words:[[`喜劇`,`hei2 kek6`,`喜剧`],[`恐怖片`,`hung2 bou3 pin2`,`恐怖片`],[`戲院`,`hei3 jyun2`,`电影院`],[`隔籬`,`gaak3 lei4`,`旁边`],[`中間`,`zung1 gaan1`,`中间`],[`通道`,`tung1 dou6`,`过道；通道`],[`連位`,`lin4 wai2`,`相连的座位`],[`買飛`,`maai5 fei1`,`买票`],[`字幕`,`zi6 mou6`,`字幕`],[`散場`,`saan3 coeng4`,`散场`]],patterns:[[`邊＋量詞＋名詞？`,`选择量词来问哪一个：“套”用于电影，“間”用于电影院。`,`你想睇邊套？邊間戲院？`],[`動詞＋完＋先……`,`先完成一件事，然后再做后面的事。`,`睇完我哋先去食飯。`]],cultureNote:`“套戲”可以指一部电影，“嗰場”指某一场次。“飛”是票的口语说法；买票时可以同时核对场次、语言、字幕和座位。`,practicePrompt:`和朋友选一部电影。说明自己不想看的类型，商量场次和靠通道的连位，再约好见面的时间与地点。`}),t({id:`friends-badminton`,topicId:`friends`,level:2,minutes:14,title:`去体育馆打羽毛球`,description:`订场、借球具、热身与轮流练习`,speakers:[`阿欣`,`阿杰`],phrases:[[`星期日打羽毛球，你訂咗場未？`,`sing1 kei4 jat6 daa2 jyu5 mou4 kau4 nei5 deng6 zo2 coeng4 mei6`,`星期天打羽毛球，你订场了吗？`],[`未呀，我今晚去訂，三點得唔得？`,`mei6 aa3 ngo5 gam1 maan5 heoi3 deng6 saam1 dim2 dak1 m4 dak1`,`还没，我今晚去订，三点可以吗？`],[`得，訂體育館，三點到四點。`,`dak1 deng6 tai2 juk6 gun2 saam1 dim2 dou3 sei3 dim2`,`可以，订体育馆，三点到四点。`],[`好，不過我冇球具，可唔可以借俾我？`,`hou2 bat1 gwo3 ngo5 mou5 kau4 geoi6 ho2 m4 ho2 ji5 ze3 bei2 ngo5`,`好，不过我没有球具，可以借给我吗？`],[`可以，我有多一套，你帶水同毛巾就得。`,`ho2 ji5 ngo5 jau5 do1 jat1 tou3 nei5 daai3 seoi2 tung4 mou4 gan1 zau6 dak1`,`可以，我多一套，你带水和毛巾就行。`],[`唔該晒，我好耐冇打，想先練吓。`,`m4 goi1 saai3 ngo5 hou2 noi6 mou5 daa2 soeng2 sin1 lin6 haa5`,`谢谢，我很久没打了，想先练一下。`],[`冇問題，我哋先熱身，再練發球。`,`mou5 man6 tai4 ngo5 dei6 sin1 jit6 san1 zoi3 lin6 faat3 kau4`,`没问题，我们先热身，再练发球。`],[`好呀，練一陣再計分。`,`hou2 aa3 lin6 jat1 zan6 zoi3 gai3 fan1`,`好啊，练一会儿再计分。`],[`今次輪到邊個發球？`,`gam1 ci3 leon4 dou3 bin1 go3 faat3 kau4`,`这次轮到谁发球？`],[`個波出界喇，再嚟一次。`,`go3 bo1 ceot1 gaai3 laa3 zoi3 lai4 jat1 ci3`,`球出界了，再来一次。`],[`我有啲攰，休息五分鐘先。`,`ngo5 jau5 di1 gui6 jau1 sik1 ng5 fan1 zung1 sin1`,`我有点累，先休息五分钟。`],[`打完去更衣室換衫。`,`daa2 jyun4 heoi3 gang1 ji1 sat1 wun6 saam1`,`打完去更衣室换衣服。`]],words:[[`羽毛球`,`jyu5 mou4 kau4`,`羽毛球`],[`訂咗場`,`deng6 zo2 coeng4`,`已预订场地`],[`體育館`,`tai2 juk6 gun2`,`体育馆`],[`球具`,`kau4 geoi6`,`球类运动器材`],[`毛巾`,`mou4 gan1`,`毛巾`],[`熱身`,`jit6 san1`,`热身`],[`發球`,`faat3 kau4`,`发球`],[`計分`,`gai3 fan1`,`计分`],[`出界`,`ceot1 gaai3`,`出界`],[`更衣室`,`gang1 ji1 sat1`,`更衣室`]],patterns:[[`好耐冇＋動作`,`说明上一次做某事已经是很久以前。`,`我好耐冇打羽毛球。`],[`輪到＋人＋動作`,`说明轮流做事时由谁来做下一次。`,`今次輪到邊個發球？`]],cultureNote:`“訂場”指预订一段时间使用场地，不等于同时订了球具。约好时间后，可再确认各自带什么，以及在哪里等；球馆的借用安排需要另问。`,practicePrompt:`约朋友周日打球，确认订场时间，并说明自己需要借球具。练习时询问谁发球，再提出休息几分钟。`}),t({id:`friends-pets`,topicId:`friends`,level:2,minutes:13,title:`去朋友家看新来的猫`,description:`宠物名字、性格与日常照顾`,speakers:[`阿欣`,`阿杰`],phrases:[[`聽講你養咗隻貓，叫咩名呀？`,`teng1 gong2 nei5 joeng5 zo2 zek3 maau1 giu3 me1 meng2 aa3`,`听说你养了一只猫，叫什么名字啊？`],[`佢叫豆豆，啱啱嚟咗一個星期。`,`keoi5 giu3 dau6 dau6 ngaam1 ngaam1 lai4 zo2 jat1 go3 sing1 kei4`,`它叫豆豆，刚来一个星期。`],[`豆豆好得意，我可唔可以摸吓佢？`,`dau6 dau6 hou2 dak1 ji3 ngo5 ho2 m4 ho2 ji5 mo2 haa5 keoi5`,`豆豆很可爱，我可以摸摸它吗？`],[`佢有啲怕醜，等佢自己行過嚟先。`,`keoi5 jau5 di1 paa3 cau2 dang2 keoi5 zi6 gei2 haang4 gwo3 lai4 sin1`,`它有点怕生，先等它自己走过来。`],[`好呀，你平時幾點餵佢食嘢？`,`hou2 aa3 nei5 ping4 si4 gei2 dim2 wai3 keoi5 sik6 je5`,`好啊，你平时几点喂它吃东西？`],[`我朝早同夜晚餵，每次嘅份量都寫低咗。`,`ngo5 ziu1 zou2 tung4 je6 maan5 wai3 mui5 ci3 ge3 fan6 loeng6 dou1 se2 dai1 zo2`,`我早晚喂，每次的份量都写下来了。`],[`咁我幫你換水，個水碗喺邊？`,`gam2 ngo5 bong1 nei5 wun6 seoi2 go3 seoi2 wun2 hai2 bin1`,`那我帮你换水，水碗在哪里？`],[`喺廚房門口，多謝你幫手。`,`hai2 cyu4 fong2 mun4 hau2 do1 ze6 nei5 bong1 sau2`,`在厨房门口，谢谢你帮忙。`],[`豆豆平時鍾意玩啲咩玩具？`,`dau6 dau6 ping4 si4 zung1 ji3 waan2 di1 me1 waan2 geoi6`,`豆豆平时喜欢玩什么玩具？`],[`貓砂放喺邊度，我幫你拎過去。`,`maau1 saa1 fong3 hai2 bin1 dou6 ngo5 bong1 nei5 ling1 gwo3 heoi3`,`猫砂放在哪里，我帮你拿过去。`],[`我唔係好識照顧貓，你寫低俾我睇吖。`,`ngo5 m4 hai6 hou2 sik1 ziu3 gu3 maau1 nei5 se2 dai1 bei2 ngo5 tai2 aa1`,`我不太会照顾猫，你写下来给我看吧。`],[`出門口之前，幫我睇吓閂好門未。`,`ceot1 mun4 hau2 zi1 cin4 bong1 ngo5 tai2 haa5 saan1 hou2 mun4 mei6`,`出门前，帮我看看门关好了没有。`]],words:[[`養`,`joeng5`,`养`],[`得意`,`dak1 ji3`,`可爱`],[`摸`,`mo2`,`抚摸`],[`怕醜`,`paa3 cau2`,`怕生`],[`餵`,`wai3`,`喂`],[`份量`,`fan6 loeng6`,`份量`],[`水碗`,`seoi2 wun2`,`水碗`],[`玩具`,`waan2 geoi6`,`玩具`],[`貓砂`,`maau1 saa1`,`猫砂`],[`照顧`,`ziu3 gu3`,`照顾`]],patterns:[[`等＋人或動物＋動作＋先`,`先等另一方做某个动作，再进行接下来的事。`,`等佢自己行過嚟先。`],[`照住＋內容＋做`,`说明按照某个说明或记录去做；“住”接在“照”后面。`,`照住張紙嘅份量餵就得。`]],cultureNote:`“得意”形容宠物时常指可爱。到朋友家接触宠物前可先问主人；临时帮忙照顾时，可请主人把喂食、换水和出门关门的安排写下来。`,practicePrompt:`朋友家有只刚来的猫。先问名字和性格，征得同意后再接近；提出帮忙换水，并请朋友写清需要你代做的事情。`})],m=[t({id:`getting-around-ferry`,topicId:`getting-around`,level:2,minutes:13,title:`坐渡轮`,description:`码头、船期与上船安排`,speakers:[`乘客`,`碼頭職員`],phrases:[[`唔該，去長洲嘅渡輪喺邊個碼頭搭？`,`m4 goi1, heoi3 coeng4 zau1 ge3 dou6 leon4 hai2 bin1 go3 maa5 tau4 daap3?`,`请问，去长洲的渡轮在哪个码头乘坐？`,`对话里的开船时间为练习示例。`],[`前面嗰個碼頭，我指畀你睇。`,`cin4 min6 go2 go3 maa5 tau4, ngo5 zi2 bei2 nei5 tai2.`,`前面那个码头，我指给你看。`],[`下一班船幾點開？`,`haa6 jat1 baan1 syun4 gei2 dim2 hoi1?`,`下一班船几点开？`],[`下晝兩點半，時間表喺門口。`,`haa6 zau3 loeng5 dim2 bun3, si4 gaan3 biu2 hai2 mun4 hau2.`,`下午两点半，时刻表在门口。`],[`船程大概要幾耐？`,`syun4 cing4 daai6 koi3 jiu3 gei2 noi6?`,`航程大概需要多久？`],[`大概半個鐘，入閘之後喺候船室等。`,`daai6 koi3 bun3 go3 zung1, jap6 zaap6 zi1 hau6 hai2 hau6 syun4 sat1 dang2.`,`大约半小时，进闸后在候船室等候。`],[`而家可以上船未？`,`ji4 gaa1 ho2 ji5 soeng5 syun4 mei6?`,`现在可以上船了吗？`],[`未得，等職員通知先排隊上船。`,`mei6 dak1, dang2 zik1 jyun4 tung1 zi1 sin1 paai4 deoi6 soeng5 syun4.`,`还不行，等工作人员通知再排队上船。`],[`我想買兩張單程飛。`,`ngo5 soeng2 maai5 loeng5 zoeng1 daan1 cing4 fei1.`,`我想买两张单程票。`],[`買來回飛，係咪一定要即日回程？`,`maai5 loi4 wui4 fei1, hai6 mai6 jat1 ding6 jiu3 zik1 jat6 wui4 cing4?`,`买往返票，是不是一定要当天返程？`],[`落船之後喺邊度集合？`,`lok6 syun4 zi1 hau6 hai2 bin1 dou6 zaap6 hap6?`,`下船后在哪里集合？`],[`尾班船嘅時間可唔可以寫低畀我？`,`mei5 baan1 syun4 ge3 si4 gaan3 ho2 m4 ho2 ji5 se2 dai1 bei2 ngo5?`,`可以把末班船的时间写下来给我吗？`]],words:[[`渡輪`,`dou6 leon4`,`渡轮`],[`碼頭`,`maa5 tau4`,`码头`],[`下一班`,`haa6 jat1 baan1`,`下一班`],[`時間表`,`si4 gaan3 biu2`,`时刻表`],[`船程`,`syun4 cing4`,`航程`],[`半個鐘`,`bun3 go3 zung1`,`半小时`],[`候船室`,`hau6 syun4 sat1`,`候船室`],[`上船`,`soeng5 syun4`,`上船`],[`單程飛`,`daan1 cing4 fei1`,`单程票`],[`尾班船`,`mei5 baan1 syun4`,`末班船`]],patterns:[[`下一班……幾點開？`,`用“班”数固定班次；“开”表示发车或开船。`,`下一班船幾點開？`],[`等……先……`,`先等前一件事发生，再做后一件事。`,`等職員通知先排隊上船。`]],cultureNote:`“飞”在口语里可以指车票、船票或门票。“尾班船”是当天最后一班船，问回程时可直接用这个词；具体班次向码头职员确认。`,practicePrompt:`你和朋友准备乘船出游。问清码头、下一班开船时间和船程，买两张单程票，再询问回程末班船的时间。`}),t({id:`getting-around-accessible-route`,topicId:`getting-around`,level:2,minutes:13,title:`找电梯与无台阶出口`,description:`电梯出口、斜坡与无台阶路线`,speakers:[`乘客`,`車站職員`],phrases:[[`我推住輪椅，邊個出口有升降機？`,`ngo5 teoi1 zyu6 leon4 ji2, bin1 go3 ceot1 hau2 jau5 sing1 gong3 gei1?`,`我推着轮椅，哪个出口有电梯？`],[`東面出口有，我帶你過去。`,`dung1 min6 ceot1 hau2 jau5, ngo5 daai3 nei5 gwo3 heoi3.`,`东面的出口有，我带你过去。`],[`由呢度去出口，使唔使行樓梯？`,`jau4 ni1 dou6 heoi3 ceot1 hau2, sai2 m4 sai2 haang4 lau4 tai1?`,`从这里到出口，需要走楼梯吗？`],[`唔使，跟住呢條斜路行就得。`,`m4 sai2, gan1 zyu6 ni1 tiu4 ce4 lou6 haang4 zau6 dak1.`,`不用，沿着这条斜坡走就行。`],[`部升降機係咪直接到地面？`,`bou6 sing1 gong3 gei1 hai6 mai6 zik6 zip3 dou3 dei6 min6?`,`这部电梯是不是直接到地面？`],[`係，出咗升降機就見到巴士站。`,`hai6, ceot1 zo2 sing1 gong3 gei1 zau6 gin3 dou2 baa1 si2 zaam6.`,`是的，出了电梯就能看到公交车站。`],[`如果部機壞咗，仲有冇第二條路？`,`jyu4 gwo2 bou6 gei1 waai6 zo2, zung6 jau5 mou5 dai6 ji6 tiu4 lou6?`,`如果电梯坏了，还有别的路线吗？`],[`你可以搵我哋，我哋幫你查其他出口。`,`nei5 ho2 ji5 wan2 ngo5 dei6, ngo5 dei6 bong1 nei5 caa4 kei4 taa1 ceot1 hau2.`,`你可以找我们，我们帮你查其他出口。`],[`我想搵一條唔使上落樓梯嘅路。`,`ngo5 soeng2 wan2 jat1 tiu4 m4 sai2 soeng5 lok6 lau4 tai1 ge3 lou6.`,`我想找一条不用上下楼梯的路。`],[`個入口夠唔夠闊？`,`go3 jap6 hau2 gau3 m4 gau3 fut3?`,`入口够宽吗？`],[`唔該，幫我按住個開門掣。`,`m4 goi1, bong1 ngo5 on3 zyu6 go3 hoi1 mun4 zai3.`,`麻烦帮我按住开门按钮。`],[`可唔可以喺地圖上面指畀我睇？`,`ho2 m4 ho2 ji5 hai2 dei6 tou4 soeng6 min6 zi2 bei2 ngo5 tai2?`,`可以在地图上指给我看吗？`]],words:[[`推住`,`teoi1 zyu6`,`推着`],[`輪椅`,`leon4 ji2`,`轮椅`],[`升降機`,`sing1 gong3 gei1`,`电梯`],[`東面`,`dung1 min6`,`东面`],[`樓梯`,`lau4 tai1`,`楼梯`],[`斜路`,`ce4 lou6`,`斜坡`],[`直接`,`zik6 zip3`,`直接`],[`地面`,`dei6 min6`,`地面`],[`闊`,`fut3`,`宽`],[`開門掣`,`hoi1 mun4 zai3`,`开门按钮`]],patterns:[[`由……去……，使唔使……？`,`先说起点和终点，再问途中是否需要某个动作。`,`由呢度去出口，使唔使行樓梯？`],[`出咗……就……`,`说明离开某处后紧接着能看到或做到什么。`,`出咗升降機就見到巴士站。`]],cultureNote:`香港常说“升降机”，电梯按钮叫“掣”。询问路线时，说清楚需要无台阶、斜坡或电梯，职员便能按实际出口安排查找路线。`,practicePrompt:`你推着轮椅去车站附近的巴士站。向职员询问不用走楼梯的出口，请对方在地图上指出路线，并问电梯停用时找谁帮忙。`}),t({id:`getting-around-rail-ticket`,topicId:`getting-around`,level:2,minutes:14,title:`买火车票`,description:`车次、座位与上车月台`,speakers:[`旅客`,`售票員`],phrases:[[`唔該，我想買聽日去廣州嘅火車票。`,`m4 goi1, ngo5 soeng2 maai5 ting1 jat6 heoi3 gwong2 zau1 ge3 fo2 ce1 piu3.`,`你好，我想买明天去广州的火车票。`],[`你想朝早定下晝出發？`,`nei5 soeng2 ziu1 zou2 ding6 haa6 zau3 ceot1 faat3?`,`你想上午还是下午出发？`],[`朝早，想買兩個連住嘅位。`,`ziu1 zou2, soeng2 maai5 loeng5 go3 lin4 zyu6 ge3 wai2.`,`上午，想买两个挨在一起的座位。`],[`我幫你查吓邊班車仲有連位。`,`ngo5 bong1 nei5 caa4 haa5 bin1 baan1 ce1 zung6 jau5 lin4 wai2.`,`我帮你查查哪个车次还有相邻座位。`],[`買完飛之後，喺邊度睇月台號碼？`,`maai5 jyun4 fei1 zi1 hau6, hai2 bin1 dou6 tai2 jyut6 toi4 hou6 maa5?`,`买票后，在哪里看站台号码？`],[`睇大堂個電子屏幕，上面有車次同月台。`,`tai2 daai6 tong4 go3 din6 zi2 ping4 mok6, soeng6 min6 jau5 ce1 ci3 tung4 jyut6 toi4.`,`看大厅的电子屏幕，上面有车次和站台。`],[`我攞住個大喼，要預多啲時間嗎？`,`ngo5 lo2 zyu6 go3 daai6 gip1, jiu3 jyu6 do1 di1 si4 gaan3 maa3?`,`我带着一个大行李箱，需要多预留一点时间吗？`],[`要呀，先睇清楚入閘時間，唔好等到最後先入。`,`jiu3 aa3, sin1 tai2 cing1 co2 jap6 zaap6 si4 gaan3, m4 hou2 dang2 dou3 zeoi3 hau6 sin1 jap6.`,`需要，先看清进闸时间，不要等到最后才进去。`],[`我想揀靠窗嘅位。`,`ngo5 soeng2 gaan2 kaau3 coeng1 ge3 wai2.`,`我想选靠窗的座位。`],[`如果改車次，要點樣辦？`,`jyu4 gwo2 goi2 ce1 ci3, jiu3 dim2 joeng6 baan6?`,`如果更改车次，要怎么办理？`],[`車廂號碼喺張飛邊度？`,`ce1 soeng1 hou6 maa5 hai2 zoeng1 fei1 bin1 dou6?`,`车厢号码在车票的哪里？`],[`呢班車中途要唔要轉車？`,`ni1 baan1 ce1 zung1 tou4 jiu3 m4 jiu3 zyun3 ce1?`,`这班车途中需要换乘吗？`]],words:[[`火車票`,`fo2 ce1 piu3`,`火车票`],[`出發`,`ceot1 faat3`,`出发`],[`連位`,`lin4 wai2`,`相邻座位`],[`月台`,`jyut6 toi4`,`站台`],[`電子屏幕`,`din6 zi2 ping4 mok6`,`电子屏幕`],[`車次`,`ce1 ci3`,`车次`],[`喼`,`gip1`,`行李箱`],[`預`,`jyu6`,`预留`],[`靠窗`,`kaau3 coeng1`,`靠窗`],[`車廂`,`ce1 soeng1`,`车厢`]],patterns:[[`朝早定下晝？`,`“定”在选择问句中连接两个选项。`,`你想朝早定下晝出發？`],[`……完……之後，喺邊度……？`,`以已完成的步骤为起点，询问下一步在哪里办。`,`買完飛之後，喺邊度睇月台號碼？`]],cultureNote:`“连位”指相邻的座位，“靠窗”与“靠走廊”说明座位偏好。售票时可以先讲日期、目的地和人数，再请职员查班次与可选座位。`,practicePrompt:`替你和朋友购买明天上午的火车票，要求相邻座位，其中一个靠窗。再问如何查看车厢、月台和入闸时间。`}),t({id:`home-moving`,topicId:`home`,level:2,minutes:14,title:`搬家当天`,description:`纸箱标签、易碎物与家具位置`,speakers:[`住客`,`搬屋師傅`],phrases:[[`師傅，呢幾箱係廚房嘢，唔該搬入廚房。`,`si1 fu6, ni1 gei2 soeng1 hai6 cyu4 fong2 je5, m4 goi1 bun1 jap6 cyu4 fong2.`,`师傅，这几箱是厨房用品，麻烦搬进厨房。`],[`好，箱面有冇寫房名？`,`hou2, soeng1 min6 jau5 mou5 se2 fong2 meng2?`,`好的，箱子表面有没有写房间名称？`],[`有，紅色標籤係廚房，藍色係睡房。`,`jau5, hung4 sik1 biu1 cim1 hai6 cyu4 fong2, laam4 sik1 hai6 seoi6 fong2.`,`有，红色标签是厨房，蓝色是卧室。`],[`收到，我哋照標籤分開放。`,`sau1 dou2, ngo5 dei6 ziu3 biu1 cim1 fan1 hoi1 fong3.`,`明白，我们按标签分开放。`],[`呢箱有玻璃杯，可唔可以放喺上面？`,`ni1 soeng1 jau5 bo1 lei1 bui1, ho2 m4 ho2 ji5 fong3 hai2 soeng6 min6?`,`这箱有玻璃杯，可以放在上面吗？`],[`可以，我會輕手啲，唔放重嘢喺上面。`,`ho2 ji5, ngo5 wui5 heng1 sau2 di1, m4 fong3 cung5 je5 hai2 soeng6 min6.`,`可以，我会轻一点拿，不在上面放重物。`],[`張梳化想放窗邊，個櫃就放門口左邊。`,`zoeng1 so1 faa2 soeng2 fong3 coeng1 bin1, go3 gwai6 zau6 fong3 mun4 hau2 zo2 bin1.`,`沙发想放在窗边，柜子就放在门口左边。`],[`好，放好之後你睇吓位置啱唔啱。`,`hou2, fong3 hou2 zi1 hau6 nei5 tai2 haa5 wai6 zi3 ngaam1 m4 ngaam1.`,`好的，放好后你看看位置对不对。`],[`呢啲係易碎物品，唔好倒轉放。`,`ni1 di1 hai6 ji6 seoi3 mat6 ban2, m4 hou2 dou3 zyun3 fong3.`,`这些是易碎物品，不要倒着放。`],[`張床要唔要拆開先搬？`,`zoeng1 cong4 jiu3 m4 jiu3 caak3 hoi1 sin1 bun1?`,`床需要拆开再搬吗？`],[`呢個箱我自己拎，入面有文件。`,`ni1 go3 soeng1 ngo5 zi6 gei2 ling1, jap6 min6 jau5 man4 gin6.`,`这个箱子我自己拿，里面有文件。`],[`唔該幫我點吓，總共有幾多箱。`,`m4 goi1 bong1 ngo5 dim2 haa5, zung2 gung6 jau5 gei2 do1 soeng1.`,`麻烦帮我数一下，一共有多少箱。`]],words:[[`箱面`,`soeng1 min6`,`箱子表面`],[`廚房`,`cyu4 fong2`,`厨房`],[`標籤`,`biu1 cim1`,`标签`],[`睡房`,`seoi6 fong2`,`卧室`],[`分開`,`fan1 hoi1`,`分开`],[`玻璃杯`,`bo1 lei1 bui1`,`玻璃杯`],[`輕手`,`heng1 sau2`,`动作轻`],[`梳化`,`so1 faa2`,`沙发`],[`易碎物品`,`ji6 seoi3 mat6 ban2`,`易碎物品`],[`倒轉`,`dou3 zyun3`,`倒过来`]],patterns:[[`照……＋動作`,`“照”表示按照某个标记或安排去做。`,`我哋照標籤分開放。`],[`唔放……喺……`,`用“唔”说明不放某物的位置；请对方避免这样做时也可以说“唔好放”。`,`唔放重嘢喺上面。`]],cultureNote:`“搬屋”是搬家，“梳化”是沙发。箱子上写房名、贴颜色标签后，和搬运师傅确认每种颜色对应的房间，省得到新家后逐箱重找。`,practicePrompt:`你把搬家纸箱分成厨房、卧室两类。向师傅解释标签，提醒一箱玻璃用品要轻放，并说清沙发和柜子的位置。`}),t({id:`home-flatmates`,topicId:`home`,level:3,minutes:15,title:`和室友商量访客安排`,description:`访客、安静时段与共用空间`,speakers:[`室友阿晴`,`室友阿健`],phrases:[[`阿健，我星期六想請兩個朋友嚟食飯，方唔方便？`,`aa3 gin6, ngo5 sing1 kei4 luk6 soeng2 cing2 loeng5 go3 pang4 jau5 lai4 sik6 faan6, fong1 m4 fong1 bin6?`,`阿健，我周六想请两个朋友来吃饭，方便吗？`],[`幾點呀？我嗰晚要喺房開網上會議。`,`gei2 dim2 aa3? ngo5 go2 maan5 jiu3 hai2 fong2 hoi1 mong5 soeng6 wui6 ji5.`,`几点？我那晚要在房间开线上会议。`],[`七點左右，我哋會喺客廳坐。`,`cat1 dim2 zo2 jau6, ngo5 dei6 wui5 hai2 haak3 teng1 co5.`,`七点左右，我们会在客厅坐。`],[`咁可唔可以八點到九點嗰陣細聲啲？`,`gam2 ho2 m4 ho2 ji5 baat3 dim2 dou3 gau2 dim2 go2 zan6 sai3 seng1 di1?`,`那八点到九点这段时间可以小声一点吗？`],[`可以，你開會之前提我一聲就得。`,`ho2 ji5, nei5 hoi1 wui6 zi1 cin4 tai4 ngo5 jat1 seng1 zau6 dak1.`,`可以，你开会前提醒我一声就行。`],[`唔該晒。你哋食完飯，會唔會即晚洗碗碟？`,`m4 goi1 saai3. nei5 dei6 sik6 jyun4 faan6, wui5 m4 wui5 zik1 maan5 sai2 wun2 dip6?`,`谢谢。你们吃完饭后，会当晚洗碗碟吗？`],[`會呀，我會執返好個廚房，唔留嘢喺枱面。`,`wui5 aa3, ngo5 wui5 zap1 faan1 hou2 go3 cyu4 fong2, m4 lau4 je5 hai2 toi2 min6.`,`会的，我会把厨房收拾好，不在桌面留东西。`],[`咁就冇問題，下次有朋友嚟都提早講聲啦。`,`gam2 zau6 mou5 man6 tai4, haa6 ci3 jau5 pang4 jau5 lai4 dou1 tai4 zou2 gong2 seng1 laa1.`,`那就没问题，下次有朋友来也提前说一声吧。`],[`我聽日要早起，今晚想早啲瞓。`,`ngo5 ting1 jat6 jiu3 zou2 hei2, gam1 maan5 soeng2 zou2 di1 fan3.`,`我明天要早起，今晚想早点睡。`],[`雪櫃上層留返畀你用。`,`syut3 gwai6 soeng6 cang4 lau4 faan1 bei2 nei5 jung6.`,`冰箱上层留给你用。`],[`洗衣機你用完未？我有機衫想洗。`,`sai2 ji1 gei1 nei5 jung6 jyun4 mei6? ngo5 jau5 gei1 saam1 soeng2 sai2.`,`洗衣机你用完了吗？我有一机衣服想洗。`],[`如果要留朋友過夜，我哋先商量好。`,`jyu4 gwo2 jiu3 lau4 pang4 jau5 gwo3 je6, ngo5 dei6 sin1 soeng1 loeng4 hou2.`,`如果要留朋友过夜，我们先商量好。`]],words:[[`客廳`,`haak3 teng1`,`客厅`],[`網上會議`,`mong5 soeng6 wui6 ji5`,`线上会议`],[`細聲`,`sai3 seng1`,`小声`],[`提我一聲`,`tai4 ngo5 jat1 seng1`,`提醒我一声`],[`碗碟`,`wun2 dip6`,`碗碟`],[`即晚`,`zik1 maan5`,`当晚`],[`執返好`,`zap1 faan1 hou2`,`收拾好；恢复整洁`],[`提早`,`tai4 zou2`,`提前`],[`雪櫃`,`syut3 gwai6`,`冰箱`],[`過夜`,`gwo3 je6`,`过夜`]],patterns:[[`……嗰陣＋動作`,`指出一段时间或某件事发生的时候。`,`八點到九點嗰陣細聲啲。`],[`動詞＋返好＋物件`,`“返”表示恢复原来的状态，“好”表示事情处理妥当。`,`我會執返好個廚房。`]],cultureNote:`“讲声”是简短告知，“夹时间”是协调时间。留宿、访客和共用空间的约定可以逐项谈；本课对话里的安排是两位室友当面商量的结果。`,practicePrompt:`周末你想邀请朋友来家里，但室友要在房间上课。商量来访时间、音量和厨房收拾，再约定留朋友过夜前先沟通。`}),t({id:`home-recycling`,topicId:`home`,level:2,minutes:13,title:`垃圾分类与回收`,description:`回收物、清洁与收集地点`,speakers:[`住客`,`回收點職員`],phrases:[[`唔該，呢啲膠樽可唔可以拎嚟回收？`,`m4 goi1, ni1 di1 gaau1 zeon1 ho2 m4 ho2 ji5 ling1 lai4 wui4 sau1?`,`请问，这些塑料瓶可以拿来回收吗？`],[`可以，先倒清入面啲嘢，再洗乾淨。`,`ho2 ji5, sin1 dou2 cing1 jap6 min6 di1 je5, zoi3 sai2 gon1 zeng6.`,`可以，先倒净里面的东西，再洗干净。`],[`樽蓋要唔要分開放？`,`zeon1 goi3 jiu3 m4 jiu3 fan1 hoi1 fong3?`,`瓶盖需要分开放吗？`],[`要，呢度有個細箱，專放樽蓋。`,`jiu3, ni1 dou6 jau5 go3 sai3 soeng1, zyun1 fong3 zeon1 goi3.`,`需要，这里有个小箱子，专门放瓶盖。`],[`我仲有啲紙箱同金屬罐，放喺邊？`,`ngo5 zung6 jau5 di1 zi2 soeng1 tung4 gam1 suk6 gun3, fong3 hai2 bin1?`,`我还有一些纸箱和金属罐，放在哪里？`],[`紙箱放左邊，金屬罐放右邊，唔好混埋。`,`zi2 soeng1 fong3 zo2 bin1, gam1 suk6 gun3 fong3 jau6 bin1, m4 hou2 wan6 maai4.`,`纸箱放左边，金属罐放右边，不要混在一起。`],[`下次幾時可以再拎嚟？`,`haa6 ci3 gei2 si4 ho2 ji5 zoi3 ling1 lai4?`,`下次什么时候可以再拿来？`],[`門口有開放時間，你影低先啦。`,`mun4 hau2 jau5 hoi1 fong3 si4 gaan3, nei5 jing2 dai1 sin1 laa1.`,`门口写有开放时间，你先拍下来吧。`],[`呢個紙盒有油，仲收唔收？`,`ni1 go3 zi2 hap6 jau5 jau4, zung6 sau1 m4 sau1?`,`这个纸盒沾了油，还收吗？`],[`我想問吓呢度收邊幾種塑膠。`,`ngo5 soeng2 man6 haa5 ni1 dou6 sau1 bin1 gei2 zung2 sou3 gaau1.`,`我想问问这里收哪几种塑料。`],[`舊電池應該拎去邊個收集點？`,`gau6 din6 ci4 jing1 goi1 ling1 heoi3 bin1 go3 sau1 zaap6 dim2?`,`旧电池应该拿到哪个收集点？`],[`可唔可以畀張分類清單我？`,`ho2 m4 ho2 ji5 bei2 zoeng1 fan1 leoi6 cing1 daan1 ngo5?`,`可以给我一张分类清单吗？`]],words:[[`膠樽`,`gaau1 zeon1`,`塑料瓶`],[`回收`,`wui4 sau1`,`回收`],[`倒清`,`dou2 cing1`,`倒干净`],[`樽蓋`,`zeon1 goi3`,`瓶盖`],[`紙箱`,`zi2 soeng1`,`纸箱`],[`金屬罐`,`gam1 suk6 gun3`,`金属罐`],[`混埋`,`wan6 maai4`,`混在一起`],[`影低`,`jing2 dai1`,`拍照留存`],[`塑膠`,`sou3 gaau1`,`塑料`],[`收集點`,`sau1 zaap6 dim2`,`收集点`]],patterns:[[`先……，再……`,`按顺序说两步处理方法。`,`先倒清入面啲嘢，再洗乾淨。`],[`仲＋動詞＋唔＋動詞？`,`询问在前面提到的情况下，是否仍然能做这件事。`,`呢個紙盒有油，仲收唔收？`]],cultureNote:`“胶樽”指塑料瓶，“影低”指拍下来留存。各回收点接受的物料和摆放方式可能不同，到场后可按物料名称问职员，再看分类标示。`,practicePrompt:`你带着塑料瓶、纸箱和金属罐到回收点。询问哪些能收、瓶盖怎样放，再问沾油纸盒和旧电池该送到哪里。`}),t({id:`services-haircut`,topicId:`services`,level:2,minutes:13,title:`理发：长度与发型`,description:`长度、发型与收费`,speakers:[`顧客`,`髮型師`],phrases:[[`唔該，淨係剪頭髮幾多錢？`,`m4 goi1, zing6 hai6 zin2 tau4 faat3 gei2 do1 cin2?`,`请问，只剪头发多少钱？`],[`我畀個價目表你睇，洗頭另計。`,`ngo5 bei2 go3 gaa3 muk6 biu2 nei5 tai2, sai2 tau4 ling6 gai3.`,`我给你看价目表，洗头另外收费。`],[`好，我想兩邊剪短，頭頂留長啲。`,`hou2, ngo5 soeng2 loeng5 bin1 zin2 dyun2, tau4 ding2 lau4 coeng4 di1.`,`好的，我想两边剪短，头顶留长一点。`],[`兩邊剪到呢個長度，得唔得？`,`loeng5 bin1 zin2 dou3 ni1 go3 coeng4 dou6, dak1 m4 dak1?`,`两边剪到这个长度，可以吗？`],[`得，但前面唔好剪太短，我想遮住額頭。`,`dak1, daan6 cin4 min6 m4 hou2 zin2 taai3 dyun2, ngo5 soeng2 ze1 zyu6 ngaak6 tau4.`,`可以，但前面不要剪太短，我想遮住额头。`],[`明白，我剪少少先，你睇吓啱唔啱。`,`ming4 baak6, ngo5 zin2 siu2 siu2 sin1, nei5 tai2 haa5 ngaam1 m4 ngaam1.`,`明白，我先剪一点，你看看合不合适。`],[`我想要唔使成日整理嘅髮型。`,`ngo5 soeng2 jiu3 m4 sai2 seng4 jat6 zing2 lei5 ge3 faat3 jing4.`,`我想要不用经常打理的发型。`],[`咁我幫你修順啲，吹乾就得。`,`gam2 ngo5 bong1 nei5 sau1 seon6 di1, ceoi1 gon1 zau6 dak1.`,`那我帮你修顺一些，吹干就行。`],[`後面可唔可以再修短少少？`,`hau6 min6 ho2 m4 ho2 ji5 zoi3 sau1 dyun2 siu2 siu2?`,`后面可以再修短一点吗？`],[`我帶咗張相，想剪到差唔多咁。`,`ngo5 daai3 zo2 zoeng1 soeng2, soeng2 zin2 dou3 caa1 m4 do1 gam2.`,`我带了一张照片，想剪得和这个差不多。`],[`可唔可以畀塊鏡我睇吓後面？`,`ho2 m4 ho2 ji5 bei2 faai3 geng3 ngo5 tai2 haa5 hau6 min6?`,`可以拿一面镜子让我看看后面吗？`],[`我唔想染髮，今日剪髮就得。`,`ngo5 m4 soeng2 jim5 faat3, gam1 jat6 zin2 faat3 zau6 dak1.`,`我不想染发，今天只剪发就行。`]],words:[[`淨係`,`zing6 hai6`,`只是；仅仅`],[`價目表`,`gaa3 muk6 biu2`,`价目表`],[`另計`,`ling6 gai3`,`另外计算`],[`剪短`,`zin2 dyun2`,`剪短`],[`頭頂`,`tau4 ding2`,`头顶`],[`長度`,`coeng4 dou6`,`长度`],[`額頭`,`ngaak6 tau4`,`额头`],[`髮型`,`faat3 jing4`,`发型`],[`吹乾`,`ceoi1 gon1`,`吹干`],[`染髮`,`jim5 faat3`,`染发`]],patterns:[[`唔好＋動詞＋太＋形容詞`,`提醒对方不要把程度做过头。`,`前面唔好剪太短。`],[`動詞＋少少＋先`,`先做一小部分，让双方确认后再继续。`,`我剪少少先，你睇吓啱唔啱。`]],cultureNote:`说“修短少少”是请对方略微剪短。比起只说“短一点”，用手指长度、指出头发部位或出示照片，更容易和发型师确认想保留多少。`,practicePrompt:`到理发店先询问剪发是否包含洗头，再说明两边、头顶和前面的长度。剪好后借镜子看后面，请发型师再修短一点。`}),t({id:`services-post-office`,topicId:`services`,level:2,minutes:14,title:`去邮局寄包裹`,description:`邮费、收件地址与追踪号码`,speakers:[`寄件人`,`郵局職員`],phrases:[[`唔該，我想寄呢個包裹去澳門。`,`m4 goi1, ngo5 soeng2 gei3 ni1 go3 baau1 gwo2 heoi3 ou3 mun4.`,`你好，我想把这个包裹寄到澳门。`],[`入面裝住啲咩？`,`jap6 min6 zong1 zyu6 di1 me1?`,`里面装着什么？`],[`幾本書，唔係文件。`,`gei2 bun2 syu1, m4 hai6 man4 gin6.`,`几本书，不是文件。`],[`好，先放上磅，我幫你查郵費。`,`hou2, sin1 fong3 soeng5 bong6, ngo5 bong1 nei5 caa4 jau4 fai3.`,`好的，先放到秤上，我帮你查邮费。`],[`有冇得追蹤件包裹？`,`jau5 mou5 dak1 zeoi1 zung1 gin6 baau1 gwo2?`,`能追踪这个包裹吗？`],[`我幫你揀有追蹤號碼嘅寄法。`,`ngo5 bong1 nei5 gaan2 jau5 zeoi1 zung1 hou6 maa5 ge3 gei3 faat3.`,`我帮你选有追踪号码的邮寄方式。`],[`個地址寫得啱唔啱？使唔使加郵政編碼？`,`go3 dei6 zi2 se2 dak1 ngaam1 m4 ngaam1? sai2 m4 sai2 gaa1 jau4 zing3 pin1 maa5?`,`地址写得对吗？需要加邮政编码吗？`],[`我同你核對收件地址先。`,`ngo5 tung4 nei5 hat6 deoi3 sau1 gin6 dei6 zi2 sin1.`,`我先和你核对收件地址。`],[`可唔可以幫我貼實個盒口？`,`ho2 m4 ho2 ji5 bong1 ngo5 tip3 sat6 go3 hap6 hau2?`,`可以帮我把盒口封牢吗？`],[`寄件人個名同電話填喺邊度？`,`gei3 gin6 jan4 go3 meng2 tung4 din6 waa2 tin4 hai2 bin1 dou6?`,`寄件人的姓名和电话填在哪里？`],[`張收據可唔可以畀我留底？`,`zoeng1 sau1 geoi3 ho2 m4 ho2 ji5 bei2 ngo5 lau4 dai2?`,`可以把收据给我留存吗？`],[`如果仲未送到，我可以點樣查？`,`jyu4 gwo2 zung6 mei6 sung3 dou3, ngo5 ho2 ji5 dim2 joeng6 caa4?`,`如果还没送到，我可以怎样查询？`]],words:[[`包裹`,`baau1 gwo2`,`包裹`],[`裝住`,`zong1 zyu6`,`装着`],[`文件`,`man4 gin6`,`文件`],[`上磅`,`soeng5 bong6`,`上秤`],[`郵費`,`jau4 fai3`,`邮费`],[`追蹤號碼`,`zeoi1 zung1 hou6 maa5`,`追踪号码`],[`寄法`,`gei3 faat3`,`邮寄方式`],[`郵政編碼`,`jau4 zing3 pin1 maa5`,`邮政编码`],[`收件地址`,`sau1 gin6 dei6 zi2`,`收件地址`],[`留底`,`lau4 dai2`,`留存备查`]],patterns:[[`有冇得＋動詞＋賓語？`,`问是否提供某种服务或是否有办法这样做。`,`有冇得追蹤件包裹？`],[`動詞＋得＋啱唔啱？`,`询问动作的结果是否正确。`,`個地址寫得啱唔啱？`]],cultureNote:`“上磅”是放到秤上称重，“留底”是留下资料备查。寄件时把目的地、内装物品和是否需要追踪先说清楚，邮费及可用寄法由柜台核实。`,practicePrompt:`到邮局寄几本书，说明目的地和内装物品，询问带追踪号码的寄法。请职员核对地址，再索取收据并问查询方式。`}),t({id:`services-library`,topicId:`services`,level:2,minutes:14,title:`图书馆借书与续借`,description:`借书、续借与遗失借书证`,speakers:[`讀者`,`圖書館職員`],phrases:[[`你好，我想借呢兩本書。`,`nei5 hou2, ngo5 soeng2 ze3 ni1 loeng5 bun2 syu1.`,`你好，我想借这两本书。`],[`可以，請畀張借書證我。`,`ho2 ji5, cing2 bei2 zoeng1 ze3 syu1 zing3 ngo5.`,`可以，请把借书证给我。`],[`張證唔喺銀包，可能唔見咗。`,`zoeng1 zing3 m4 hai2 ngan4 baau1, ho2 nang4 m4 gin3 zo2.`,`借书证不在钱包里，可能丢了。`],[`咁要先報失，我幫你查吓要點辦。`,`gam2 jiu3 sin1 bou3 sat1, ngo5 bong1 nei5 caa4 haa5 jiu3 dim2 baan6.`,`那要先报失，我帮你查查怎么办。`],[`補領之前，仲可唔可以借書？`,`bou2 ling5 zi1 cin4, zung6 ho2 m4 ho2 ji5 ze3 syu1?`,`补领之前，还可以借书吗？`],[`我先核對你嘅資料，再幫你問借書安排。`,`ngo5 sin1 hat6 deoi3 nei5 ge3 zi1 liu6, zoi3 bong1 nei5 man6 ze3 syu1 on1 paai4.`,`我先核对你的资料，再帮你问借书安排。`],[`另外，屋企有本書聽日到期，我想續借。`,`ling6 ngoi6, uk1 kei2 jau5 bun2 syu1 ting1 jat6 dou3 kei4, ngo5 soeng2 zuk6 ze3.`,`另外，家里有本书明天到期，我想续借。`],[`我幫你查吓可唔可以續借，再確認新嘅到期日。`,`ngo5 bong1 nei5 caa4 haa5 ho2 m4 ho2 ji5 zuk6 ze3, zoi3 kok3 jan6 san1 ge3 dou3 kei4 jat6.`,`我帮你查查能否续借，再确认新的到期日。`],[`我想搵兒童故事書。`,`ngo5 soeng2 wan2 ji4 tung4 gu3 si6 syu1.`,`我想找儿童故事书。`],[`呢本書有人預約咗。`,`ni1 bun2 syu1 jau5 jan4 jyu6 joek3 zo2.`,`这本书有人预约了。`],[`還書箱喺入口隔籬。`,`waan4 syu1 soeng1 hai2 jap6 hau2 gaak3 lei4.`,`还书箱在入口旁边。`],[`我可唔可以用電話查借書紀錄？`,`ngo5 ho2 m4 ho2 ji5 jung6 din6 waa2 caa4 ze3 syu1 gei3 luk6?`,`我可以用电话查询借书记录吗？`]],words:[[`借書證`,`ze3 syu1 zing3`,`借书证`],[`銀包`,`ngan4 baau1`,`钱包`],[`報失`,`bou3 sat1`,`报失`],[`補領`,`bou2 ling5`,`补领`],[`核對`,`hat6 deoi3`,`核对`],[`到期`,`dou3 kei4`,`到期`],[`續借`,`zuk6 ze3`,`续借`],[`到期日`,`dou3 kei4 jat6`,`到期日`],[`兒童故事書`,`ji4 tung4 gu3 si6 syu1`,`儿童故事书`],[`還書箱`,`waan4 syu1 soeng1`,`还书箱`]],patterns:[[`……之前，仲可唔可以……？`,`问某一步尚未办妥时，能否先做另一件事。`,`補領之前，仲可唔可以借書？`],[`另外，……`,`当前面的事还在处理时，提出另一项需要查询的事。`,`另外，屋企有本書聽日到期，我想續借。`]],cultureNote:`“续借”是延长借用时间，“还书”里的“还”读 waan4。借书证遗失、补领和续借可分别向柜台查询，办好续借后再核对新的到期日。`,practicePrompt:`你到图书馆借两本书，却发现借书证丢了。向职员报失，询问补领期间怎样借书，再查家里另一本书能否续借。`})],h=[{id:`first-words`,name:`问候与介绍`,subtitle:`早晨！你好！`,description:`问候、人物介绍、联系方式与礼貌请求`,scene:3},{id:`time-plans`,name:`时间与计划`,subtitle:`聽日幾點見？`,description:`日期、报时、邀约、营业时间与行程安排`,scene:1},{id:`food-drink`,name:`餐饮与点单`,subtitle:`唔該，我要…`,description:`点单、订位、面包蛋糕、下厨与结账`,scene:0},{id:`shopping`,name:`街市与购物`,subtitle:`呢個幾錢呀？`,description:`街市、衣物、网购、家居用品与手机维修`,scene:2},{id:`getting-around`,name:`交通与出行`,subtitle:`請問點去呀？`,description:`问路、公共交通、渡轮、火车与无障碍路线`,scene:1},{id:`home`,name:`居家生活`,subtitle:`我住呢度`,description:`看房、家务、搬家、室友与分类回收`,scene:3},{id:`services`,name:`社区办事`,subtitle:`唔該，想問吓…`,description:`预约、银行、诊所、理发、邮局与图书馆`,scene:2},{id:`friends`,name:`朋友交往`,subtitle:`得閒一齊食飯`,description:`邀请、聚会、电影、运动与宠物话题`,scene:0},{id:`work`,name:`职场沟通`,subtitle:`我哋傾一傾`,description:`同事、会议、面试、文件打印与工作交接`,scene:3},{id:`express-yourself`,name:`聊天与表达`,subtitle:`我覺得…`,description:`经历、观点、分歧、建议与事物描述`,scene:1}],g=[...n,...r,...i,...a,...o,...s,...c,...l,...u,...d,...f,...p,...m],_=new Map(g.map(e=>[e.id,e])),v=new Map(h.map(e=>[e.id,e])),y=new Set(g.flatMap(e=>e.phrases.map(e=>e.hanzi.replace(/[\s，。！？、；：…]/g,``)))).size;new Set(g.flatMap(e=>e.words.map(e=>e.hanzi))).size,g.reduce((e,t)=>e+t.exercises.length,0);export{y as a,v as i,h as n,g as r,_ as t};